"""RMC Active Loop State v1.

Patch 262J1R-Preflight-C11 implements the missing active loop state
object from Algorithm 6 without introducing mutation. The module reconstructs
L_t from the live RMC pipeline report and the local RMC memory dataset so the
system can tell what loop is active, where it is blocked, what has already
completed, which branches remain unresolved, and what the next lawful stage is.

This is not a UI convenience object and it is not an LLM hook. It is the
read-only continuity surface that future gated persistence, promotion, and the
RMC Memory Panel should consume.
"""
from __future__ import annotations

import datetime as _dt
import hashlib as _hashlib
import json as _json
import os as _os
import re as _re
from pathlib import Path as _Path
from typing import Any

ENGINE_VERSION = "rmc_active_loop_state_v1_patch262J1R_preflight_C11"
ENGINE_MODE = "read_only_active_loop_state_reconstruction"
DEFAULT_FORGE_ROOT = _Path("/home/nic/forge")
DEFAULT_DATASET_REL = _Path("memory/rmc_dataset_v1")
DEFAULT_LIVE_REL = _Path("memory/rmc_live_memory_v1")

CANONICAL_STAGE_ORDER = [
    "phase_parser",
    "memory_recaller",
    "trace_spine",
    "candidate_generator",
    "evolutionary_drift_explorer",
    "coherence_scorer",
    "correction_naming",
    "manifest_compiler",
    "output_renderer",
    "echo_validator",
    "memory_writer_dry_run",
    "gated_memory_writer",
]

MUTATING_STAGE_NAMES = {"gated_memory_writer"}


def _utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat()


def _as_dict(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, dict) else {}


def _as_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if value in (None, "", {}):
        return []
    return [value]


def _text(value: Any, limit: int = 800) -> str:
    text = str(value or "").strip()
    text = _re.sub(r"\s+", " ", text)
    return text[:limit]


def _sha(value: Any) -> str:
    return _hashlib.sha256(_json.dumps(value, sort_keys=True, default=str).encode("utf-8", errors="replace")).hexdigest()


def _forge_root(root: str | _Path | None = None) -> _Path:
    if root is not None:
        return _Path(root).expanduser().resolve()
    env_root = _os.environ.get("FORGE_ROOT")
    if env_root:
        return _Path(env_root).expanduser().resolve()
    return DEFAULT_FORGE_ROOT


def _safe_read_json(path: _Path) -> Any:
    try:
        with path.open("r", encoding="utf-8") as handle:
            return _json.load(handle)
    except Exception:
        return None


def _safe_read_jsonl(path: _Path, limit: int = 50) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    try:
        with path.open("r", encoding="utf-8") as handle:
            for line in handle:
                if len(rows) >= limit:
                    break
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = _json.loads(line)
                    if isinstance(obj, dict):
                        rows.append(obj)
                except Exception:
                    continue
    except Exception:
        return []
    return rows


def _iter_files(path: _Path, pattern: str = "*.json", limit: int = 80) -> list[_Path]:
    if not path.exists():
        return []
    try:
        files = [p for p in path.rglob(pattern) if p.is_file()]
        files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
        return files[:limit]
    except Exception:
        return []


def _rel(path: _Path, root: _Path) -> str:
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except Exception:
        return str(path)


def active_loop_boundary() -> dict[str, Any]:
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/active_loop_state.py",
        "implements_rmc_stage": "Active Loop State / L_t",
        "algorithm_reference": "Algorithm 6 continuity object before gated persistence",
        "read_only": True,
        "writes_files": False,
        "writes_rmc_memory": False,
        "writes_identity_vault": False,
        "uses_llm": False,
        "executes_shell": False,
        "queries_chroma": False,
        "reads_db_files": False,
        "mutates_canonical_reference": False,
        "ui_is_authority": False,
        "forge_governs": True,
        "purpose": "Reconstruct current loop continuity from pipeline trace and RMC memory surfaces without mutating state.",
    }


def active_loop_schema_contract() -> dict[str, Any]:
    return {
        "symbol": "L_t",
        "formula": "L_t = reconstruct_active_loop(T_t, μ_t, R_t, V_t, W_t, M_t)",
        "required_fields": [
            "current_loop_id",
            "current_phase",
            "phase_path",
            "open_issues",
            "completed_stages",
            "unresolved_branches",
            "next_expected_step",
            "last_valid_manifest",
            "last_valid_render",
            "last_valid_echo",
            "memory_write_status",
            "user_session_continuity",
        ],
        "persistence_policy": "read_only_reconstruction_in_C11; gated persistence is future work",
        "mutation_policy": "no writes, no approval token consumption, no Identity Vault, no Chroma mutation",
        "design_reason": "Without L_t the pipeline can run per request but cannot know the continuing loop position except by reconstructing from files and reports.",
    }


def _stage_summaries(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    return [s for s in _as_list(pipeline_report.get("stage_summaries")) if isinstance(s, dict)]


def _stage_map(pipeline_report: dict[str, Any]) -> dict[str, dict[str, Any]]:
    return {str(s.get("stage")): s for s in _stage_summaries(pipeline_report) if s.get("stage")}


def _source_reports(pipeline_report: dict[str, Any]) -> dict[str, dict[str, Any]]:
    reports = pipeline_report.get("source_stage_reports")
    if isinstance(reports, dict):
        return {str(k): _as_dict(v) for k, v in reports.items()}
    return {}


def _phase_from_pipeline(pipeline_report: dict[str, Any]) -> dict[str, Any]:
    stages = _stage_map(pipeline_report)
    phase = _as_dict(stages.get("phase_parser"))
    if not phase:
        phase = _as_dict(stages.get("trace_spine"))
    path = _as_list(phase.get("phase_path_hypothesis")) or _as_list(phase.get("phase_path"))
    primary = phase.get("phase_primary") or (path[-1] if path else None)
    return {
        "phase_primary": primary,
        "phase_secondary": _as_list(phase.get("phase_secondary")),
        "phase_path": path,
        "confidence": phase.get("confidence"),
        "confidence_status": phase.get("confidence_status"),
    }


def _completed_stages(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    completed: list[dict[str, Any]] = []
    for s in _stage_summaries(pipeline_report):
        name = str(s.get("stage") or "")
        if not name:
            continue
        status = str(s.get("status") or "").upper()
        if s.get("algorithm_failure"):
            continue
        if name == "gated_memory_writer" and not s.get("memory_write_committed"):
            continue
        if s.get("gate_refusal") and name not in ("gated_memory_writer",):
            continue
        completed.append({
            "stage": name,
            "status": status,
            "evidence": _stage_completion_evidence(name, s),
        })
    return completed


def _stage_completion_evidence(name: str, summary: dict[str, Any]) -> dict[str, Any]:
    keys = {
        "phase_parser": ["phase_primary", "phase_path_hypothesis", "confidence"],
        "memory_recaller": ["active_memory_count", "candidate_nodes_collected"],
        "trace_spine": ["I_t_present", "M_t_present"],
        "candidate_generator": ["C_t_present", "candidate_count"],
        "evolutionary_drift_explorer": ["E_t_present", "bounded_branch_count"],
        "coherence_scorer": ["S_t_present", "selected_candidate_present"],
        "correction_naming": ["chi_t_present", "N_t_present", "stable_naming"],
        "manifest_compiler": ["manifest_packet_present", "manifest_readiness_score"],
        "output_renderer": ["R_t_present", "rendering_allowed"],
        "echo_validator": ["V_t_present", "echo_validation_passed", "echo_score"],
        "memory_writer_dry_run": ["W_t_present", "memory_write_plan_allowed"],
        "gated_memory_writer": ["W_t_commit_present", "memory_write_committed"],
    }.get(name, [])
    return {k: summary.get(k) for k in keys if k in summary}


def _open_issues(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    issues: list[dict[str, Any]] = []
    first = _as_dict(pipeline_report.get("first_blocker"))
    if first:
        issues.append({
            "issue_id": f"blocker_{_sha(first)[:12]}",
            "kind": first.get("kind") or "gate_refusal",
            "stage": first.get("stage"),
            "severity": "critical" if first.get("kind") == "algorithm_failure" else "normal_gate",
            "reason_codes": _as_list(first.get("reason_codes")),
            "failure_code": first.get("failure_code"),
            "recommended_action": _next_from_blocker(first),
        })
    for s in _stage_summaries(pipeline_report):
        if s.get("algorithm_failure") and not any(i.get("stage") == s.get("stage") for i in issues):
            issues.append({
                "issue_id": f"algorithm_{_sha(s)[:12]}",
                "kind": "algorithm_failure",
                "stage": s.get("stage"),
                "severity": "critical",
                "reason_codes": _as_list(s.get("reason_codes")),
                "failure_code": s.get("failure_code"),
                "recommended_action": "stop_and_repair_stage_before_continuing",
            })
    counts = _as_dict(pipeline_report.get("gate_counts"))
    if counts.get("actual_file_write_count", 0) and not pipeline_report.get("memory_write_committed"):
        issues.append({
            "issue_id": "unexpected_write_count_without_commit",
            "kind": "write_integrity_warning",
            "stage": "pipeline_summary",
            "severity": "critical",
            "reason_codes": ["actual_file_write_count_nonzero_without_commit"],
            "recommended_action": "audit_actual_files_written_before_next_patch",
        })
    return issues


def _next_from_blocker(first: dict[str, Any]) -> str:
    stage = str(first.get("stage") or "")
    kind = str(first.get("kind") or "")
    if kind == "algorithm_failure":
        return "repair_algorithm_failure_before_any_gate_or_ui_work"
    mapping = {
        "correction_naming": "run_or_improve_correction_and_naming_until_stable",
        "manifest_compiler": "repair_manifest_inputs_or_required_manifest_fields",
        "output_renderer": "repair_renderer_sentence_plan_or_manifest_renderability",
        "echo_validator": "repair_render_until_echo_preserves_manifest",
        "memory_writer_dry_run": "inspect_W_t_write_plan_refusal_before_commit_attempt",
        "gated_memory_writer": "supply_explicit_approval_only_after_C7_plan_and_echo_pass",
    }
    return mapping.get(stage, "continue_to_next_required_rmc_gate")


def _next_expected_step(pipeline_report: dict[str, Any], open_issues: list[dict[str, Any]]) -> dict[str, Any]:
    if open_issues:
        issue = open_issues[0]
        return {
            "stage": issue.get("stage"),
            "action": issue.get("recommended_action"),
            "reason": issue.get("kind"),
            "may_mutate": False,
        }
    if pipeline_report.get("memory_write_committed"):
        return {
            "stage": "promotion_path",
            "action": "review_committed_memory_for_promotion_queue_or_stable_memory",
            "reason": "memory_commit_completed_under_gate",
            "may_mutate": False,
        }
    return {
        "stage": "gated_memory_writer",
        "action": "optional_commit_only_with_explicit_approval_after_review",
        "reason": "pipeline_ready_no_commit_attempted",
        "may_mutate": False,
    }


def _find_nested_dict(obj: Any, key: str) -> dict[str, Any]:
    if isinstance(obj, dict):
        value = obj.get(key)
        if isinstance(value, dict):
            return value
        for child in obj.values():
            found = _find_nested_dict(child, key)
            if found:
                return found
    elif isinstance(obj, list):
        for child in obj:
            found = _find_nested_dict(child, key)
            if found:
                return found
    return {}


def _find_nested_value(obj: Any, key: str) -> Any:
    if isinstance(obj, dict):
        if key in obj:
            return obj.get(key)
        for child in obj.values():
            found = _find_nested_value(child, key)
            if found not in (None, "", [], {}):
                return found
    elif isinstance(obj, list):
        for child in obj:
            found = _find_nested_value(child, key)
            if found not in (None, "", [], {}):
                return found
    return None


def _last_valid_artifacts(pipeline_report: dict[str, Any]) -> dict[str, Any]:
    reports = _source_reports(pipeline_report)
    manifest_report = reports.get("manifest_compiler", {})
    renderer_report = reports.get("output_renderer", {})
    echo_report = reports.get("echo_validator", {})

    manifest_packet = _as_dict(manifest_report.get("manifest_packet"))
    mu = _as_dict(manifest_packet.get("μ_t"))
    render_packet = _as_dict(renderer_report.get("render_packet"))
    R_t = _as_dict(render_packet.get("R_t"))
    V_t = _as_dict(echo_report.get("V_t"))

    # Fall back to recursive search because endpoint wrappers can nest source reports.
    if not mu:
        mu = _find_nested_dict(pipeline_report, "μ_t")
    if not R_t:
        R_t = _find_nested_dict(pipeline_report, "R_t")
    if not V_t:
        V_t = _find_nested_dict(pipeline_report, "V_t")

    return {
        "last_valid_manifest": _artifact_summary("manifest", mu, required_key="claim"),
        "last_valid_render": _artifact_summary("render", R_t, required_key="rendered_text"),
        "last_valid_echo": _artifact_summary("echo", V_t, required_key="echo_score"),
    }


def _artifact_summary(kind: str, artifact: dict[str, Any], *, required_key: str) -> dict[str, Any] | None:
    if not artifact or required_key not in artifact:
        return None
    if kind == "manifest":
        return {
            "artifact_type": kind,
            "claim_preview": _text(artifact.get("claim"), 220),
            "phase_path": _as_list(artifact.get("phase_path")),
            "confidence": artifact.get("confidence"),
            "novelty": artifact.get("novelty"),
            "projection_status": artifact.get("projection_status"),
            "hash": _sha(artifact)[:18],
        }
    if kind == "render":
        return {
            "artifact_type": kind,
            "rendered_text_preview": _text(artifact.get("rendered_text"), 260),
            "render_mode": artifact.get("render_mode"),
            "hash": _sha(artifact)[:18],
        }
    return {
        "artifact_type": kind,
        "echo_score": artifact.get("echo_score"),
        "echo_validation_passed": artifact.get("echo_validation_passed"),
        "recommended_route": artifact.get("recommended_route"),
        "hash": _sha(artifact)[:18],
    }


def _memory_write_status(pipeline_report: dict[str, Any]) -> dict[str, Any]:
    stages = _stage_map(pipeline_report)
    dry = _as_dict(stages.get("memory_writer_dry_run"))
    gated = _as_dict(stages.get("gated_memory_writer"))
    counts = _as_dict(pipeline_report.get("gate_counts"))
    return {
        "write_plan_allowed": bool(dry.get("memory_write_plan_allowed")),
        "write_eligibility_score": dry.get("write_eligibility_score"),
        "blocked_write_candidate_present": bool(dry.get("blocked_write_candidate_present")),
        "commit_attempted": bool(gated.get("attempted")),
        "memory_write_committed": bool(gated.get("memory_write_committed") or pipeline_report.get("memory_write_committed")),
        "actual_file_write_count": counts.get("actual_file_write_count", 0),
        "actual_files_written": _as_list(pipeline_report.get("actual_files_written")),
        "requires_explicit_approval_token": True,
        "approval_token": "APPROVE_RMC_MEMORY_WRITE",
    }


def _unresolved_branches(pipeline_report: dict[str, Any]) -> list[dict[str, Any]]:
    branches: list[dict[str, Any]] = []
    reports = _source_reports(pipeline_report)
    evo = reports.get("evolutionary_drift_explorer", {})
    for key, route in (("archive_candidates", "archive_or_review"), ("rejected_candidates", "blocked"), ("bounded_branches", "candidate_review")):
        for item in _as_list(evo.get(key))[:8]:
            if isinstance(item, dict):
                branches.append({
                    "branch_id": item.get("candidate_id") or item.get("branch_id") or f"branch_{_sha(item)[:12]}",
                    "source": key,
                    "route": route,
                    "novelty": _find_nested_value(item, "novelty_delta") or item.get("novelty") or item.get("novelty_estimate"),
                    "epsilon_s": _find_nested_value(item, "epsilon_s"),
                    "reason": _text(item.get("reason") or item.get("archive_reason") or item.get("status"), 220),
                })
    if not branches:
        for issue in _open_issues(pipeline_report)[:4]:
            if issue.get("kind") != "algorithm_failure":
                branches.append({
                    "branch_id": f"unresolved_{_sha(issue)[:12]}",
                    "source": "gate_refusal",
                    "route": "return_to_required_gate",
                    "reason": _text(issue.get("recommended_action"), 220),
                    "stage": issue.get("stage"),
                })
    return branches


def _latest_file_summary(root: _Path, folder: _Path, pattern: str = "*.json") -> dict[str, Any] | None:
    files = _iter_files(root / folder, pattern=pattern, limit=1)
    if not files:
        return None
    path = files[0]
    data = _safe_read_json(path)
    return {
        "path": _rel(path, root),
        "modified_utc": _dt.datetime.fromtimestamp(path.stat().st_mtime, tz=_dt.timezone.utc).replace(microsecond=0).isoformat(),
        "sha256_16": _hashlib.sha256(path.read_bytes()).hexdigest()[:16],
        "object_id": _object_id(data, path),
    }


def _object_id(data: Any, path: _Path) -> str:
    if isinstance(data, dict):
        for key in ("event_id", "receipt_id", "memory_node_id", "candidate_id", "review_id", "commit_id"):
            if data.get(key):
                return str(data.get(key))
    return path.stem


def _count_files(path: _Path, pattern: str = "*.json") -> int:
    if not path.exists():
        return 0
    try:
        return sum(1 for p in path.rglob(pattern) if p.is_file())
    except Exception:
        return 0


def _memory_surface(root: _Path) -> dict[str, Any]:
    dataset = root / DEFAULT_DATASET_REL
    live = root / DEFAULT_LIVE_REL
    events_index = dataset / "indexes" / "events_index.jsonl"
    index_rows = _safe_read_jsonl(events_index, limit=500)
    return {
        "forge_root": str(root),
        "dataset_root": str(dataset),
        "dataset_root_exists": dataset.exists(),
        "live_memory_root": str(live),
        "live_memory_root_exists": live.exists(),
        "raw_event_count": _count_files(dataset / "raw_events"),
        "receipt_count": _count_files(dataset / "dataset_receipts"),
        "review_queue_count": _count_files(dataset / "review_queue"),
        "stable_memory_count": _count_files(dataset / "stable_memory"),
        "approved_promotion_count": _count_files(dataset / "approved_promotions"),
        "retrieval_index_exists": events_index.exists(),
        "retrieval_index_row_count": len(index_rows),
        "latest_raw_event": _latest_file_summary(root, DEFAULT_DATASET_REL / "raw_events"),
        "latest_receipt": _latest_file_summary(root, DEFAULT_DATASET_REL / "dataset_receipts"),
        "latest_review_queue_item": _latest_file_summary(root, DEFAULT_DATASET_REL / "review_queue"),
    }


def _user_session_continuity(pipeline_report: dict[str, Any], memory_surface: dict[str, Any]) -> dict[str, Any]:
    phase = _phase_from_pipeline(pipeline_report)
    source = _as_dict(_find_nested_dict(pipeline_report, "input_event")) or _as_dict(_find_nested_dict(pipeline_report, "I_t"))
    raw_input = source.get("x_t_raw_input") or source.get("x_t_raw_input_preview") or _find_nested_value(pipeline_report, "x_t_raw_input_preview")
    key_material = {
        "input": _text(raw_input, 280),
        "phase": phase.get("phase_primary"),
        "path": phase.get("phase_path"),
        "latest_receipt": _as_dict(memory_surface.get("latest_receipt")).get("object_id"),
        "latest_event": _as_dict(memory_surface.get("latest_raw_event")).get("object_id"),
    }
    return {
        "session_key": f"rmc_session_{_sha(key_material)[:18]}",
        "raw_input_preview": _text(raw_input, 260),
        "derived_from_pipeline_trace": True,
        "derived_from_memory_surface": True,
        "continuity_strength": _continuity_strength(memory_surface, phase),
        "continuity_inputs": key_material,
    }


def _continuity_strength(memory_surface: dict[str, Any], phase: dict[str, Any]) -> float:
    score = 0.0
    if memory_surface.get("dataset_root_exists"):
        score += 0.22
    if memory_surface.get("raw_event_count", 0) > 0:
        score += 0.18
    if memory_surface.get("receipt_count", 0) > 0:
        score += 0.18
    if memory_surface.get("retrieval_index_exists"):
        score += 0.16
    if phase.get("phase_primary"):
        score += 0.16
    if phase.get("phase_path"):
        score += 0.10
    return round(min(1.0, score), 6)


def _current_loop_id(pipeline_report: dict[str, Any], continuity: dict[str, Any]) -> str:
    first = _as_dict(pipeline_report.get("first_blocker"))
    phase = _phase_from_pipeline(pipeline_report)
    material = {
        "session_key": continuity.get("session_key"),
        "phase": phase,
        "first_blocker": first,
        "pipeline_verdict": pipeline_report.get("pipeline_verdict"),
    }
    return f"rmcloop_{_sha(material)[:18]}"


def build_active_loop_state(pipeline_report: dict[str, Any], *, forge_root: str | _Path | None = None) -> dict[str, Any]:
    """Reconstruct read-only active loop state from a live pipeline report.

    The function performs only bounded local JSON/file inspection under the Forge
    memory directory. It does not write, mutate, query Chroma, call an LLM, or
    consume approval tokens.
    """
    pipeline = _as_dict(pipeline_report)
    root = _forge_root(forge_root)
    phase = _phase_from_pipeline(pipeline)
    issues = _open_issues(pipeline)
    completed = _completed_stages(pipeline)
    memory = _memory_surface(root)
    continuity = _user_session_continuity(pipeline, memory)
    artifacts = _last_valid_artifacts(pipeline)
    write_status = _memory_write_status(pipeline)
    unresolved = _unresolved_branches(pipeline)
    next_step = _next_expected_step(pipeline, issues)
    loop_id = _current_loop_id(pipeline, continuity)

    L_t = {
        "current_loop_id": loop_id,
        "current_phase": phase.get("phase_primary"),
        "phase_path": phase.get("phase_path"),
        "phase_confidence": phase.get("confidence"),
        "open_issues": issues,
        "completed_stages": completed,
        "unresolved_branches": unresolved,
        "next_expected_step": next_step,
        "last_valid_manifest": artifacts.get("last_valid_manifest"),
        "last_valid_render": artifacts.get("last_valid_render"),
        "last_valid_echo": artifacts.get("last_valid_echo"),
        "memory_write_status": write_status,
        "user_session_continuity": continuity,
        "memory_surface": memory,
    }

    required = active_loop_schema_contract()["required_fields"]
    missing = [field for field in required if field not in L_t]
    status = "OK" if not missing and not any(i.get("kind") == "algorithm_failure" for i in issues) else "BLOCKED"
    result = {
        "status": status,
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "stage": "Active Loop State / L_t",
        "active_loop_state_id": f"activeloop_{_sha(L_t)[:18]}",
        "created_at_utc": _utc_now(),
        "L_t": L_t,
        "schema_contract": active_loop_schema_contract(),
        "missing_required_fields": missing,
        "loop_state_quality": _loop_state_quality(L_t, pipeline),
        "pipeline_link": {
            "pipeline_summary_id": pipeline.get("pipeline_summary_id") or pipeline.get("pipeline_run_id"),
            "pipeline_verdict": pipeline.get("pipeline_verdict"),
            "first_blocker": pipeline.get("first_blocker"),
            "gate_counts": pipeline.get("gate_counts"),
            "source_reports_included": bool(pipeline.get("source_reports_included")),
        },
        "persistence_status": {
            "persisted": False,
            "persistence_allowed_in_this_patch": False,
            "future_stage": "active_loop_state_gated_persistence_after_operator_review",
        },
        "approved_output": False,
        "projection_allowed": False,
        "memory_write_allowed": False,
        "writes_files": False,
        "identity_vault_write": False,
        "rmc_live_memory_write": False,
        "boundary": active_loop_boundary(),
    }
    return result


def _loop_state_quality(L_t: dict[str, Any], pipeline_report: dict[str, Any]) -> dict[str, Any]:
    completed_count = len(_as_list(L_t.get("completed_stages")))
    open_count = len(_as_list(L_t.get("open_issues")))
    unresolved_count = len(_as_list(L_t.get("unresolved_branches")))
    continuity = _as_dict(L_t.get("user_session_continuity")).get("continuity_strength", 0.0)
    has_phase = bool(L_t.get("current_phase"))
    has_next = bool(_as_dict(L_t.get("next_expected_step")).get("stage"))
    score = min(1.0, (completed_count / max(1, len(CANONICAL_STAGE_ORDER))) * 0.42 + float(continuity or 0.0) * 0.36 + (0.12 if has_phase else 0.0) + (0.10 if has_next else 0.0))
    return {
        "score": round(score, 6),
        "completed_stage_count": completed_count,
        "open_issue_count": open_count,
        "unresolved_branch_count": unresolved_count,
        "continuity_strength": continuity,
        "algorithm_failure_count": _as_dict(pipeline_report.get("gate_counts")).get("algorithm_failure_count", 0),
        "gate_refusal_count": _as_dict(pipeline_report.get("gate_counts")).get("gate_refusal_count", 0),
        "quality_label": "usable_read_only_state" if score >= 0.55 else "weak_reconstructed_state",
    }

files.rmc_engine_v1/anchor_store.py:
"""Lazy anchor shards. A question loads the shards whose ingestion phrase it names.

This module does not parse with a regular expression and does not rank by
token overlap. Concept phrases were placed when the shard was built.
The starter set in anchors_187.json is always loaded by the caller.
"""
from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[2] / "data" / "anchors_188"
LIMIT = 16
MAX_SHARDS = 2


def _words(text: str) -> str:
    raw = str(text or "").lower()
    chars = []
    for ch in raw:
        if ("a" <= ch <= "z") or ("0" <= ch <= "9") or ch == " ":
            chars.append(ch)
        else:
            chars.append(" ")
    return " ".join("".join(chars).split())


@lru_cache(maxsize=1)
def _index() -> dict[str, Any]:
    path = ROOT / "index.json"
    if not path.exists():
        return {"surfaces": {}, "shards": {}, "count": 0}
    return json.loads(path.read_text(encoding="utf-8"))


@lru_cache(maxsize=64)
def _shard(name: str) -> list[dict[str, Any]]:
    meta = (_index().get("shards") or {}).get(name) or {}
    rel = str(meta.get("file") or "")
    path = ROOT / rel
    if not rel or not path.exists() or not path.resolve().is_relative_to(ROOT.resolve()):
        return []
    data = json.loads(path.read_text(encoding="utf-8"))
    rows = data.get("anchors") if isinstance(data, dict) else None
    return [row for row in rows or [] if isinstance(row, dict)]


def select_anchors(question: str, limit: int = LIMIT) -> list[dict[str, Any]]:
    """Return at most `limit` trusted rows from the shards the question names."""
    index = _index()
    surfaces = index.get("surfaces") or {}
    blob = " " + _words(question) + " "
    named: list[str] = []
    for phrase in sorted(surfaces, key=len, reverse=True):
        if (" " + phrase + " ") not in blob:
            continue
        for shard in surfaces.get(phrase) or []:
            if shard not in named:
                named.append(shard)
        if len(named) >= MAX_SHARDS:
            break
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for name in named[:MAX_SHARDS]:
        for row in _shard(name):
            text = str(row.get("text") or "")
            if not text or text in seen:
                continue
            seen.add(text)
            rows.append(row)
    rows.sort(key=lambda row: str(row.get("id") or ""))
    return rows[:limit]


def clear_cache() -> None:
    _index.cache_clear()
    _shard.cache_clear()

files.rmc_engine_v1/athena_props.py:
"""4.9.246 Athena property resolution. No model.

A missing kāraka property (formula, SMILES, mass, height, width, depth, radius, GM) is filled only when two
independent Tier-A publishers agree. Wikipedia is never a publisher. Wikidata is never a publisher. The phone
fetches CORS-open public APIs and hands the raw documents here; CPython may fetch the same URLs for the Home PC
runner and the tests. Admitted rows are on-device clauses. Nothing here writes to Supabase.
"""
from __future__ import annotations

import json
import re
import urllib.parse
import urllib.request
from pathlib import Path
from typing import Any, Callable

SCHEMA = "forge.sim_property/v1"
REL = 0.15  # identical constants (a chemical mass, a body's GM): agree within 15 percent
MASS_REL = 0.005  # chemical masses agree within 0.5 percent (PubChem average vs ChEBI exact)
# Museum specimens of one subtype are not identical constants. Publisher medians may differ by this much
# and still be the same kind (a 110 cm and a 132 cm example of one kind).
ARTIFACT_REL = 0.25
BROAD_SPREAD = 0.45  # a bare noun whose heights scatter more than this is more than one kind
UA = "forge-mobile/4.9.249"
Http = Callable[[str], str]

PUBLISHERS = {
    "pubchem": {"publisher": "NLM", "host": "pubchem.ncbi.nlm.nih.gov", "license": "public-domain",
                "license_url": "https://www.nlm.nih.gov/copyright.html"},
    "chebi": {"publisher": "EMBL-EBI", "host": "www.ebi.ac.uk", "license": "CC BY 4.0",
              "license_url": "https://creativecommons.org/licenses/by/4.0/"},
    "vam": {"publisher": "Victoria and Albert Museum", "host": "api.vam.ac.uk", "license": "CC BY 4.0",
            "license_url": "https://www.vam.ac.uk/info/va-api"},
    "artic": {"publisher": "Art Institute of Chicago", "host": "api.artic.edu", "license": "CC0 1.0",
              "license_url": "https://creativecommons.org/publicdomain/zero/1.0/"},
    "cleveland": {"publisher": "Cleveland Museum of Art", "host": "openaccess-api.clevelandart.org", "license": "CC0 1.0",
                  "license_url": "https://www.clevelandart.org/open-access"},
    "gent": {"publisher": "Design Museum Gent", "host": "data.designmuseumgent.be", "license": "open-data",
             "license_url": "https://data.designmuseumgent.be/v2/"},
    "smg": {"publisher": "Science Museum Group", "host": "collection.sciencemuseumgroup.org.uk",
            "license": "Open Government Licence v3", "license_url": "https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/"},
    "toolbox": {"publisher": "Engineering Toolbox", "host": "www.engineeringtoolbox.com", "license": "cited-handbook",
                "license_url": "https://www.engineeringtoolbox.com/wood-density-d_40.html"},
    "wooddb": {"publisher": "The Wood Database, citing USDA FPL Wood Handbook", "host": "www.wood-database.com",
               "license": "cited-handbook", "license_url": "https://www.wood-database.com/"},
    "imcce": {"publisher": "IMCCE", "host": "ssp.imcce.fr", "license": "public-research",
              "license_url": "https://ssp.imcce.fr/webservices/ssodnet/"},
    "jpl": {"publisher": "NASA/JPL", "host": "ssd-api.jpl.nasa.gov", "license": "public-domain",
            "license_url": "https://www.jpl.nasa.gov/jpl-image-use-policy", "cors": False},
    "nhtsa": {"publisher": "NHTSA", "host": "vpic.nhtsa.dot.gov", "license": "public-domain",
              "license_url": "https://vpic.nhtsa.dot.gov/api/", "cors": True},
    "epa": {"publisher": "US EPA", "host": "www.fueleconomy.gov", "license": "public-domain",
            "license_url": "https://www.fueleconomy.gov/feg/ws/", "cors": True},
}

BLOCKED_HOSTS = ("wikipedia.org", "wikidata.org", "wikimedia.org")


def _http(url: str, timeout: float = 4.0) -> str:
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "application/json", "Origin": "https://bogaertn.github.io"})
    with urllib.request.urlopen(req, timeout=timeout) as res:
        return res.read().decode("utf-8", errors="replace")


def _host(url: str) -> str:
    try:
        return urllib.parse.urlparse(url).hostname or ""
    except Exception:
        return ""


def _blocked(url: str) -> bool:
    h = _host(url)
    return any(h == b or h.endswith("." + b) for b in BLOCKED_HOSTS)


def _pub(sid: str, url: str) -> dict[str, Any]:
    row = dict(PUBLISHERS[sid])
    row.update(id=sid, url=url)
    return row


def _agree_num(a: float, b: float, rel: float) -> bool:
    scale = max(abs(a), abs(b), 1e-12)
    return abs(a - b) / scale <= rel


def _fact(head: str, prop: str, value: Any, unit: str | None, publishers: list[dict[str, Any]]) -> dict[str, Any]:
    hosts = {_host(p.get("url") or "") or p.get("host") for p in publishers}
    return {
        "schema": SCHEMA, "head": head.lower(), "property": prop, "value": value, "unit": unit,
        "publishers": publishers, "hosts": sorted(h for h in hosts if h),
        "calls_llm": False, "supabase_write": False,
    }


def gilligan(facts: list[dict[str, Any]]) -> dict[str, Any]:
    """Two independent non-Wikipedia hosts, or the row is not admitted."""
    ok, held = [], []
    for f in facts:
        pubs = f.get("publishers") or []
        hosts = []
        for p in pubs:
            url = str(p.get("url") or "")
            if _blocked(url):
                continue
            h = _host(url) or str(p.get("host") or "")
            if h and h not in hosts:
                hosts.append(h)
        if len(hosts) >= 2 and len({p.get("publisher") for p in pubs}) >= 2:
            ok.append(f)
        else:
            held.append({"head": f.get("head"), "property": f.get("property"), "reason": "two_publishers_required", "hosts": hosts})
    return {"ok": ok, "held": held, "calls_llm": False, "supabase_write": False}


# ---------------------------------------------------------------- chemistry: PubChem (NLM) and ChEBI (EMBL-EBI)

def pubchem_url(name: str) -> str:
    q = urllib.parse.quote(name)
    return ("https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/" + q
            + "/property/MolecularFormula,MolecularWeight,InChIKey,IsomericSMILES/JSON")


def chebi_search_url(name: str) -> str:
    return "https://www.ebi.ac.uk/ols4/api/search?ontology=chebi&exact=true&q=" + urllib.parse.quote(name)


def chebi_term_url(obo: str) -> str:
    return "https://www.ebi.ac.uk/ols4/api/ontologies/chebi/terms?obo_id=" + urllib.parse.quote(obo)


def parse_pubchem(name: str, raw: str) -> dict[str, Any] | None:
    try:
        props = ((json.loads(raw).get("PropertyTable") or {}).get("Properties") or [None])[0]
    except Exception:
        return None
    if not isinstance(props, dict) or not props.get("MolecularFormula"):
        return None
    cid = props.get("CID")
    url = f"https://pubchem.ncbi.nlm.nih.gov/compound/{cid}" if cid else pubchem_url(name)
    return {"formula": str(props["MolecularFormula"]), "mass": float(props["MolecularWeight"]),
            "inchikey": props.get("InChIKey"),
            "smiles": props.get("IsomericSMILES") or props.get("CanonicalSMILES") or props.get("ConnectivitySMILES") or props.get("SMILES"),
            "url": url}


def parse_chebi_search(raw: str) -> str | None:
    try:
        docs = ((json.loads(raw).get("response") or {}).get("docs") or [])
    except Exception:
        return None
    for d in docs:
        obo = str(d.get("obo_id") or "")
        if obo.startswith("CHEBI:") and d.get("label"):
            return obo
    return None


def parse_chebi_term(raw: str) -> dict[str, Any] | None:
    try:
        terms = ((json.loads(raw).get("_embedded") or {}).get("terms") or [])
    except Exception:
        return None
    if not terms:
        return None
    ann = terms[0].get("annotation") or {}
    formula = (ann.get("generalized_empirical_formula") or [None])[0]
    mass = (ann.get("mass") or [None])[0]
    if not formula or mass is None:
        return None
    obo = terms[0].get("obo_id") or ""
    return {"formula": str(formula), "mass": float(mass), "inchikey": (ann.get("inchi_key_string") or [None])[0],
            "smiles": (ann.get("smiles_string") or [None])[0],
            "url": "https://www.ebi.ac.uk/chebi/searchId.do?chebiId=" + str(obo)}


def chemical_decision(name: str, pub: dict[str, Any] | None, che: dict[str, Any] | None, err_p: str | None = None, err_c: str | None = None) -> dict[str, Any]:
    """One decision for a fetched pair: missing, disagreement, or two-publisher agreement."""
    if not pub or not che:
        return {"ok": [], "held": [{"head": name.lower(), "property": "formula", "reason": "publisher_missing",
                                    "pubchem": bool(pub), "chebi": bool(che), "errors": [err_p, err_c]}],
                "calls_llm": False, "supabase_write": False}
    if str(pub.get("formula")) != str(che.get("formula")) or (
            pub.get("mass") is not None and che.get("mass") is not None and not _agree_num(float(pub["mass"]), float(che["mass"]), MASS_REL)):
        return {"ok": [], "held": [{"head": name.lower(), "property": "formula", "reason": "publishers_disagree",
                                    "pubchem": pub.get("formula"), "chebi": che.get("formula")}],
                "calls_llm": False, "supabase_write": False}
    return gilligan(agree_chemical(name, pub, che))


def agree_chemical(name: str, pub: dict[str, Any], che: dict[str, Any]) -> list[dict[str, Any]]:
    if str(pub.get("formula")) != str(che.get("formula")):
        return []
    if not _agree_num(float(pub["mass"]), float(che["mass"]), MASS_REL):
        return []
    if pub.get("inchikey") and che.get("inchikey") and pub["inchikey"] != che["inchikey"]:
        return []
    pubs = [_pub("pubchem", pub["url"]), _pub("chebi", che["url"])]
    head = name.lower()
    rows = [
        _fact(head, "formula", pub["formula"], None, pubs),
        _fact(head, "mass_da", round((float(pub["mass"]) + float(che["mass"])) / 2.0, 4), "Da", pubs),
    ]
    smiles = pub.get("smiles") or che.get("smiles")
    if smiles:
        rows.append(_fact(head, "smiles", smiles, None, pubs))
    return rows


def fetch_chemical(name: str, http: Http = _http) -> dict[str, Any]:
    """Live PubChem + ChEBI. Returns gilligan() on the agreed rows, or a hold naming the gap."""
    try:
        pub = parse_pubchem(name, http(pubchem_url(name)))
    except Exception as e:
        pub = None
        err_p = str(e)[:160]
    else:
        err_p = None
    che = None
    err_c = None
    try:
        obo = parse_chebi_search(http(chebi_search_url(name)))
        if obo:
            che = parse_chebi_term(http(chebi_term_url(obo)))
    except Exception as e:
        err_c = str(e)[:160]
    return chemical_decision(name, pub, che, err_p, err_c)


# ---------------------------------------------------------------- physical objects: two museums, measured records only

_SKIP = re.compile(r"\b(design|drawing|sketch|miniature|portrait|painting|print|photograph|study)\b", re.I)


def _cm(value: float, unit: str) -> float | None:
    u = (unit or "").lower()
    if u in ("cm", "centimeter", "centimeters"):
        return value / 100.0
    if u in ("mm", "millimeter", "millimeters"):
        return value / 1000.0
    if u in ("m", "meter", "meters", "metre", "metres"):
        return value
    if u in ("in", "inch", "inches"):
        return value * 0.0254
    if u in ("kg", "kilogram", "kilograms"):
        return value
    return None


def _median(xs: list[float]) -> float | None:
    if not xs:
        return None
    ys = sorted(xs)
    n = len(ys)
    return ys[n // 2] if n % 2 else (ys[n // 2 - 1] + ys[n // 2]) / 2.0


def museum_measures(records: list[dict[str, Any]], head: str) -> dict[str, float]:
    """Median height/width/depth/mass in metres and kilograms. Records whose title is a picture of the thing are dropped.
    `head` is the patient's head noun from the kāraka frame. No noun is special-cased."""
    want = head.lower()
    buckets: dict[str, list[float]] = {"height": [], "width": [], "depth": [], "mass": []}
    for rec in records:
        title = " ".join(str(rec.get(k) or "") for k in ("title", "objectType", "classification"))
        if want not in title.lower() or _SKIP.search(title):
            continue
        dims = rec.get("dimensions") or []
        if isinstance(dims, str):
            continue
        for d in dims:
            if not isinstance(d, dict):
                continue
            part = str(d.get("part") or "").lower()
            if part and part not in ("", "overall", "object"):
                continue
            name = str(d.get("dimension") or d.get("type") or "").lower()
            try:
                val = float(d.get("value"))
            except (TypeError, ValueError):
                continue
            unit = str(d.get("unit") or "")
            metres = _cm(val, unit)
            if metres is None:
                continue
            if name in ("height", "h", "højde") and unit.lower() not in ("kg", "kilogram", "kilograms"):
                buckets["height"].append(metres)
            elif name in ("width", "w", "bredde") and unit.lower() not in ("kg",):
                buckets["width"].append(metres)
            elif name in ("depth", "d", "dybde") and unit.lower() not in ("kg",):
                buckets["depth"].append(metres)
            elif name in ("weight", "mass") or unit.lower() in ("kg", "kilogram", "kilograms"):
                buckets["mass"].append(val if unit.lower() in ("kg", "kilogram", "kilograms") else metres)
    return {k: v for k, v in ((_k, _median(_v)) for _k, _v in buckets.items()) if v is not None}


def agree_objects(head: str, sides: list[tuple[str, str, dict[str, float]]], rel: float = REL) -> list[dict[str, Any]]:
    """sides: (publisher id, url, measures). A quantity is kept when at least two publishers measured it and they agree."""
    by_prop: dict[str, list[tuple[str, str, float]]] = {}
    for sid, url, measures in sides:
        for prop, val in measures.items():
            by_prop.setdefault(prop, []).append((sid, url, val))
    rows = []
    for prop, vals in by_prop.items():
        if len(vals) < 2:
            continue
        nums = [v for _, _, v in vals]
        if max(nums) <= 0 or not all(_agree_num(nums[0], n, rel) for n in nums[1:]):
            continue
        mean = sum(nums) / len(nums)
        pubs = [_pub(sid, url) for sid, url, _ in vals]
        unit = "kg" if prop == "mass" else "m"
        rows.append(_fact(head, prop, round(mean, 4), unit, pubs))
    return rows


def _content_words(phrase: str) -> list[str]:
    stop = {"a", "an", "the", "of", "and", "or"}
    return [w for w in re.findall(r"[a-z0-9]+", phrase.lower()) if w not in stop and len(w) > 1]


def _blob(rec: dict[str, Any]) -> str:
    return " ".join(str(rec.get(k) or "") for k in ("title", "objectType", "classification", "description")).lower()


def _num_text(value: Any) -> float | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    s = str(value or "").strip()
    m = re.fullmatch(r"(\d+)\s+(\d+)\s*/\s*(\d+)", s)
    if m:
        return float(m.group(1)) + float(m.group(2)) / float(m.group(3))
    m = re.fullmatch(r"(\d+)\s*/\s*(\d+)", s)
    if m:
        return float(m.group(1)) / float(m.group(2))
    try:
        return float(s)
    except (TypeError, ValueError):
        return None


def _from_dim_text(text: str) -> dict[str, float]:
    """Prose dimensions. A frame, plate, or sheet size is not the object."""
    out: dict[str, float] = {}
    for part in re.split(r"[;\n]", str(text or "")):
        if re.search(r"\b(framed|image|plate|sheet|mount|diam)\b", part, re.I):
            continue
        labeled = False
        for m in re.finditer(r"\b(height|width|depth|h|w|d)\.?\s*:?\s*(\d+(?:\.\d+)?)\s*cm\b", part, re.I):
            key = {"h": "height", "w": "width", "d": "depth"}.get(m.group(1).lower()[:1], "")
            if key:
                out.setdefault(key, float(m.group(2)) / 100.0)
                labeled = True
        if labeled:
            continue
        m = re.search(r"(\d+(?:\.\d+)?)\s*[×x]\s*(\d+(?:\.\d+)?)(?:\s*[×x]\s*(\d+(?:\.\d+)?))?\s*cm", part, re.I)
        if not m:
            continue
        out.setdefault("height", float(m.group(1)) / 100.0)
        out.setdefault("width", float(m.group(2)) / 100.0)
        if m.group(3):
            out.setdefault("depth", float(m.group(3)) / 100.0)
    return out


# Densities live in physical_defaults.json with two handbook figures and a class
# (wood, metal, bulk, soft). A pair is used only when the two figures agree within REL.
_WORD_ALIAS = {
    "wooden": "oak", "wood": "oak", "timber": "oak",
    "aluminium": "aluminum", "aluminum": "aluminum",
    "plastic": "polyethylene", "polymer": "polyethylene", "polyethylene": "polyethylene",
    "saltwater": "seawater", "brine": "seawater",
}


def _material_table() -> dict[str, Any]:
    from rmc_engine_v1.sim_scene import defaults
    return (defaults().get("materials") or {})


def _material_rows() -> dict[str, dict[str, Any]]:
    return dict((_material_table().get("rows") or {}))
# Board thickness is physical_defaults.materials.board_m (18 mm and 19.05 mm).


def _one_record(rec: dict[str, Any]) -> dict[str, float]:
    """Overall height, width, depth (m) and mass (kg). A leg or a crate is skipped; closed/overall counts."""
    out: dict[str, float] = {}
    dims = rec.get("dimensions") or []
    if isinstance(dims, str):
        out.update(_from_dim_text(dims))
        dims = []
    whole = {"", "overall", "object", "closed"}
    for d in dims:
        if not isinstance(d, dict):
            continue
        part = str(d.get("part") or "").lower()
        if part and part not in whole:
            continue
        name = str(d.get("dimension") or d.get("type") or "").lower()
        val = _num_text(d.get("value"))
        if val is None:
            continue
        unit = str(d.get("unit") or "")
        metres = _cm(val, unit)
        if metres is None:
            continue
        if name in ("height", "h", "hoogte") and unit.lower() not in ("kg", "kilogram", "kilograms", "lb", "lbs"):
            out.setdefault("height", metres)
        elif name in ("width", "w", "breedde") and unit.lower() not in ("kg", "kilogram", "kilograms"):
            out.setdefault("width", metres)
        elif name in ("depth", "d", "diepte") and unit.lower() not in ("kg", "kilogram", "kilograms"):
            out.setdefault("depth", metres)
        elif name in ("weight", "mass", "gewicht") or unit.lower() in ("kg", "kilogram", "kilograms"):
            if unit.lower() in ("kg", "kilogram", "kilograms") and val > 0:
                out.setdefault("mass", val)
    for k, v in _from_dim_text(str(rec.get("dimension_text") or "")).items():
        out.setdefault(k, v)
    return out


def _species(blob: str) -> list[str]:
    """Material keys named in a record. Longer names win ('cast iron' before 'iron')."""
    rows = _material_rows()
    found: list[str] = []
    text = blob.lower()
    names = sorted(set(list(rows) + list(_WORD_ALIAS)), key=len, reverse=True)
    for word in names:
        if re.search(r"\b" + re.escape(word) + r"\b", text):
            key = _WORD_ALIAS.get(word, word)
            if key in rows and key not in found:
                found.append(key)
    return found


def _density_of(key: str) -> float | None:
    row = _material_rows().get(key) or {}
    pair = row.get("rho") or []
    if len(pair) != 2 or not _agree_num(float(pair[0]), float(pair[1]), REL):
        return None
    return (float(pair[0]) + float(pair[1])) / 2.0


def _board_m() -> float:
    pair = (_material_table().get("board_m") or [0.018, 0.01905])
    return (float(pair[0]) + float(pair[1])) / 2.0


def _class_of(key: str) -> str:
    return str((_material_rows().get(key) or {}).get("class") or "")


def _shell_mass(measures: dict[str, float], density: float, board: float | None = None) -> float | None:
    """Hollow carcass: surface area times agreed board thickness times density."""
    h, w, d = measures.get("height"), measures.get("width"), measures.get("depth")
    if not h or not w or not d or h <= 0 or w <= 0 or d <= 0 or density <= 0:
        return None
    area = 2.0 * (h * w + h * d + w * d)
    return area * (board if board is not None else _board_m()) * density


def _mass_from_materials(measures: dict[str, float], keys: list[str]) -> float | None:
    """Wood shell, plus a metal frame when the record names a metal, else a bulk volume.
    Fabric and any pair whose handbooks disagree are left out."""
    woods = [k for k in keys if _class_of(k) == "wood" and _density_of(k)]
    metals = [k for k in keys if _class_of(k) == "metal" and _density_of(k)]
    bulks = [k for k in keys if _class_of(k) in ("bulk", "soft") and _density_of(k)]
    h, w, d = measures.get("height"), measures.get("width"), measures.get("depth")
    board = _board_m()
    wood_rho = (sum(_density_of(k) or 0 for k in woods) / len(woods)) if woods else None
    metal_rho = (sum(_density_of(k) or 0 for k in metals) / len(metals)) if metals else None
    if wood_rho and h and w and d:
        shell = _shell_mass(measures, wood_rho, board) or 0.0
        if metal_rho:
            # Four corner posts of square board section, plus one face plate of board thickness.
            posts = 4.0 * float(h) * board * board * metal_rho
            plate = float(h) * float(w) * board * metal_rho
            return shell + posts + plate
        return shell
    if metal_rho and not wood_rho:
        return _shell_mass(measures, metal_rho, board)
    if bulks and h and w and d and not woods and not metals:
        rho = sum(_density_of(k) or 0 for k in bulks) / len(bulks)
        return float(h) * float(w) * float(d) * rho
    return None


def _spread(xs: list[float]) -> float | None:
    if len(xs) < 2:
        return None
    med = _median(xs)
    if not med:
        return None
    return (max(xs) - min(xs)) / med


def resolve_objects(phrase: str, sides: list[dict[str, Any]], head: str | None = None, specific: bool = False) -> dict[str, Any]:
    """Full noun phrase, not a stripped head. A bare noun whose heights scatter is underspecified.
    A specific phrase keeps the publisher medians when they lie within ARTIFACT_REL, and a missing mass
    is the wood shell of the agreed box when two handbooks agree on the named wood.
    """
    words = _content_words(phrase)
    label = (head or " ".join(words) or phrase).strip().lower()
    empty = {"ok": [], "ask": False, "held": [{"head": label, "property": "dimensions", "reason": "two_publishers_required"}],
             "calls_llm": False, "supabase_write": False}
    if not words:
        return empty
    per: list[tuple[str, str, list[dict[str, Any]]]] = []
    heights: list[float] = []
    for side in sides:
        if not isinstance(side, dict):
            continue
        matched = []
        for rec in side.get("records") or []:
            if not isinstance(rec, dict):
                continue
            # A picture is named in the title. A real object's description may mention a drawing of it.
            if _SKIP.search((str(rec.get("title") or "") + " " + str(rec.get("objectType") or "")).lower()):
                continue
            blob = (_blob(rec) + " " + " ".join(str(x) for x in (rec.get("materials") or []))).lower()
            if any(w not in blob for w in words):
                continue
            one = _one_record(rec)
            if not one:
                continue
            one["species"] = _species(blob)
            matched.append(one)
            if "height" in one:
                heights.append(one["height"])
        if matched:
            per.append((str(side.get("id") or ""), str(side.get("url") or ""), matched))
    spread = _spread(heights)
    if not specific and len(words) == 1 and spread is not None and spread > BROAD_SPREAD:
        return {"ok": [], "ask": True, "word": words[0], "spread": round(spread, 4),
                "held": [{"head": label, "property": "kind", "reason": "underspecified", "spread": round(spread, 4)}],
                "calls_llm": False, "supabase_write": False}
    # A search also returns parts and pictures. Keep the cluster of full-size specimens:
    # the agreeing group whose heights are the larger ones, not a handful of mechanisms.
    sized = [(sid, url, m) for sid, url, matched in per for m in matched if isinstance(m.get("height"), (int, float))]
    if len(sized) >= 2:
        best: list[tuple[str, str, dict[str, Any]]] = []
        best_key: tuple[int, float] = (0, 0.0)
        for _, _, pivot in sized:
            group = [row for row in sized if _agree_num(row[2]["height"], pivot["height"], 0.35)]
            pubs = len({row[0] for row in group})
            if pubs < 2:
                continue
            key = (pubs, _median([row[2]["height"] for row in group]) or 0.0)
            if key > best_key:
                best, best_key = group, key
        if best:
            grouped: dict[tuple[str, str], list[dict[str, Any]]] = {}
            for sid, url, m in best:
                grouped.setdefault((sid, url), []).append(m)
            per = [(sid, url, ms) for (sid, url), ms in grouped.items()]
    medians: list[tuple[str, str, dict[str, float]]] = []
    species_all: list[str] = []
    for sid, url, matched in per:
        med: dict[str, float] = {}
        for prop in ("height", "width", "depth", "mass"):
            xs = [m[prop] for m in matched if isinstance(m.get(prop), (int, float))]
            got = _median(xs)
            if got is not None:
                med[prop] = got
        for m in matched:
            for s in m.get("species") or []:
                if s not in species_all:
                    species_all.append(s)
        if med:
            medians.append((sid, url, med))
    rows = agree_objects(label, medians, ARTIFACT_REL) if len(medians) >= 2 else []
    spoken = " ".join(words)
    if rows and not any(r["property"] == "mass" for r in rows):
        by = {r["property"]: r for r in rows}
        geom = {k: by[k]["value"] for k in ("height", "width", "depth") if k in by}
        # A shell mass needs a depth that two publishers already agreed. One publisher's depth is not copied across.
        mass = _mass_from_materials(geom, species_all) if "depth" in by and "height" in by and "width" in by else None
        if mass and mass > 0:
            pubs: list[dict[str, Any]] = []
            seen: set[tuple[Any, Any]] = set()
            for prop in ("height", "width", "depth"):
                for p in by[prop]["publishers"]:
                    ident = (p.get("id"), p.get("url"))
                    if ident in seen:
                        continue
                    seen.add(ident)
                    pubs.append(p)
            pubs.append(_pub("toolbox", PUBLISHERS["toolbox"]["license_url"]))
            pubs.append(_pub("wooddb", PUBLISHERS["wooddb"]["license_url"]))
            rows.append(_fact(label, "mass", round(mass, 1), "kg", pubs))
    for row in rows:
        row["average"] = True
        row["phrase"] = spoken
        row["head"] = label
    if not rows or not any(r["property"] == "mass" for r in rows) or not any(r["property"] == "height" for r in rows):
        return empty
    packed = gilligan(rows)
    packed["ask"] = False
    packed["word"] = spoken
    return packed


def fetch_objects(head: str, http: Http = _http) -> dict[str, Any]:
    q = urllib.parse.quote(head)
    sides: list[tuple[str, str, dict[str, float]]] = []
    vam_url = f"https://api.vam.ac.uk/v2/objects/search?q={q}&page_size=8"
    try:
        search = json.loads(http(vam_url))
        recs = []
        for hit in (search.get("records") or [])[:6]:
            sysn = hit.get("systemNumber")
            if not sysn:
                continue
            obj = json.loads(http(f"https://api.vam.ac.uk/v2/object/{urllib.parse.quote(str(sysn))}"))
            rec = obj.get("record") or {}
            dims = []
            for d in rec.get("dimensions") or []:
                if str(d.get("part") or "").lower() in ("crate",):
                    continue
                dims.append({"dimension": d.get("dimension"), "value": d.get("value"), "unit": d.get("unit"), "part": d.get("part") or ""})
            recs.append({"title": rec.get("_primaryTitle") or hit.get("_primaryTitle") or "",
                         "objectType": rec.get("objectType") or hit.get("objectType") or "",
                         "dimensions": dims})
        got = museum_measures(recs, head)
        if got:
            sides.append(("vam", vam_url, got))
    except Exception:
        pass
    artic_url = ("https://api.artic.edu/api/v1/artworks/search?q=" + q
                 + "&limit=20&fields=id,title,dimensions,classification_title,artwork_type_title")
    try:
        data = json.loads(http(artic_url)).get("data") or []
        recs = []
        for a in data:
            text = str(a.get("dimensions") or "")
            # "128.9 × 143.2 cm" or "H. 50 cm"
            nums = re.findall(r"(\d+(?:\.\d+)?)\s*(?:×|x)?\s*(?:cm|mm)?", text)
            # Prefer explicit centimetre pairs in the first measurement clause.
            cm = re.findall(r"(\d+(?:\.\d+)?)\s*×\s*(\d+(?:\.\d+)?)(?:\s*×\s*(\d+(?:\.\d+)?))?\s*cm", text)
            dims = []
            if cm:
                h, w, d = cm[0]
                dims.append({"dimension": "Height", "value": h, "unit": "cm", "part": ""})
                dims.append({"dimension": "Width", "value": w, "unit": "cm", "part": ""})
                if d:
                    dims.append({"dimension": "Depth", "value": d, "unit": "cm", "part": ""})
            elif nums:
                continue
            recs.append({"title": a.get("title") or "", "objectType": a.get("classification_title") or "",
                         "classification": a.get("artwork_type_title") or "", "dimensions": dims})
        got = museum_measures(recs, head)
        if got:
            sides.append(("artic", artic_url, got))
    except Exception:
        pass
    if len(sides) < 2:
        return {"ok": [], "held": [{"head": head.lower(), "property": "dimensions", "reason": "two_publishers_required",
                                    "publishers": [s[0] for s in sides]}], "calls_llm": False, "supabase_write": False}
    return gilligan(agree_objects(head, sides))


# ---------------------------------------------------------------- celestial body: IMCCE ssoCard and NASA/JPL SBDB (asteroids / dwarf planets)

def parse_ssocard(raw: str, url: str) -> dict[str, Any] | None:
    """Radius and mass from an IMCCE ssoCard, when that card publishes both."""
    try:
        card = json.loads(raw)
    except Exception:
        return None
    phys = ((card.get("parameters") or {}).get("physical") or {})
    diam = (phys.get("diameter") or {}).get("value")
    mass = (phys.get("mass") or {}).get("value")
    if not diam or not mass:
        return None
    return {"radius_m": float(diam) * 500.0, "mass_kg": float(mass), "url": url,
            "type": str(card.get("type") or ""), "name": str(card.get("name") or "")}


def parse_quaero_sso(raw: str) -> dict[str, Any] | None:
    """Identity only. Quaero names a satellite; it does not publish mass or radius."""
    try:
        data = json.loads(raw)
    except Exception:
        return None
    rows = data.get("data") if isinstance(data, dict) else None
    if isinstance(data, dict) and data.get("type"):
        rows = [data]
    if not rows:
        return None
    row = rows[0]
    return {"id": row.get("id"), "name": row.get("name"), "type": row.get("type"),
            "has_mass": False, "has_radius": False}


def agree_body(name: str, sides: list[dict[str, Any]]) -> dict[str, Any]:
    """sides: publisher rows with radius_m and mass_kg. Two different non-blocked hosts, or hold."""
    usable = []
    for side in sides:
        if not isinstance(side, dict) or side.get("radius_m") is None or side.get("mass_kg") is None:
            continue
        url = str(side.get("url") or "")
        if _blocked(url):
            continue
        usable.append(side)
    hosts = []
    for side in usable:
        h = _host(str(side.get("url") or "")) or str(side.get("host") or "")
        if h and h not in hosts:
            hosts.append(h)
    if len(hosts) < 2:
        return {"ok": [], "held": [{"head": name.lower(), "property": "radius", "reason": "two_publishers_required",
                                    "hosts": hosts, "cors_note": "a catalog counts only when the phone can read it"}],
                "calls_llm": False, "supabase_write": False}
    radii = [float(s["radius_m"]) for s in usable]
    masses = [float(s["mass_kg"]) for s in usable]
    if not all(_agree_num(radii[0], r, REL) for r in radii[1:]) or not all(_agree_num(masses[0], m, REL) for m in masses[1:]):
        return {"ok": [], "held": [{"head": name.lower(), "property": "radius", "reason": "publishers_disagree"}],
                "calls_llm": False, "supabase_write": False}
    pubs = [_pub(str(s.get("id") or "imcce"), str(s["url"])) for s in usable[:2]]
    radius = sum(radii) / len(radii)
    mass = sum(masses) / len(masses)
    gm = 6.67430e-11 * mass
    head = name.lower()
    return gilligan([
        _fact(head, "radius", round(radius, 1), "m", pubs),
        _fact(head, "mass", mass, "kg", pubs),
        _fact(head, "gm", gm, "m3/s2", pubs),
    ])


def fetch_body(name: str, http: Http = _http) -> dict[str, Any]:
    """Radius and GM only from two CORS-readable catalogs that both publish them.

    IMCCE ssoCard sends Access-Control-Allow-Origin: * and publishes diameter and mass for
    many small bodies. A planetary-satellite name often 404s there, and a shared name can
    resolve to an asteroid instead of the moon. SsODNet Quaero (also CORS *) can identify
    a satellite and does not publish mass or radius. NASA/JPL SBDB JSON sends no
    Access-Control-Allow-Origin, so the phone cannot use it. One catalog is not agreement.
    """
    card_url = "https://ssp.imcce.fr/webservices/ssodnet/api/ssocard/" + urllib.parse.quote(name)
    quaero_url = "https://api.ssodnet.imcce.fr/quaero/1/sso?q=" + urllib.parse.quote(name) + "&type=Satellite&limit=1"
    imcce = None
    try:
        imcce = parse_ssocard(http(card_url), card_url)
    except Exception:
        imcce = None
    quaero = None
    try:
        quaero = parse_quaero_sso(http(quaero_url))
    except Exception:
        quaero = None
    if imcce and quaero and str(quaero.get("type") or "").lower() == "satellite" and str(imcce.get("type") or "").lower() != "satellite":
        # The card is a different body that shares the name (an asteroid, not the moon).
        imcce = None
    sides = []
    if imcce:
        sides.append({"id": "imcce", "url": imcce["url"], "radius_m": imcce["radius_m"], "mass_kg": imcce["mass_kg"]})
    # Quaero identifies; it does not add a radius. JPL is not readable on the phone.
    agreed = agree_body(name, sides)
    if not agreed.get("ok"):
        agreed["held"] = agreed.get("held") or []
        if agreed["held"]:
            agreed["held"][0]["imcce_numbers"] = bool(imcce)
            agreed["held"][0]["quaero_type"] = (quaero or {}).get("type")
            agreed["held"][0]["jpl_cors"] = False
    return agreed


def parse_nhtsa_specs(raw: str) -> dict[str, float]:
    """Canadian vehicle specifications as NHTSA vPIC publishes them (cm and kg)."""
    try:
        data = json.loads(raw)
    except Exception:
        return {}
    rows = data.get("Results") or data.get("results") or []
    buckets: dict[str, list[float]] = {"height": [], "width": [], "depth": [], "mass": []}
    for rec in rows:
        specs = rec.get("Specs") if isinstance(rec, dict) else None
        if not isinstance(specs, list):
            continue
        got = {}
        for item in specs:
            if not isinstance(item, dict):
                continue
            name = str(item.get("Name") or "")
            try:
                val = float(item.get("Value"))
            except (TypeError, ValueError):
                continue
            got[name] = val
        # OL overall length, OW width, OH height, in centimetres; CW curb weight in kilograms.
        if "OH" in got:
            buckets["height"].append(got["OH"] / 100.0)
        if "OW" in got:
            buckets["width"].append(got["OW"] / 100.0)
        if "OL" in got:
            buckets["depth"].append(got["OL"] / 100.0)
        if "CW" in got and got["CW"] > 0:
            buckets["mass"].append(got["CW"])
    return {k: v for k, v in ((key, _median(xs)) for key, xs in buckets.items()) if v}


def parse_epa_vehicle(raw: str) -> dict[str, Any]:
    """FuelEconomy.gov vehicle record. It publishes a size class. Dimensions are kept only if present."""
    try:
        data = json.loads(raw)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    out: dict[str, Any] = {}
    if data.get("VClass"):
        out["vclass"] = str(data["VClass"])
    for src, dest, scale in (("height", "height", 1.0), ("width", "width", 1.0), ("length", "depth", 1.0), ("curbWeight", "mass", 1.0)):
        if data.get(src) not in (None, ""):
            try:
                out[dest] = float(data[src]) * scale
            except (TypeError, ValueError):
                pass
    return out


def agree_vehicle(head: str, nhtsa: dict[str, float], epa: dict[str, Any], nhtsa_url: str, epa_url: str) -> dict[str, Any]:
    """A number is admitted only when both government hosts publish it and they agree.
    FuelEconomy.gov currently publishes the size class and not the curb weight, so a class
    word with no shared number holds."""
    pubs = [_pub("nhtsa", nhtsa_url), _pub("epa", epa_url)]
    rows = []
    for prop in ("height", "width", "depth", "mass"):
        if prop not in nhtsa or prop not in epa:
            continue
        if not _agree_num(float(nhtsa[prop]), float(epa[prop]), ARTIFACT_REL):
            continue
        mean = (float(nhtsa[prop]) + float(epa[prop])) / 2.0
        rows.append(_fact(head, prop, round(mean, 4), "kg" if prop == "mass" else "m", pubs))
    if not rows or not any(r["property"] == "mass" for r in rows):
        return {"ok": [], "ask": False, "held": [{"head": head.lower(), "property": "mass", "reason": "two_publishers_required",
                                                  "nhtsa": sorted(nhtsa), "epa": sorted(k for k in epa if k != "vclass"),
                                                  "vclass": epa.get("vclass")}],
                "calls_llm": False, "supabase_write": False}
    for row in rows:
        row["average"] = True
        row["phrase"] = head
    packed = gilligan(rows)
    packed["ask"] = False
    return packed


def vehicle_concept(head: str) -> bool:
    """True when the lexicon already maps this head to the vehicle concept. No noun list is added here."""
    try:
        table = json.loads((Path(__file__).with_name("concept_lexicon.json")).read_text(encoding="utf-8"))
    except Exception:
        return False
    return str(table.get(str(head or "").lower()) or "") == "N.CAR"


def lineage_of(publisher: dict[str, Any]) -> str:
    """One origin is one lineage. A mirror host of the same publisher does not count twice."""
    pid = str(publisher.get("id") or "").strip().lower()
    if pid:
        return pid
    host = str(publisher.get("host") or _host(str(publisher.get("url") or ""))).lower()
    if host.startswith("www."):
        host = host[4:]
    return host


def independent_lineages(fact: dict[str, Any]) -> list[str]:
    found: list[str] = []
    for raw in fact.get("publishers") or []:
        if not isinstance(raw, dict):
            continue
        url = str(raw.get("url") or "")
        if _blocked(url) or _blocked("https://" + str(raw.get("host") or "")):
            continue
        if str(raw.get("id") or "") in ("wikipedia", "wikidata"):
            continue
        lin = lineage_of(raw)
        if lin and lin not in found:
            found.append(lin)
    return found


def note_sources(ledger: dict[str, Any] | None, facts: list[dict[str, Any]], *, disagreed: bool = False) -> dict[str, Any]:
    """Persisted trust counts. A new source rises only by agreeing with a different lineage."""
    book = dict(ledger or {})
    rows = dict(book.get("sources") or {})
    for fact in facts:
        lins = independent_lineages(fact)
        for raw in fact.get("publishers") or []:
            if not isinstance(raw, dict):
                continue
            lin = lineage_of(raw)
            if not lin or lin in ("wikipedia", "wikidata"):
                continue
            row = dict(rows.get(lin) or {"lineage": lin, "agrees": 0, "conflicts": 0, "trusted": False})
            if disagreed:
                row["conflicts"] = int(row.get("conflicts") or 0) + 1
            elif len(lins) >= 2:
                row["agrees"] = int(row.get("agrees") or 0) + 1
                others = [x for x in lins if x != lin]
                if others and any((rows.get(o) or {}).get("trusted") or int((rows.get(o) or {}).get("agrees") or 0) >= 1 for o in others):
                    row["trusted"] = True
                if row["agrees"] >= 1 and len(lins) >= 2:
                    row["trusted"] = True
            rows[lin] = row
    book["sources"] = rows
    book["calls_llm"] = False
    book["supabase_write"] = False
    return book


def record_outcome(ledger: dict[str, Any] | None, method: str, rule: str, facts: list[dict[str, Any]] | None = None, *, disagreed: bool = False) -> dict[str, Any]:
    """The source ledger and the method counts, from one outcome."""
    book = note_sources(ledger, facts or [], disagreed=disagreed)
    methods = dict(book.get("methods") or {})
    row = dict(methods.get(method) or {"method": method, "proposed": 0, "rejected": 0, "simulated": 0})
    if rule == "ATHENA-PROPOSED":
        row["proposed"] = int(row.get("proposed") or 0) + 1
    elif rule == "ATHENA-SIMULATED":
        row["simulated"] = int(row.get("simulated") or 0) + 1
    else:
        row["rejected"] = int(row.get("rejected") or 0) + 1
    methods[method] = row
    book["methods"] = methods
    return book


def propose_rows(facts: list[dict[str, Any]], question: str = "") -> dict[str, Any]:
    """A structured proposal. The clause is the atom's fields, not a sentence that is parsed back."""
    proposals, rejected = [], []
    for fact in facts:
        if not isinstance(fact, dict):
            continue
        lins = independent_lineages(fact)
        atom = {"predicate": fact.get("property"), "args": [fact.get("head"), fact.get("value")], "polarity": "pos", "unit": fact.get("unit")}
        clause = {"property": fact.get("property"), "head": fact.get("head"), "value": fact.get("value"), "unit": fact.get("unit")}
        if len(lins) < 2 or clause["value"] != atom["args"][1] or clause["head"] != atom["args"][0]:
            rejected.append({"head": fact.get("head"), "property": fact.get("property"), "rule": "GILLIGAN-LINEAGE", "lineages": lins})
            continue
        prop, head, value = fact.get("property"), fact.get("head"), fact.get("value")
        shown = str(value) + ((" " + str(fact.get("unit"))) if fact.get("unit") else "")
        frame = {"kriya": "be", "polarity": "pos",
                 "kartr": {"text": "the " + str(prop) + " of " + str(head), "head": str(prop), "det": "the",
                           "of": {"text": str(head), "head": str(head)}},
                 "pred": {"type": "np", "text": shown, "head": str(value)}}
        proposals.append({
            "schema": SCHEMA, "head": head, "property": prop, "value": value,
            "unit": fact.get("unit"), "hosts": fact.get("hosts") or [], "publishers": fact.get("publishers") or [],
            "lineages": lins, "k": len(lins), "atom": atom, "clause": clause, "frame": frame, "question": question,
            "admitted": False, "phone_remember": False, "supabase_write": False, "calls_llm": False,
            "store": "proposal", "method": "lookup", "gilligan": "GILLIGAN-STRUCTURE-OK",
        })
    return {"proposals": proposals, "rejected": rejected, "calls_llm": False, "supabase_write": False}


def _personal(question: str) -> bool:
    return bool(re.search(r"\b(my|our)\b", str(question or ""), re.I))


def fill_gap(gap: dict[str, Any], http: Http = _http, ledger: dict[str, Any] | None = None) -> dict[str, Any]:
    """One generic step. Lookup, on-device simulate, or neither. Nothing is written."""
    gap = gap if isinstance(gap, dict) else {}
    question = str(gap.get("question") or "")
    sim = gap.get("sim") if isinstance(gap.get("sim"), dict) else {}
    frame = gap.get("qframe") if isinstance(gap.get("qframe"), dict) else None
    base = {"calls_llm": False, "supabase_write": False, "phone_remember": False, "question": question}
    if _personal(question):
        return {**base, "ok": [], "proposals": [], "rule": "ATHENA-PERSONAL", "ledger": ledger or {}}
    from rmc_engine_v1.sim_device import plan, tip_check
    if frame or not sim.get("reason"):
        planned = plan(question, frame)
    else:
        planned = {"ok": False, "reason": sim.get("reason"), "substance": sim.get("substance"), "body": sim.get("body")}
    if planned.get("ok") and planned.get("solver") in ("mujoco_wasm", "sympy_pyodide"):
        scene = planned.get("scene") if isinstance(planned.get("scene"), dict) else {}
        chk = tip_check(scene) if scene.get("action") == "push" else None
        return {**base, "ok": [], "proposals": [], "method": "simulate", "rule": "ATHENA-SIMULATED",
                "outcome": (chk or {}).get("outcome"), "solver": planned.get("solver"), "ledger": ledger or {}}
    reason = str(sim.get("reason") or planned.get("reason") or "")
    head = str(sim.get("substance") or sim.get("body") or planned.get("substance") or planned.get("body") or "").strip()
    if reason == "unknown_substance" and head:
        got = fetch_chemical(head, http)
    elif reason in ("unknown_body", "property_missing") and head:
        got = fetch_objects(head, http)
    else:
        return {**base, "ok": [], "proposals": [], "rule": "ATHENA-NOT-RESEARCHABLE", "reason": reason or "no_gap", "ledger": ledger or {}}
    held = got.get("held") or []
    disagree = any(str(h.get("reason") or "") == "publishers_disagree" for h in held if isinstance(h, dict))
    if disagree or not got.get("ok"):
        rule = "ATHENA-DISAGREEMENT" if disagree else "ATHENA-NO-AGREEMENT"
        book = record_outcome(ledger, "lookup", rule, got.get("ok") or [], disagreed=disagree)
        return {**base, "ok": [], "proposals": [], "held": held, "ledger": book, "rule": rule, "method": "lookup"}
    proposed = propose_rows(got.get("ok") or [], question)
    book = record_outcome(ledger, "lookup", "ATHENA-PROPOSED", got.get("ok") or [])
    return {**base, "ok": got.get("ok") or [], "proposals": proposed["proposals"], "rejected": proposed["rejected"],
            "held": held, "ledger": book, "rule": "ATHENA-PROPOSED", "method": "lookup"}


_BACKOFF = (0, 30, 120, 600)
_MAX_ATTEMPTS = 4


def tick_gaps(gaps: list[dict[str, Any]], *, now: float = 0, http: Http = _http, cancelled: list[str] | None = None,
              ledger: dict[str, Any] | None = None) -> dict[str, Any]:
    """One idle pass. Dedupes, backs off, and does not write."""
    seen: set[str] = set()
    stop = {str(x) for x in (cancelled or [])}
    log: list[dict[str, Any]] = []
    proposals: list[dict[str, Any]] = []
    book = dict(ledger or {})
    for gap in gaps or []:
        if not isinstance(gap, dict):
            continue
        key = " ".join(str(gap.get("question") or "").lower().split()).rstrip("?.!")
        if not key or key in seen:
            log.append({"key": key, "rule": "ATHENA-DEDUPED", "calls_llm": False})
            continue
        seen.add(key)
        if key in stop:
            log.append({"key": key, "rule": "ATHENA-CANCELLED", "calls_llm": False})
            continue
        attempts = int(gap.get("attempts") or 0)
        last = float(gap.get("last_at") or 0)
        wait = _BACKOFF[min(attempts, len(_BACKOFF) - 1)]
        if attempts and now < last + wait:
            log.append({"key": key, "rule": "ATHENA-BACKOFF", "calls_llm": False})
            continue
        if attempts >= _MAX_ATTEMPTS:
            log.append({"key": key, "rule": "ATHENA-EXHAUSTED", "calls_llm": False})
            continue
        found = fill_gap(gap, http, book)
        book = found.get("ledger") or book
        gap["attempts"] = attempts + 1
        gap["last_at"] = now
        gap["research_rule"] = found.get("rule")
        if found.get("proposals"):
            proposals.extend(found["proposals"])
        log.append({"key": key, "rule": found.get("rule"), "method": found.get("method"), "n": len(found.get("proposals") or []), "calls_llm": False})
    return {"log": log, "proposals": proposals, "ledger": book, "calls_llm": False, "supabase_write": False, "phone_remember": False}


def facts_for(kind: str, name: str, http: Http = _http) -> dict[str, Any]:
    if kind == "chemical":
        return fetch_chemical(name, http)
    if kind == "object":
        return fetch_objects(name, http)
    if kind == "body":
        return fetch_body(name, http)
    return {"ok": [], "held": [{"reason": "unknown_kind", "kind": kind}], "calls_llm": False, "supabase_write": False}

files.rmc_engine_v1/athena_sources_222.py:
"""4.9.222 Athena fetchers for the Tier-A trusted sources (FORGE-ATHENA-SOURCES/v1). Deterministic: no model, no embeddings.

Each fetcher turns a question into zero or one document per source page for self_seed_202.evaluate:
  - prose pages (NASA, Space Place, BIPM): the defining sentence is picked first (relation_echo.define_rank, best rank,
    first in page order); a page with no defining sentence gives no document;
  - glosses (MeSH scope note, ChEBI definition, OEWN gloss): rendered "Label is definition." (the first sentence of the
    gloss), which counts as a whole sentence; the verbatim gloss is kept in the document;
  - structured records (NSSDC, World Bank, GeoNames, CODATA, PubChem periodic table): rendered as one plain sentence
    from the record fields, with the record kept verbatim.
Wikidata is a link and cross-check only (crosscheck()): it never returns a source document.
A source is used only while its flag in reference/athena_sources_222.json is on. Nothing here writes anywhere.
The http getter is injectable so every source is unit-tested offline on recorded responses."""
from __future__ import annotations

import gzip
import hashlib
import html as _html
import json
import os
import re
import time
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable

from rmc_engine_v1.relation_echo import asked, define_rank

HERE = Path(__file__).resolve().parent
CONFIG = HERE / "reference" / "athena_sources_222.json"
UA = "ForgeMobile/4.9.222 (Athena trusted-source fetch; no model; contact via github.com/BogaertN/forge-mobile)"
Http = Callable[[str], str]


class FetchMiss(Exception):
    """The page or record does not exist (404 or empty)."""


def load_config() -> dict[str, Any]:
    return json.loads(CONFIG.read_text(encoding="utf-8"))


def source_rows() -> dict[str, dict[str, Any]]:
    return {row["id"]: row for row in load_config()["sources"]}


def enabled(sid: str) -> bool:
    return bool(source_rows().get(sid, {}).get("enabled"))


def http_get(url: str, timeout: float = 25.0, tries: int = 2) -> str:
    last: Exception | None = None
    for attempt in range(tries):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "application/sparql-results+json,application/json;q=0.9,text/html;q=0.8,text/plain;q=0.7,*/*;q=0.5"})
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                raw = resp.read(4_000_000)
                if raw[:2] == b"\x1f\x8b":
                    raw = gzip.decompress(raw)
                return raw.decode("utf-8", "replace")
        except urllib.error.HTTPError as exc:
            if exc.code == 404:
                raise FetchMiss(url) from exc
            last = exc
        except Exception as exc:  # network: retried once, then reported, never read as "no source"
            last = exc
        time.sleep(1.5 * (attempt + 1))
    raise last or RuntimeError("fetch failed")


def sha256_text(text: str) -> str:
    return hashlib.sha256(str(text or "").encode("utf-8")).hexdigest()


def now_iso() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


# ---------------------------------------------------------------- subject, sentences, renders
_Q = re.compile(r"^\s*(?:what|who|which)\s+(?:is|are|was|were)\s+(?:the\s+|a\s+|an\s+)?(.+?)\s*\??\s*$", re.IGNORECASE)
KNOWN_ATTRS = {"capital", "mass", "mean radius", "radius", "density", "mean density", "surface gravity", "gravity", "escape velocity"}
_OF = re.compile(r"^(?P<attr>[A-Za-z][A-Za-z ]*?)\s+of\s+(?:the\s+)?(?P<thing>.+)$", re.IGNORECASE)


def subject_of(question: str) -> dict[str, Any]:
    """The asked label with the asker's own capitalisation, and for 'X of Y' the attribute and the thing."""
    m = _Q.match(str(question or ""))
    label = m.group(1).strip() if m else ""
    out: dict[str, Any] = {"question": question, "label": label, "ask": asked(question), "attr": None, "thing": None}
    of = _OF.match(label) if label else None
    if of and of.group("attr").strip().lower() in KNOWN_ATTRS:
        out["attr"], out["thing"] = of.group("attr").strip().lower(), of.group("thing").strip()
    return out


def page_text_blocks(page: str) -> list[str]:
    """Paragraph text of an HTML page (scripts, styles, navigation and footers dropped)."""
    t = re.sub(r"(?is)<(script|style|noscript|svg|nav|header|footer|form)\b.*?</\1>", " ", page)
    blocks = re.findall(r"(?is)<p\b[^>]*>(.*?)</p>", t)
    out = []
    for b in blocks:
        text = " ".join(_html.unescape(re.sub(r"<[^>]+>", " ", b)).split())
        text = re.sub(r"\s+([,.;:!?])", r"\1", text)
        if len(text) >= 20:
            out.append(text)
    return out


def sentences_of(blocks: list[str]) -> list[str]:
    out = []
    for block in blocks:
        for part in re.split(r"(?<=[.!?])\s+(?=[A-Z\"'(])", block):
            part = part.strip()
            if part:
                out.append(part)
    return out


def choose_defining(question: str, sentences: list[str]) -> dict[str, Any] | None:
    """define_rank first: the best-ranked sentence, first in page order; rank 0 (only a mention) is never chosen."""
    ask = asked(question)
    best = None
    for i, s in enumerate(sentences):
        r = define_rank(ask, s)
        if r.get("rank", 0) >= 1 and (best is None or r["rank"] > best["rank"]):
            best = {"sentence": s, "rank": r["rank"], "kind": r.get("kind"), "index": i}
            if r["rank"] == 2:
                break
    return best


_LOWER_OK = {"the", "a", "an", "any", "one", "some", "either", "each"}


def render_gloss(label: str, gloss: str) -> str | None:
    """'Label is definition.' from the first sentence (or first ';' clause) of a dictionary-style gloss."""
    g = " ".join(str(gloss or "").split())
    if not g or not label:
        return None
    g = re.sub(r"^\((?:[a-z ]+)\)\s+", "", g)  # OEWN domain label, e.g. "(physics) the force of ..."
    g = re.split(r"(?<=[a-z0-9)\]])\.\s+(?=[A-Z])", g, maxsplit=1)[0]
    depth, cut = 0, len(g)
    for i, ch in enumerate(g):  # first '; ' outside brackets ("atomic weight [15.99903; 15.99977]" stays whole)
        depth += ch in "([" ; depth -= ch in ")]"
        if ch == ";" and depth <= 0 and g[i + 1:i + 2] == " ":
            cut = i
            break
    g = g[:cut].strip().rstrip(".;: ")
    if re.sub(r"[^a-z0-9]", "", g.lower()).startswith(re.sub(r"[^a-z0-9]", "", label.lower())):
        return None  # a tautology ("Quartz is Quartz (SiO2).") defines nothing
    first = g.split(" ", 1)[0]
    if first and first[0].isupper() and first[1:] == first[1:].lower() and (first.lower() in _LOWER_OK or first.lower() not in label.lower().split()):
        g = first[0].lower() + g[1:]
    if not g:
        return None
    return label[0].upper() + label[1:] + " is " + g + "."


def _doc(sid: str, url: str, text: str, verbatim: str, how: dict[str, Any], raw: str = "") -> dict[str, Any]:
    row = source_rows()[sid]
    return {
        "url": url, "text": text, "role": "source", "source_id": sid, "publisher": row["publisher"], "kind": row["kind"],
        "verbatim": verbatim, "how": how, "fetched_at": now_iso(), "sha256": sha256_text(text),
        "raw_sha256": sha256_text(raw or verbatim),
    }


def _slug(label: str) -> str:
    s = re.sub(r"^(the|a|an)\s+", "", label.strip().lower())
    return re.sub(r"[^a-z0-9]+", "-", s).strip("-")


# ---------------------------------------------------------------- NASA (one publisher, three hosts)
def fetch_nasa_science(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    if not subj["label"] or subj["attr"]:
        return []
    slug = _slug(subj["label"])
    for url in (f"https://science.nasa.gov/{slug}/facts/", f"https://science.nasa.gov/{slug}/"):
        try:
            page = http(url)
        except FetchMiss:
            continue
        pick = choose_defining(q, sentences_of(page_text_blocks(page)))
        if pick:
            return [_doc("nasa_science", url, pick["sentence"], pick["sentence"], {"define_rank": pick["rank"], "index": pick["index"]}, page)]
    return []


def fetch_nasa_spaceplace(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    if not subj["label"] or subj["attr"]:
        return []
    slug = _slug(subj["label"])
    for path in (f"all-about-the-{slug}", f"all-about-{slug}", f"what-is-{slug}", slug):
        url = f"https://spaceplace.nasa.gov/{path}/en/"
        try:
            page = http(url)
        except FetchMiss:
            continue
        if "<title>Page Not Found" in page or "Page not found" in page[:4000]:
            continue
        pick = choose_defining(q, sentences_of(page_text_blocks(page)))
        if pick:
            return [_doc("nasa_spaceplace", url, pick["sentence"], pick["sentence"], {"define_rank": pick["rank"], "index": pick["index"]}, page)]
    return []


NSSDC_BODIES = {"mercury", "venus", "earth", "moon", "mars", "jupiter", "saturn", "uranus", "neptune", "pluto", "sun"}
NSSDC_ATTRS = {  # question attribute -> fact-sheet row label (the label text before the unit)
    "mass": "Mass", "mean radius": "Volumetric mean radius", "radius": "Volumetric mean radius", "density": "Mean density",
    "mean density": "Mean density", "surface gravity": "Surface gravity", "gravity": "Surface gravity", "escape velocity": "Escape velocity",
}


def _nssdc_rows(page: str) -> dict[str, tuple[str, str]]:
    out = {}
    for row in re.findall(r"(?is)<tr[^>]*>(.*?)</tr>", page):
        cells = [" ".join(_html.unescape(re.sub(r"<[^>]+>", " ", c)).split()) for c in re.findall(r"(?is)<t[dh][^>]*>(.*?)</t[dh]>", row)]
        if len(cells) >= 2 and cells[0]:
            m = re.match(r"^(.*?)\s*\((.*)\)\s*$", cells[0])
            name, unit = (m.group(1), m.group(2)) if m else (cells[0], "")
            out.setdefault(name.strip(), (cells[1], unit))  # 4.9.223: the planet's own table comes first; a later moon table (Phobos) never overwrites it
    return out


def _nssdc_unit(unit: str) -> tuple[str, str]:
    """'10 24 kg' (superscripts flattened by the page) -> ('× 10^24', 'kg')."""
    m = re.match(r"^(?:x\s*)?10\s+(-?\d+)\s+(.*)$", unit.strip())
    if m:
        return "× 10^" + m.group(1), re.sub(r"\s+(\d)\b", r"^\1", m.group(2)).strip()
    return "", re.sub(r"(?<=[a-z])\s+(\d)\b", r"^\1", unit.strip())


def fetch_nasa_nssdc(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    attr, thing = subj["attr"], (subj["thing"] or "")
    body = re.sub(r"^(the)\s+", "", thing.lower())
    if not attr or attr not in NSSDC_ATTRS or body not in NSSDC_BODIES:
        return []
    url = f"https://nssdc.gsfc.nasa.gov/planetary/factsheet/{body}fact.html"
    page = http(url)
    rows = _nssdc_rows(page)
    want = NSSDC_ATTRS[attr]
    if want not in rows:
        return []
    value, unit = rows[want]
    scale, unit = _nssdc_unit(unit)
    name = "the Moon" if body == "moon" else ("the Sun" if body == "sun" else body.capitalize())
    text = f"The {attr} of {name} is {value}{(' ' + scale) if scale else ''} {unit}.".replace("  ", " ")
    return [_doc("nasa_nssdc", url, text, f"{want} ({unit}): {value}", {"record": want}, page)]


# ---------------------------------------------------------------- NLM MeSH
MESH = "https://id.nlm.nih.gov/mesh"


def fetch_nlm_mesh(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    label = subj["label"]
    if not label or subj["attr"]:
        return []
    tried = []
    for form in dict.fromkeys([label, label[0].upper() + label[1:], label.title()]):
        hits = json.loads(http(f"{MESH}/lookup/term?" + urllib.parse.urlencode({"label": form, "match": "exact", "limit": 3})) or "[]")
        tried.append(form)
        for hit in hits:
            term = str(hit.get("resource") or "").rsplit("/", 1)[-1]
            query = ("PREFIX meshv: <http://id.nlm.nih.gov/mesh/vocab#> PREFIX mesh: <http://id.nlm.nih.gov/mesh/> "
                     "PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> SELECT ?d ?dl ?c ?note WHERE { "
                     "{ ?c meshv:preferredTerm mesh:%s } UNION { ?c meshv:term mesh:%s } . ?d meshv:preferredConcept ?c . "
                     "?d rdfs:label ?dl . ?c meshv:scopeNote ?note }" % (term, term))
            res = json.loads(http(f"{MESH}/sparql?" + urllib.parse.urlencode({"query": query, "format": "JSON"})))
            for b in (res.get("results") or {}).get("bindings") or []:
                note = b["note"]["value"]
                desc = b["d"]["value"].rsplit("/", 1)[-1]
                text = render_gloss(str(hit.get("label") or form), note)
                if text:
                    # the term is in the descriptor's preferred concept: a synonym, the same meaning
                    return [_doc("nlm_mesh", f"https://id.nlm.nih.gov/mesh/{desc}.html", text, note,
                                 {"descriptor": desc, "descriptor_label": b["dl"]["value"], "term": term, "render": "GLOSS-FIT"})]
    return []


# ---------------------------------------------------------------- countries (World Bank, GeoNames)
def _country_thing(subj: dict[str, Any]) -> str | None:
    if subj["attr"] != "capital" or not subj["thing"]:
        return None
    return subj["thing"].strip()


def _cnorm(name: str) -> str:
    return " ".join(re.findall(r"[a-z0-9]+", name.lower().replace("&", "and")))


def fetch_worldbank(q: str, http: Http) -> list[dict[str, Any]]:
    thing = _country_thing(subject_of(q))
    if not thing:
        return []
    url = "https://api.worldbank.org/v2/country?format=json&per_page=400"
    raw = http(url)
    data = json.loads(raw)
    for c in data[1] if isinstance(data, list) and len(data) > 1 else []:
        if _cnorm(c.get("name") or "") == _cnorm(thing) and (c.get("capitalCity") or "").strip():
            text = f"The capital of {c['name']} is {c['capitalCity'].strip()}."
            return [_doc("worldbank", f"https://api.worldbank.org/v2/country/{c['id']}?format=json", text,
                         json.dumps({k: c.get(k) for k in ("id", "name", "capitalCity")}, ensure_ascii=False), {"record": c["id"]}, raw)]
    return []


def fetch_geonames(q: str, http: Http) -> list[dict[str, Any]]:
    thing = _country_thing(subject_of(q))
    if not thing:
        return []
    url = "https://download.geonames.org/export/dump/countryInfo.txt"
    raw = http(url)
    for line in raw.splitlines():
        if not line or line.startswith("#"):
            continue
        f = line.split("\t")
        if len(f) > 5 and _cnorm(f[4]) == _cnorm(thing) and f[5].strip():
            text = f"The capital of {f[4]} is {f[5].strip()}."
            return [_doc("geonames", url + "#" + f[0], text, "\t".join(f[:9]), {"record": f[0]}, raw)]
    return []


# ---------------------------------------------------------------- NIST CODATA, BIPM SI
def _codata_value(v: str) -> str:
    v = v.replace(" ", "").replace("...", "")
    m = re.match(r"^(-?[\d.]+)e(-?\d+)$", v)
    return f"{m.group(1)} × 10^{int(m.group(2))}" if m else v


def fetch_nist_codata(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    label = re.sub(r"^(the|a|an)\s+", "", subj["label"].lower())
    if not label:
        return []
    url = "https://physics.nist.gov/cuu/Constants/Table/allascii.txt"
    raw = http(url)
    rows = []
    for line in raw.splitlines():
        m = re.match(r"^(\S.*?)\s{2,}(-?[\d. ]+(?:e-?\d+)?(?:\.\.\.)?)\s{2,}(\(exact\)|[\d. ]+(?:e-?\d+)?)\s*(.*)$", line)
        if m:
            rows.append((m.group(1).strip(), m.group(2).strip(), m.group(3).strip(), m.group(4).strip()))
    pick = next((r for r in rows if r[0].lower() == label), None)
    if not pick:  # "speed of light" -> "speed of light in vacuum": the one row that extends the asked name
        ext = [r for r in rows if r[0].lower().startswith(label + " ")]
        pick = ext[0] if len(ext) == 1 else None
    if not pick:
        return []
    name, value, unc, unit = pick
    text = f"The {name} is {_codata_value(value)}{(' ' + unit) if unit else ''}{' (exact)' if unc == '(exact)' else ''}."
    return [_doc("nist_codata", url + "#" + urllib.parse.quote(name), text, " | ".join(pick), {"record": name, "edition": "CODATA 2022"}, raw)]


BIPM_UNITS = {"second": "second", "metre": "metre", "meter": "metre", "kilogram": "kilogram", "ampere": "ampere",
              "kelvin": "kelvin", "mole": "mole", "candela": "candela"}


def fetch_bipm_si(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    word = re.sub(r"^(the|a|an)\s+", "", subj["label"].lower())
    unit = BIPM_UNITS.get(word)
    if not unit or subj["attr"]:
        return []
    url = f"https://www.bipm.org/en/si-base-units/{unit}"
    page = http(url)
    plain = " ".join(_html.unescape(re.sub(r"<[^>]+>", " ", re.sub(r"(?is)<(script|style)\b.*?</\1>", " ", page))).split())
    m = re.search(r"The (%s), symbol (\S+), is (the SI unit of [^.]+)\." % unit, plain)
    if not m:
        return []
    verbatim = m.group(0)
    shown = word if word != unit else unit  # the asker's spelling (meter) of the BIPM name (metre)
    text = f"The {shown} is {m.group(3)}."
    return [_doc("bipm_si", url, text, verbatim, {"render": "drop the symbol apposition", "symbol": m.group(2)}, page)]


# ---------------------------------------------------------------- chemistry: PubChem, ChEBI
PUBCHEM_PD_ORIGINS = {"LiverTox", "Hazardous Substances Data Bank (HSDB)"}


def fetch_pubchem(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    label = re.sub(r"^(the|a|an)\s+", "", subj["label"])
    if not label or subj["attr"]:
        return []
    url = "https://pubchem.ncbi.nlm.nih.gov/rest/pug/periodictable/JSON"
    raw = http(url)
    table = json.loads(raw)["Table"]
    cols = table["Columns"]["Column"]
    for row in table["Row"]:
        rec = dict(zip(cols, row["Cell"]))
        if rec.get("Name", "").lower() == label.lower():
            text = f"{rec['Name']} is a chemical element with symbol {rec['Symbol']} and atomic number {rec['AtomicNumber']}."
            return [_doc("pubchem", f"https://pubchem.ncbi.nlm.nih.gov/element/{rec['AtomicNumber']}", text,
                         json.dumps({k: rec[k] for k in ("AtomicNumber", "Symbol", "Name", "GroupBlock", "StandardState")}), {"record": "periodic table"}, raw)]
    durl = f"https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/name/{urllib.parse.quote(label)}/description/JSON"
    try:
        info = json.loads(http(durl)).get("InformationList", {}).get("Information", [])
    except FetchMiss:
        return []
    cid = next((i.get("CID") for i in info if i.get("CID")), None)
    for item in info:
        if item.get("Description") and item.get("DescriptionSourceName") in PUBCHEM_PD_ORIGINS:
            sents = sentences_of([item["Description"]])
            pick = choose_defining(q, sents)
            if pick:
                return [_doc("pubchem", f"https://pubchem.ncbi.nlm.nih.gov/compound/{cid}", pick["sentence"], item["Description"],
                             {"origin": item["DescriptionSourceName"], "define_rank": pick["rank"]})]
    return []


def fetch_chebi(q: str, http: Http) -> list[dict[str, Any]]:
    subj = subject_of(q)
    label = re.sub(r"^(the|a|an)\s+", "", subj["label"])
    if not label or subj["attr"]:
        return []
    url = "https://www.ebi.ac.uk/ols4/api/search?" + urllib.parse.urlencode({"q": label, "ontology": "chebi", "exact": "true", "rows": 5})
    docs = (json.loads(http(url)).get("response") or {}).get("docs") or []
    for d in docs:
        if str(d.get("label") or "").lower() == label.lower() and d.get("description"):
            gloss = str(d["description"][0])
            text = render_gloss(label, gloss)
            if text:
                return [_doc("chebi", "https://www.ebi.ac.uk/chebi/searchId.do?chebiId=" + str(d.get("obo_id")), text, gloss,
                             {"chebi": d.get("obo_id"), "render": "GLOSS-FIT"})]
    return []


# ---------------------------------------------------------------- Open English WordNet 2025 plus (pinned sense)
_OEWN_CACHE: dict[str, Any] = {}


def oewn_dir() -> Path | None:
    p = os.environ.get("FORGE_OEWN_DIR")
    return Path(p) if p and Path(p).is_dir() else None


def _oewn_entries(letter: str) -> dict[str, Any]:
    key = "e" + letter
    if key not in _OEWN_CACHE:
        d = oewn_dir()
        f = d / f"entries-{letter if letter.isalpha() else '0'}.json" if d else None
        _OEWN_CACHE[key] = json.loads(f.read_text(encoding="utf-8")) if f and f.exists() else {}
    return _OEWN_CACHE[key]


def _oewn_synset(sid: str) -> dict[str, Any] | None:
    if "syn" not in _OEWN_CACHE:
        d = oewn_dir()
        syn: dict[str, Any] = {}
        for f in sorted(d.glob("noun.*.json")) if d else []:
            syn.update(json.loads(f.read_text(encoding="utf-8")))
        _OEWN_CACHE["syn"] = syn
    return _OEWN_CACHE["syn"].get(sid)


def fetch_oewn(q: str, http: Http, pinned: dict[str, str] | None = None) -> list[dict[str, Any]]:
    """The gloss of the pinned sense when the concept is pinned; otherwise the only noun meaning of the word as asked
    (capitalisation kept). Two or more meanings and no pin: nothing is guessed (the dry-run asks)."""
    subj = subject_of(q)
    label = re.sub(r"^(the|a|an)\s+", "", subj["label"], flags=re.IGNORECASE)
    if not label or subj["attr"] or not oewn_dir():
        return []
    sid = (pinned or {}).get(label.lower())
    how = {"sense": "pinned"} if sid else {}
    if not sid:
        forms = [label] if label[:1].isupper() else [label, label.lower()]
        senses = []
        for form in forms:
            ent = _oewn_entries(form[:1].lower()).get(form) or {}
            senses += [s["synset"] for s in (ent.get("n") or {}).get("sense") or []]
        senses = list(dict.fromkeys(senses))
        if len(senses) != 1:
            return [{"role": "ambiguous", "source_id": "oewn", "senses": senses, "url": "", "text": ""}] if senses else []
        sid, how = senses[0], {"sense": "only noun meaning"}
    syn = _oewn_synset(sid)
    if not syn or not syn.get("definition"):
        return []
    gloss = str(syn["definition"][0])
    text = render_gloss(label, gloss)
    return [_doc("oewn", f"https://en-word.net/id/oewn-{sid}", text, gloss, dict(how, synset=sid, ili=syn.get("ili"), qid=_qid(syn.get("wikidata")), render="GLOSS-FIT"))] if text else []


# ---------------------------------------------------------------- Wikidata: link and cross-check only
def _qid(value: Any) -> str | None:
    if isinstance(value, list):
        value = value[0] if value else None
    value = str(value or "").strip()
    return value if re.fullmatch(r"Q\d+", value) else None


def crosscheck(q: str, http: Http, qid: str | None = None) -> dict[str, Any] | None:
    """Wikidata as a link and a cross-check only. With the QID the pinned OEWN sense links to, read that item's label and
    description; without one, only report how many items carry the label (it is never used to pick a meaning)."""
    subj = subject_of(q)
    label = re.sub(r"^(the|a|an)\s+", "", subj["label"], flags=re.IGNORECASE)
    if not label:
        return None
    if qid:
        url = "https://www.wikidata.org/w/api.php?" + urllib.parse.urlencode({"action": "wbgetentities", "ids": qid, "props": "labels|descriptions", "languages": "en", "format": "json"})
        ent = (json.loads(http(url)).get("entities") or {}).get(qid) or {}
        lab = ((ent.get("labels") or {}).get("en") or {}).get("value")
        desc = ((ent.get("descriptions") or {}).get("en") or {}).get("value")
        return {"role": "crosscheck", "source_id": "wikidata", "qid": qid, "label": lab, "description": desc, "via": "OEWN sense link",
                "label_matches": bool(lab) and lab.lower() == label.lower(), "url": "https://www.wikidata.org/wiki/" + qid, "counts_as_publisher": False}
    url = "https://www.wikidata.org/w/api.php?" + urllib.parse.urlencode({"action": "wbsearchentities", "search": label, "language": "en", "format": "json", "limit": 7, "type": "item"})
    hits = json.loads(http(url)).get("search") or []
    exact = [h for h in hits if str(h.get("label") or "").lower() == label.lower()]
    return {"role": "crosscheck", "source_id": "wikidata", "qid": None, "via": "label search (not resolved)", "exact_label_items": len(exact),
            "counts_as_publisher": False}


def pins_from_table(table: dict[str, Any]) -> tuple[dict[str, str], dict[str, str]]:
    """The 4.9.221 curated meaning table (passed in by the caller) -> (surface -> pinned OEWN sense, surface -> the QID that sense links to)."""
    pinned = {r["surface"]: r["sense"] for r in (table.get("concepts") or {}).values() if r.get("surface") and r.get("sense")}
    senses = table.get("senses") or {}
    qids = {}
    for surface, sid in pinned.items():
        q = _qid((senses.get(sid) or [None, None, None])[2])
        if q:
            qids[surface] = q
    return pinned, qids


FETCHERS: dict[str, Callable[..., list[dict[str, Any]]]] = {
    "nasa_science": fetch_nasa_science, "nasa_nssdc": fetch_nasa_nssdc, "nasa_spaceplace": fetch_nasa_spaceplace,
    "nlm_mesh": fetch_nlm_mesh, "worldbank": fetch_worldbank, "geonames": fetch_geonames, "nist_codata": fetch_nist_codata,
    "bipm_si": fetch_bipm_si, "pubchem": fetch_pubchem, "chebi": fetch_chebi, "oewn": fetch_oewn,
}


def fetch_all(question: str, http: Http = http_get, pinned: dict[str, str] | None = None, only: list[str] | None = None, pinned_qid: dict[str, str] | None = None) -> dict[str, Any]:
    """Every enabled source, one by one. A source error is recorded for that source and never stops the others."""
    rows = source_rows()
    per: dict[str, Any] = {}
    docs: list[dict[str, Any]] = []
    for sid, row in rows.items():
        if only and sid not in only:
            continue
        if not row.get("enabled"):
            per[sid] = {"status": row.get("status") or "DISABLED", "docs": []}
            continue
        if sid == "wikidata":
            continue  # after every source: it reads the QID the OEWN sense links to
        try:
            got = FETCHERS[sid](question, http, pinned) if sid == "oewn" else FETCHERS[sid](question, http)
        except FetchMiss:
            got = []
        except Exception as exc:
            per[sid] = {"status": "ERROR", "error": type(exc).__name__ + ": " + str(exc)[:120], "docs": []}
            continue
        amb = [d for d in got if d.get("role") == "ambiguous"]
        src = [d for d in got if d.get("role") == "source"]
        per[sid] = {"status": "AMBIGUOUS" if amb else ("FETCHED" if src else "NO-ENTRY"), "docs": src, "senses": amb[0]["senses"] if amb else None}
        docs += src
    if rows.get("wikidata", {}).get("enabled") and (not only or "wikidata" in only):
        qid = next((d["how"].get("qid") for d in docs if d.get("source_id") == "oewn"), None) or (pinned_qid or {}).get(subject_of(question)["label"].lower().removeprefix("the ").removeprefix("a "))
        try:
            per["wikidata"] = {"status": "CROSSCHECK", "crosscheck": crosscheck(question, http, qid)}
        except Exception as exc:
            per["wikidata"] = {"status": "ERROR", "error": type(exc).__name__ + ": " + str(exc)[:120]}
    return {"question": question, "per_source": per, "documents": docs, "calls_llm": False, "writes": False}

