    scenario_id = _normalize_scenario_id(source_metadata.get("scenario") or source_metadata.get("ui_scenario_id"))
    scenario = dict(SCENARIO_LIBRARY.get(scenario_id, SCENARIO_LIBRARY["custom"]))
