_MEANING_STOP = {
    "the", "and", "for", "with", "from", "that", "this", "what", "which", "when",
    "where", "who", "whom", "why", "how", "are", "was", "were", "you", "your",
    "does", "did", "can", "could", "into", "about", "have", "has", "not", "but",
}


def _meaning_tokens(text: str) -> set[str]:
    import re
    return {w for w in re.findall(r"[a-z0-9]+", str(text or "").lower()) if len(w) > 2 and w not in _MEANING_STOP}


def _meaning_coverage(question: str, text: str) -> float:
    left = _meaning_tokens(question)
    right = _meaning_tokens(text)
    if not left:
        return 0.0
    return len(left & right) / len(left)


def _recalled_nodes(trace_spine: dict[str, Any]) -> list[dict[str, Any]]:
    recall = _as_dict(_as_dict(trace_spine.get("memory_recall")).get("memory_state"))
    nodes = recall.get("active_memory_nodes")
    return [n for n in nodes if isinstance(n, dict)] if isinstance(nodes, list) else []


def _admitted_claim(question: str, trace_spine: dict[str, Any]) -> dict[str, Any]:
    """Pick a verified recalled sentence that carries the question's meaning.

    Quarantined research (low confidence, prior drift at or above 0.40) is not a claim.
    It stays evidence until the admit gate passes on a later write.
    """
    best: dict[str, Any] = {}
    best_score = 0.0
    for node in _recalled_nodes(trace_spine):
        prior = _number(node.get("prior_drift_score"), 0.0)
        confidence = str(node.get("confidence") or "")
        if prior >= 0.40 or confidence == "low":
            continue
        text = str(node.get("content_summary") or node.get("content") or "").strip()
        score = _meaning_coverage(question, text)
        if score > best_score:
            best_score = score
            best = {"text": text, "score": round(score, 6), "memory_id": node.get("memory_id"), "source": node.get("source")}
    return best


def _manifest_reading(coherence_report: dict[str, Any], wm_measure: dict[str, Any] | None, routing_epsilon: float) -> dict[str, Any]:
    """4.9.235 (plan 229 step 7): the manifest's numbers are the measured reading of the answer.

    When the world model speaks, its reading (weakest hop for C, memory fit and source confidence;
    the largest epsilon and novelty over the spoken sentences). Otherwise the orchestrator's
    selected candidate, as the kernel measured it. Nothing here is a fixed number.
    """
    selected = _as_dict(_as_dict(coherence_report).get("selected_scored_candidate_preview"))
    parts = _as_dict(selected.get("score_components"))
    drift = _as_dict(selected.get("measured_evolutionary_drift"))
    pre = _number(drift.get("epsilon_s"), routing_epsilon)
    if isinstance(wm_measure, dict) and wm_measure.get("sentences"):
        sentences = [s for s in wm_measure.get("sentences") or [] if isinstance(s, dict)]
        weakest = next((s for s in sentences if s.get("text") == wm_measure.get("weakest_hop")), sentences[0])
        comp = _as_dict(weakest.get("components"))
        terms = _as_dict(weakest.get("drift_terms"))
        return {
            "basis": "world_model_measure (weakest hop; epsilon and novelty: max over spoken sentences)",
            "confidence": _number(wm_measure.get("C"), 0.0),
            "novelty": max(_number(_as_dict(s.get("drift_terms")).get("novelty_delta"), 0.0) for s in sentences),
            "pre_epsilon_s": pre,
            "post_epsilon_s": _number(wm_measure.get("epsilon_s"), pre),
            "semantic_distance": _number(terms.get("semantic_distance"), 0.0),
            "memory_fit": _number(comp.get("memory_fit"), 0.0),
            "source_confidence": _number(comp.get("source_confidence"), 0.0),
        }
    return {
        "basis": "orchestrator selected candidate (measurement_kernel)",
        "confidence": _number(parts.get("coherence_score"), _number(selected.get("coherence_score"), 0.0)),
        "novelty": _number(drift.get("novelty_delta"), 0.0),
        "pre_epsilon_s": pre,
        "post_epsilon_s": pre,
        "semantic_distance": _number(drift.get("semantic_distance"), 0.0),
        "memory_fit": _number(parts.get("memory_fit"), _number(drift.get("memory_fit"), 0.0)),
        "source_confidence": _number(parts.get("source_confidence"), _number(drift.get("source_confidence"), 0.0)),
    }


def _live_manifest(claim: str, phase_path: list[Any], epsilon: float, memory_id: str | None, reading: dict[str, Any] | None = None) -> dict[str, Any]:
    reading = reading if isinstance(reading, dict) else {}
    mu = {
        "claim": claim[:1600],
        "phase_path": phase_path or ["Φ1"],
        "operator_path": ["memory_recall", "coherence_scorer", "containment_router"],
        "memory_links": [{"memory_id": memory_id or "recalled", "role": "admitted_evidence"}],
        # 4.9.235: measured (see _manifest_reading); a key the reading lacks reads 0, not a made-up value.
        "confidence": round(_number(reading.get("confidence"), 0.0), 6),
        "novelty": round(_number(reading.get("novelty"), 0.0), 6),
        "drift_status": {
            "status": "bounded",
            "post_epsilon_s": round(_number(reading.get("post_epsilon_s"), float(epsilon)), 6),
            "pre_epsilon_s": round(_number(reading.get("pre_epsilon_s"), float(epsilon)), 6),
            "semantic_distance": round(_number(reading.get("semantic_distance"), 0.0), 6),
            "memory_fit": round(_number(reading.get("memory_fit"), 0.0), 6),
            "source_confidence": round(_number(reading.get("source_confidence"), 0.0), 6),
            "measured_basis": reading.get("basis") or "none",
        },
        "projection_status": {"status": "not_projected"},
        "output_targets": [{"target": "text"}],
        "forbidden_claims": [],
    }
    return {
        "manifest_compilation_allowed": True,
        "manifest_packet": {
            "manifest_symbol": "μ_t",
            "manifest_id": "live_mu_" + _sha({"claim": claim[:240]}),
            "μ_t": mu,
        },
    }


def _claim_for_renderer(question: str, trace_spine: dict[str, Any], reasoning: dict[str, Any]) -> dict[str, Any]:
    """Admitted memory is the claim until the reasoning seam is applied.

    4.9.184 sets applied and derived_text. The renderer then speaks that text.
    """
    if reasoning.get("applied") is True:
        text = str(reasoning.get("derived_text") or "").strip()
        if text:
            return {"text": text, "score": 1.0, "memory_id": "reasoning_seam", "source": "reasoning_seam"}
        # Contract §5: a conflict is not a chosen side. Do not fall through to one premise.
        if str((reasoning.get("derive") or {}).get("status") or "") == "conflicted":
            return {}
    return _admitted_claim(question, trace_spine)


def _run_late_stages(
    question: str,
    route_result: dict[str, Any],
    trace_spine: dict[str, Any],
    epsilon: float,
    phase_path: list[Any],
    reasoning: dict[str, Any] | None = None,
    reading: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Renderer, Echo, and memory writer. Sealed routes are executed as blocked, not skipped."""
    stages: list[dict[str, Any]] = []
    artifacts: dict[str, Any] = {}
    reasoning = reasoning if isinstance(reasoning, dict) else {}
    sealed = bool(route_result.get("is_sealed"))
    render_allowed = bool(route_result.get("echo_validation_allowed")) and not sealed
    claim = _claim_for_renderer(question, trace_spine, reasoning)
    render_report: dict[str, Any] = {}
    if not render_allowed:
        stages.append(_stage_ok(
            "output_renderer_eligibility_check",
            {"executed": True, "rendering_allowed": False, "blocked": True, "reason": "sealed_or_unlawful_route_blocks_renderer", "route": route_result.get("route")},
            executed=True,
            reason="sealed_or_unlawful_route_blocks_renderer",
        ))
    elif not claim.get("text"):
        blocked_reason = "conflicted_derivation_not_rendered" if str((reasoning.get("derive") or {}).get("status") or "") == "conflicted" else "no_admitted_memory_covers_the_question"
        stages.append(_stage_ok(
            "output_renderer_eligibility_check",
            {"executed": True, "rendering_allowed": False, "blocked": True, "reason": blocked_reason},
            executed=True,
            reason=blocked_reason,
        ))
    else:
        try:
            from rmc_engine_v1.output_renderer import render_output
            manifest = _live_manifest(str(claim["text"]), phase_path, epsilon, claim.get("memory_id"), reading)
            render_report = _as_dict(render_output(manifest, audience_profile="operator", style_mode="standard", render_mode="text"))
            artifacts["output_renderer"] = render_report
            rendered = render_report.get("R_t") or _as_dict(render_report.get("render_packet")).get("R_t")
            stages.append(_stage_ok(
                "output_renderer_eligibility_check",
                render_report,
                executed=True,
                rendered=bool(rendered),
                calls_llm=False,
            ))
        except Exception as exc:
            stages.append(_stage_error("output_renderer_eligibility_check", exc))
    echo_report: dict[str, Any] = {}
    rendered_text = str(render_report.get("R_t") or _as_dict(render_report.get("render_packet")).get("R_t") or "")
    if not render_report or not rendered_text:
        stages.append(_stage_ok(
            "echo_validation_eligibility_check",
            {"executed": True, "echo_validation_passed": False, "reason": "no_rendered_answer"},
            executed=True,
            reason="no_rendered_answer",
        ))
    else:
        try:
            from rmc_engine_v1.echo_validator import validate_echo
            echo_report = _as_dict(validate_echo(render_report))
            artifacts["echo_validator"] = echo_report
            stages.append(_stage_ok(
                "echo_validation_eligibility_check",
                echo_report,
                executed=True,
                echo_validation_passed=bool(echo_report.get("echo_validation_passed")),
                calls_llm=False,
            ))
        except Exception as exc:
            stages.append(_stage_error("echo_validation_eligibility_check", exc))
    write_allowed = bool(route_result.get("memory_write_allowed")) and not sealed and bool(echo_report.get("echo_validation_passed"))
    if not write_allowed:
        stages.append(_stage_ok(
            "memory_write_eligibility_check",
            {"executed": True, "memory_write_committed": False, "reason": "echo_or_route_blocks_memory_write"},
            executed=True,
            reason="echo_or_route_blocks_memory_write",
        ))
    else:
        try:
            from rmc_engine_v1.memory_writer import plan_memory_write
            plan = _as_dict(plan_memory_write(echo_report))
            artifacts["memory_writer"] = plan
            stages.append(_stage_ok(
                "memory_write_eligibility_check",
                plan,
                executed=True,
                memory_write_committed=False,
                calls_llm=False,
            ))
        except Exception as exc:
            stages.append(_stage_error("memory_write_eligibility_check", exc))
    artifacts["admitted_claim"] = claim
    artifacts["rendered_answer"] = rendered_text
    return stages, artifacts


def _offer_language_core(question: str, trace_spine: dict[str, Any], phase_report: dict[str, Any], candidate_report: dict[str, Any], stages: list[dict[str, Any]], artifacts: dict[str, Any]) -> None:
    """Run the language-core functions and offer a candidate when the unchanged gate would pass."""
    from rmc_engine_v1.language_core_orchestration import orchestrate, scoring_candidate
    from rmc_engine_v1.measurement_kernel import coherence_components, measure_candidate
    from rmc_engine_v1.mobile_config import THRESHOLDS
    from rmc_engine_v1.rmc_core import echo_against_question

    recall = _as_dict(_as_dict(trace_spine.get("memory_recall")).get("memory_state"))
    active = recall.get("active_memory_nodes") if isinstance(recall.get("active_memory_nodes"), list) else []
    observed = recall.get("admitted_for_observe") if isinstance(recall.get("admitted_for_observe"), list) else []
    # The chain may walk every trusted fact. The scorer's memory_fit is the
    # active phase-aligned set, which is the same set the other candidates use.
    nodes = observed or active
    chain = orchestrate(question, nodes, phase_report if isinstance(phase_report, dict) else None)
    public = {
        "function": chain.get("function"),
        "module": chain.get("module"),
        "cite": chain.get("cite"),
        "calls_llm": False,
        "model_invoked": False,
        "os_process": False,
        "christping_initiated": False,
        "christping_owner": "gilligan_only",
        "speech_act": chain.get("speech_act"),
        "chat": chain.get("chat"),
        "inference": chain.get("inference"),
        "lifecycle": chain.get("lifecycle"),
        "hops": chain.get("hops"),
        "claim": chain.get("claim"),
        "anchors_connected": chain.get("anchors_connected"),
        "gap": chain.get("gap"),
        "debate": chain.get("debate"),
        "admitted_candidate": False,
        "candidate_id": None,
    }
    from rmc_engine_v1.language_core_debate import run_debate
    from rmc_engine_v1.world_model_v1 import content_tokens, parse_sentence

    best = None
    best_score = -1.0
    best_measured = None
    best_parts = None
    best_echo = None
    for hop in chain.get("hops") or []:
        if not isinstance(hop, dict):
            continue
        text = str(hop.get("text") or "").strip()
        if not text:
            continue
        try:
            eps_hop = float(hop.get("eps") or 0.0)
        except (TypeError, ValueError):
            eps_hop = 0.0
        disposition = "clean" if eps_hop <= float(THRESHOLDS["drift_quarantine"]) else "quarantine"
        parsed = parse_sentence(text)
        atom = (parsed or {}).get("atom") or {"predicate": "stated", "args": [text], "polarity": "pos"}
        debated = run_debate({
            "text": text,
            "atom": atom,
            "status": "supported_only",
            "checker_ok": disposition == "clean",
            "checker_reason": "the claim is the trusted fact",
            "premises": [
                {"id": h.get("memory_id"), "text": h.get("text"), "quarantined": False}
                for h in (chain.get("hops") or []) if isinstance(h, dict)
            ],
            "drift": {"epsilon_s": eps_hop, "disposition": disposition},
        }, content_tokens=content_tokens)
        if debated.get("survived") is not True:
            continue
        echo = echo_against_question(question, text, rendered=True)
        # 4.9.241 (plan 229 step 10): no Echo bypass. A language-core sentence is offered only when its own Echo passes:
        # a greeting by structural Echo for speech acts, anything else by the question Echo.
        if hop.get("speech_act") == "greeting":
            from rmc_engine_v1.structural_echo import speech_act_score
            echo = speech_act_score(question, text)
        if not echo.get("pass"):
            continue
        cand = scoring_candidate({"claim": text, "debate": debated}, hop)
        if cand is None:
            continue
        # 4.9.241: no synthetic high-confidence node for a self sentence; every offer is measured against the recalled nodes
        measure_nodes = list(active or nodes)
        measured = measure_candidate(cand, candidate_report, memory_nodes=measure_nodes)
        # 4.9.235: the candidate's novelty is the kernel's measured novelty_delta.
        cand["novelty"] = _number(measured.get("novelty_delta"), 0.0)
        parts = coherence_components(cand, measured)
        eps = _number(measured.get("epsilon_s"), 1.0)
        score = _number(parts.get("coherence_score"), 0.0)
        public["premeasure"] = {
            "C": score,
            "epsilon_s": eps,
            "memory_fit": parts.get("memory_fit"),
            "utility_fit": parts.get("utility_fit"),
            "bounded": bool(measured.get("bounded_evolutionary_drift")),
            "circuit_breaker": bool(measured.get("circuit_breaker")),
            "formula": parts.get("formula"),
        }
        public["echo_precheck"] = {"score": echo.get("score"), "pass": True, "min": echo.get("min")}
        if not (
            measured.get("bounded_evolutionary_drift")
            and not measured.get("circuit_breaker")
            and score >= float(THRESHOLDS["C_min"])
            and eps <= float(THRESHOLDS["drift_quarantine"])
            and score > best_score
        ):
            continue
        best = cand
        best_score = score
        best_measured = measured
        best_parts = parts
        best_echo = echo
    if best is not None and best_measured is not None and best_parts is not None:
        # The stored trace drops the sentence body. Keep the measurement
        # taken against the live active nodes. The formula is unchanged.
        best["measurement_kernel"] = best_measured
        rowset = candidate_report.get("candidate_set")
        if not isinstance(rowset, list):
            rowset = []
            candidate_report["candidate_set"] = rowset
        rowset.append(best)
        public["claim"] = best.get("candidate")
        public["candidate_id"] = best.get("candidate_id")
        public["admitted_candidate"] = True
        public["debate"] = {"survived": True, "calls_llm": False, "order": ["proponent", "opponent"]}
        public["premeasure"] = {
            "C": best_score,
            "epsilon_s": best_measured.get("epsilon_s"),
            "memory_fit": best_parts.get("memory_fit"),
            "utility_fit": best_parts.get("utility_fit"),
            "bounded": True,
            "circuit_breaker": False,
            "formula": best_parts.get("formula"),
        }
        public["echo_precheck"] = {"score": (best_echo or {}).get("score"), "pass": True, "min": (best_echo or {}).get("min")}
    artifacts["language_core"] = public
    # The trace records the function. It is not a 17th pipeline stage.
    # Stages stay 16 so the dry-run card's count does not move.


def run_deep_dry_run(
    source_text: str | None = None,
    source_metadata: dict[str, Any] | None = None,
    *,
    root: str | None = None,
    use_protoforge2_preview: bool = True,
    execute_late_stages: bool = False,
) -> dict[str, Any]:
    """Run a read-only full-stack dry-run using installed RMC modules.

    The return object is intentionally verbose because the UI/operator should be
    able to audit every stage. No stage in this function commits data or emits
    approved output.
    """
    source_metadata = dict(source_metadata or {})
    source_metadata.setdefault("source", "patch273_interactive_deep_dry_run")
    source_text, interactive_request = _resolve_interactive_request(source_text, source_metadata)
    source_metadata.update({
        "interactive_scenario_panel": True,
        "scenario_id": interactive_request.get("scenario_id"),
        "scenario_label": interactive_request.get("scenario_label"),
        "operator_input_supplied": interactive_request.get("operator_input_supplied"),
        "grants_authority": False,
    })
    run_id = f"rmcddr_{_sha({'text': source_text, 'meta': source_metadata})}"
    stages: list[dict[str, Any]] = []
    artifacts: dict[str, Any] = {}

    input_event = _make_input_stage(source_text, source_metadata)
    artifacts["input_event"] = input_event
    stages.append(_stage_ok("input_event", input_event))

    # Trace spine includes phase parser, memory recall, and structural drift in one read-only call.
    trace_spine: dict[str, Any] = {}
    try:
        from rmc_engine_v1.memory_recaller import build_trace_spine
        remembered_overlap = []
        if root:
            from pathlib import Path as _Path
            from rmc_engine_v1.world_model_v1 import content_tokens as _ctoks
            _qtoks = _ctoks(source_text or "")
            _rdir = _Path(root) / "memory" / "context_library_v1" / "receipts"
            if _rdir.is_dir() and _qtoks:
                for _path in sorted(_rdir.glob("m*.json")):
                    try:
                        _body = _json.loads(_path.read_text(encoding="utf-8"))
                    except Exception:
                        continue
                    if str(_body.get("filename") or "") != "phone_kb":
                        continue
                    _text = str(_body.get("text") or "").strip()
                    if _text and (_ctoks(_text) & _qtoks):
                        remembered_overlap.append(_body)
        trace_value = build_trace_spine(source_text, source_metadata, root=root, limit=48)
        trace_spine = _as_dict(trace_value)
        artifacts["trace_spine"] = trace_spine
        stages.append(_stage_ok("memory_recall_trace_spine", trace_spine))
    except Exception as exc:
        stages.append(_stage_error("memory_recall_trace_spine", exc))

    # Phase parser explicit stage, even when trace spine already performed it.
    phase_report: dict[str, Any] = _as_dict(trace_spine.get("phase_report"))
    try:
        from rmc_engine_v1.phase_parser import parse_phase
        parsed = parse_phase(source_text, source_metadata)
        phase_report = _as_dict(parsed) or phase_report
        artifacts["phase_report"] = phase_report
        stages.append(_stage_ok("phase_parser", phase_report))
    except Exception as exc:
        if phase_report:
            stages.append(_stage_ok("phase_parser", phase_report, note="phase_report_from_trace_spine"))
        else:
            stages.append(_stage_error("phase_parser", exc))

    structural_drift: dict[str, Any] = _as_dict(trace_spine.get("drift_report"))
    try:
        from rmc_engine_v1.drift_engine import analyze_drift
        drift_value = analyze_drift(phase_report)
        structural_drift = _as_dict(drift_value) or structural_drift
        artifacts["structural_drift"] = structural_drift
        stages.append(_stage_ok("structural_drift_engine", structural_drift))
        from rmc_engine_v1.lexicon_resonance import apply_lexicon_phase
        phase_report = apply_lexicon_phase(phase_report, source_text)
        from rmc_engine_v1.resonance_recall import settle_subject_phase
        _recall_nodes = (((trace_spine.get("memory_recall") or {}).get("memory_state") or {}).get("active_memory_nodes")) if isinstance(trace_spine, dict) else None
        phase_report = settle_subject_phase(phase_report, _recall_nodes)
        artifacts["phase_report"] = phase_report
    except Exception as exc:
        if structural_drift:
            stages.append(_stage_ok("structural_drift_engine", structural_drift, note="drift_report_from_trace_spine"))
        else:
            stages.append(_stage_error("structural_drift_engine", exc))

    pf2_preview: dict[str, Any] = {}
    if use_protoforge2_preview:
        try:
            from rmc_engine_v1.protoforge2_drift_connector import preview_drift_call
            pf2_value = preview_drift_call()
            pf2_preview = {"preview": _as_dict(pf2_value)}
            artifacts["protoforge2_drift_preview"] = pf2_value
            stages.append(_stage_ok("protoforge2_drift_adapter", _as_dict(pf2_value)))
        except Exception as exc:
            stages.append(_stage_error("protoforge2_drift_adapter", exc))
    else:
        stages.append(_stage_skip("protoforge2_drift_adapter", "disabled_by_caller"))

    # Candidate generation needs symbolic trace shape.
    candidate_report: dict[str, Any] = {}
    try:
        from rmc_engine_v1.candidate_generator import generate_candidates
        candidate_value = generate_candidates(trace_spine, max_candidates=8)
        candidate_report = _as_dict(candidate_value)
        artifacts["candidate_report"] = candidate_report
        stages.append(_stage_ok("candidate_generator", candidate_report))
    except Exception as exc:
        candidate_report = {
            "status": "FALLBACK_SYNTHETIC_CANDIDATE_REPORT",
            "trace_id": _as_dict(trace_spine.get("symbolic_trace")).get("trace_id"),
            "candidate_set": [{
                "candidate_id": "patch271_fallback_candidate",
                "candidate": "Fallback candidate because candidate_generator was unavailable during dry run.",
                "phase_path": _phase_path_from_trace(trace_spine, phase_report) or ["Φ1", "Φ6"],
                "epsilon_s": _f(structural_drift.get("epsilon_s"), 0.0),
                "coherence_score": 0.42,
                "read_only": True,
            }],
            "read_only": True,
        }
        artifacts["candidate_report"] = candidate_report
        stages.append(_stage_error("candidate_generator", exc, fallback_used=True))

    _offer_language_core(source_text, trace_spine, phase_report, candidate_report, stages, artifacts)

    evolution_report: dict[str, Any] = {}
    try:
        from rmc_engine_v1.evolutionary_drift_explorer import explore_evolutionary_drift
        evolution_value = explore_evolutionary_drift(candidate_report, max_branches=8)
        evolution_report = _as_dict(evolution_value)
        artifacts["evolutionary_drift_report"] = evolution_report
        stages.append(_stage_ok("evolutionary_drift_explorer", evolution_report))
    except Exception as exc:
        stages.append(_stage_error("evolutionary_drift_explorer", exc))

    coherence_report: dict[str, Any] = {}
    try:
        from rmc_engine_v1.evolutionary_drift_explorer import score_coherence
        coherence_value = score_coherence(evolution_report if evolution_report else {"source_candidate_report": candidate_report})
        coherence_report = _as_dict(coherence_value)
        artifacts["coherence_report"] = coherence_report
        stages.append(_stage_ok("coherence_scorer", coherence_report))
    except Exception as exc:
        stages.append(_stage_error("coherence_scorer", exc))

    selected_candidate = _select_candidate(candidate_report, coherence_report)
    routing_packet = _merge_routing_packet(selected_candidate, trace_spine, structural_drift, pf2_preview, coherence_report)
    artifacts["routing_packet"] = routing_packet

    route_result: dict[str, Any] = {}
    try:
        from rmc_engine_v1.containment_router import route_candidate
        route_value = route_candidate(routing_packet)
        route_result = _as_dict(route_value)
        artifacts["containment_route"] = route_result
        stages.append(_stage_ok("containment_router", route_result))
    except Exception as exc:
        route_result = {
            "status": "ROUTER_UNAVAILABLE_FAIL_CLOSED",
            "route": "drift_archive_only",
            "projection_allowed": False,
            "manifest_compile_allowed": False,
            "echo_validation_allowed": False,
            "memory_write_allowed": False,
            "stable_memory_allowed": False,
            "is_sealed": True,
            "reason_codes": ["containment_router_unavailable_fail_closed"],
            "read_only": True,
        }
        artifacts["containment_route"] = route_result
        stages.append(_stage_error("containment_router", exc, fail_closed=True))

    chi_preview: dict[str, Any] = {}
    chi_required = bool(
        route_result.get("route") in {"correction_queue", "spc_cold_storage_required"}
        or routing_packet.get("epsilon_s", 0) >= 0.35
        or route_result.get("containment_required")
    )
    if chi_required:
        try:
            from rmc_engine_v1.chi_correction_gate import evaluate_chi_t
            chi_input = {
                "epsilon_s": routing_packet.get("epsilon_s"),
                "psi1_trace_ref": "patch271_dry_run_psi1_ref_not_authoritative",
                "phase_path": routing_packet.get("phase_path"),
                "correction_attempt_number": 1,
                "prior_epsilon_series": [0.18, routing_packet.get("epsilon_s", 0.18)],
            }
            chi_value = evaluate_chi_t(chi_input)
            chi_preview = _as_dict(chi_value)
            artifacts["chi_correction_preview"] = chi_preview
            stages.append(_stage_ok("chi_correction_gate_preview", chi_preview))
        except Exception as exc:
            stages.append(_stage_error("chi_correction_gate_preview", exc))
    else:
        stages.append(_stage_skip("chi_correction_gate_preview", "chi_not_required_by_route_or_epsilon"))

    storage_preview, storage_stage = _storage_preview_for_route(route_result, routing_packet)
    if storage_preview is not None:
        artifacts["storage_target_preview"] = storage_preview
    stages.append(storage_stage)

    resurrection_preview, resurrection_stage = _resurrection_preview(storage_preview, route_result)
    if resurrection_preview is not None:
        artifacts["resurrection_eligibility_preview"] = resurrection_preview
    stages.append(resurrection_stage)

    eligibility = _eligibility_checks(route_result)
    artifacts["eligibility"] = eligibility
    stages.append(_stage_ok("manifest_eligibility_check", eligibility, executed=False))
    from rmc_engine_v1.reasoning_seam import run_reasoning_seam
    recall_state = _as_dict(_as_dict(trace_spine.get("memory_recall")).get("memory_state"))
    recalled = int(recall_state.get("active_memory_count") or 0)
    observe_rows = recall_state.get("admitted_for_observe")
    observe_source = observe_rows if isinstance(observe_rows, list) else _recalled_nodes(trace_spine)
    active_ids = {
        n.get("memory_id") for n in (recall_state.get("active_memory_nodes") or [])
        if isinstance(n, dict)
    }
    nodes = []
    for node in observe_source:
        low = str(node.get("confidence") or "") == "low" or _number(node.get("prior_drift_score"), 0.0) >= 0.40
        # An encyclopedia anchor is a premise only when resonance locked it.
        # A low-trust excerpt is never a premise.
        anchor_idle = str(node.get("tier") or node.get("state") or "") == "anchor" and node.get("memory_id") not in active_ids
        low_trust = str(node.get("trust") or "").lower() == "low"
        nodes.append({
            "id": node.get("memory_id"),
            "text": node.get("content_summary") or node.get("content") or "",
            "source": node.get("source") or node.get("source_kind"),
            "confidence": node.get("confidence"),
            "prior_drift_score": node.get("prior_drift_score"),
            "tier": node.get("tier"),
            "trust": node.get("trust"),
            "quarantined": low or anchor_idle or low_trust or node.get("quarantined") is True,
            # 4.9.231 (plan 229 step 3): the clause, the meaning id and the resonance packet (phase, band, Hz) reach Observe
            "clause": node.get("clause") if isinstance(node.get("clause"), dict) else None,
            "meaning_id": node.get("meaning_id"),
            "sim": node.get("sim") if isinstance(node.get("sim"), dict) else None,
            "provenance": node.get("provenance") if isinstance(node.get("provenance"), dict) else None,
            "sensitive": node.get("sensitive") is True,
            "packet": node.get("packet") if isinstance(node.get("packet"), dict) else None,
            "concepts": node.get("concepts") if isinstance(node.get("concepts"), list) else None,
            "sfe": node.get("sfe") if isinstance(node.get("sfe"), dict) else None,
        })
    # A remembered sentence that names something in this question stays a premise when resonance
    # did not rank it. Captured before recall, which keeps the active set small.
    have = {" ".join(str(n.get("text") or "").lower().split()) for n in nodes}
    for body in remembered_overlap:
        text = str(body.get("text") or "").strip()
        key = " ".join(text.lower().split())
        if not text or key in have:
            continue
        have.add(key)
        nodes.append({
            "id": body.get("receipt_id"), "text": text, "source": "phone_kb",
            "confidence": "medium", "prior_drift_score": 0.0, "quarantined": body.get("quarantined") is True,
            "clause": body.get("clause") if isinstance(body.get("clause"), dict) else None,
            "meaning_id": body.get("meaning_id"), "sim": None,
            "provenance": body.get("provenance") if isinstance(body.get("provenance"), dict) else None,
            "sensitive": body.get("sensitive") is True,
        })
    # 4.9.234 (plan 229 step 6): RMC runs into the world model in series. The RMC reading (C, epsilon, route)
    # goes in as the world model's upstream; the sentence the world model speaks is measured and routed by the
    # same kernel and router, and that reading is what the late stages and the Ask gate use.
    from rmc_engine_v1.world_claim_measure import measure_spoken, upstream_reading
    upstream = upstream_reading(coherence_report, routing_packet, route_result)
    reasoning = run_reasoning_seam(source_text, {
        "active": recalled,
        "active_memory_count": recalled,
        "phase_path": _as_list(routing_packet.get("phase_path")),
        "nodes": nodes,
        "upstream": upstream,
    })
    artifacts["reasoning_seam"] = {k: v for k, v in reasoning.items() if k != "memory"}
    late_route = route_result
    try:
        wm_measure = measure_spoken(
            reasoning, observe_source, _as_list(routing_packet.get("phase_path")), upstream,
            trace_spine=trace_spine, structural_drift=structural_drift, pf2_preview=pf2_preview, coherence_report=coherence_report,
        )
    except Exception as exc:
        wm_measure = None
        artifacts["world_model_measure_error"] = type(exc).__name__ + ": " + str(exc)[:240]
    # 4.9.241 (Nic: natural conversation): a turn that opens with an act the speech-act lexicon answers (greet, thank,
    # apologize, farewell) has its responses measured by the same kernel against the lexicon items they realize.
    try:
        from rmc_engine_v1.speech_acts import measure_turn as _act_measure
        act_measure = _act_measure(
            source_text, _as_list(routing_packet.get("phase_path")),
            trace_spine=trace_spine, structural_drift=structural_drift, pf2_preview=pf2_preview, coherence_report=coherence_report,
        )
    except Exception as exc:
        act_measure = None
        artifacts["speech_act_measure_error"] = type(exc).__name__ + ": " + str(exc)[:240]
    if act_measure is not None:
        artifacts["speech_act_measure"] = act_measure
    if wm_measure is not None:
        artifacts["world_model_measure"] = {k: v for k, v in wm_measure.items() if k != "route_result"}
        if isinstance(wm_measure.get("route_result"), dict) and wm_measure["route_result"]:
            late_route = wm_measure["route_result"]
    if execute_late_stages:
        phase_path = _as_list(routing_packet.get("phase_path"))
        late_stages, late_artifacts = _run_late_stages(
            source_text,
            late_route,
            trace_spine,
            _number(routing_packet.get("epsilon_s"), 0.0),
            phase_path,
            reasoning,
            _manifest_reading(coherence_report, wm_measure, _number(routing_packet.get("epsilon_s"), 0.0)),
        )
        stages.extend(late_stages)
        artifacts.update(late_artifacts)
        eligibility = dict(eligibility)
        eligibility["output_renderer_executed"] = bool(late_artifacts.get("rendered_answer"))
        eligibility["late_stages_executed"] = True
        artifacts["eligibility"] = eligibility
    else:
        stages.append(_stage_skip("output_renderer_eligibility_check", "renderer_not_executed_in_patch271_dry_run", output_renderer_allowed=False))
        stages.append(_stage_skip("echo_validation_eligibility_check", "echo_not_executed_in_patch271_dry_run", echo_validation_allowed=eligibility.get("echo_validation_allowed")))
        stages.append(_stage_skip("memory_write_eligibility_check", "memory_write_not_executed_in_patch271_dry_run", memory_write_allowed=eligibility.get("memory_write_allowed")))

    violations = _detect_forbidden_effect_violations(stages, artifacts, route_result, eligibility)
    completed = not violations and bool(route_result)

    return {
        "status": "DRY_RUN_COMPLETE" if completed else "DRY_RUN_COMPLETED_WITH_BOUNDARY_WARNINGS",
        "endpoint": "/api/rmc/deep-dry-run",
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "run_id": run_id,
        "run_at_utc": _utc(),
        "stage_count": len(stages),
        "pipeline_order": PIPELINE_ORDER,
        "interactive_request": interactive_request,
        "stages": stages,
        "artifacts": artifacts,
        "final_route": route_result,
        "eligibility": eligibility,
        "forbidden_effect_violations": violations,
        "deep_stack_modules_exercised": _modules_exercised(stages),
        "activation_ready_next_step": bool(completed),
        "activation_note": "This dry-run proves cross-module routing only. It does not activate live pipeline mutation.",
        "boundary": boundary(),
        "read_only": True,
        **FORBIDDEN_EFFECTS,
    }


def _modules_exercised(stages: list[dict[str, Any]]) -> dict[str, bool]:
    return {stage_id: any(s.get("stage_id") == stage_id and s.get("status") == "OK" for s in stages) for stage_id in PIPELINE_ORDER}


def _detect_forbidden_effect_violations(
    stages: list[dict[str, Any]],
    artifacts: dict[str, Any],
    route_result: dict[str, Any],
    eligibility: dict[str, Any],
) -> list[dict[str, Any]]:
    violations: list[dict[str, Any]] = []
    for key, expected in FORBIDDEN_EFFECTS.items():
        observed_values = []
        for obj in [route_result, eligibility, artifacts.get("storage_target_preview"), artifacts.get("resurrection_eligibility_preview")]:
            if isinstance(obj, dict) and key in obj:
                observed_values.append(obj.get(key))
        # Several modules use alternative names.
        if key == "active_runtime_reentry":
            for obj in [artifacts.get("resurrection_eligibility_preview"), route_result]:
                if isinstance(obj, dict):
                    if "re_enters_active_runtime" in obj:
                        observed_values.append(obj.get("re_enters_active_runtime"))
                    if "active_runtime_reentry_allowed" in obj:
                        observed_values.append(obj.get("active_runtime_reentry_allowed"))
        if any(v is True for v in observed_values) and expected is False:
            violations.append({"field": key, "expected": expected, "observed_values": observed_values})
    # A sealed route must not report manifest eligibility.
    if route_result.get("is_sealed") and eligibility.get("manifest_compile_allowed"):
        violations.append({"field": "sealed_route_manifest_compile_allowed", "expected": False, "observed": True})
    return violations


def summarize_dry_run(report: dict[str, Any]) -> dict[str, Any]:
    stages = _as_list(report.get("stages"))
    return {
        "status": report.get("status"),
        "engine_version": report.get("engine_version"),
        "stage_count": len(stages),
        "ok_stages": [s.get("stage_id") for s in stages if isinstance(s, dict) and s.get("status") == "OK"],
        "skipped_stages": [s.get("stage_id") for s in stages if isinstance(s, dict) and s.get("status") == "SKIPPED"],
        "error_stages": [s.get("stage_id") for s in stages if isinstance(s, dict) and s.get("status") == "ERROR"],
        "final_route": _as_dict(report.get("final_route")).get("route"),
        "manifest_compile_allowed": _as_dict(report.get("eligibility")).get("manifest_compile_allowed"),
        "projection_allowed": report.get("projection_allowed"),
        "memory_write_committed": report.get("memory_write_committed"),
        "forbidden_effect_violation_count": len(_as_list(report.get("forbidden_effect_violations"))),
    }

files.rmc_engine_v1/derive_frame.py:
"""4.9.233 (plan 229 step 5): Derive matches a fact to the question by frame AND by phase/band alignment.

Frame. The phone's question frame (forge.qframe/v1, via question_frame.current()) names the kriyā, the known roles
and the gap (the indefinite pro-form "something"/"someone"). A fact's frame is its clause frame (4.9.232), the roles of
a clause that did not cover every word (role_frame), or the two arguments of an is() atom. A fact answers only when
the kriyā is the same, every known role of the question unifies with the fact's role (same head, the question's words
inside the fact's phrase, the same owner), and the gap role is filled. Copula: "What is X?" reads X as the fact's kartṛ;
a definite X ("the capital of France") may also be the fact's predicate (a specificational copula). A polar question
needs both roles. One relational-noun rule, WM-NAME-OF: "X's name" is the proper-noun predicate of a copula fact on X.

Alignment. The fact's placement (place_row: Φ, ε, μ, band, Hz) against each phase on the question's phase path:
resonance grace rpm·cos²δ with δ ≤ π/4 (resonance_recall._grace), the band relation same/x3/x9/none
(band_tuning.relation), and the 4.9.204 frequency attraction between the fact's Hz and the question's tuned Hz
(frequency_204.attract_dh). A frame match that is not phase-aligned does not answer. Word coverage is only a logged
tie-break. Nothing here calls a model.

4.9.236 — Memory Phase Invariance with Contextual Phase Alignment (Nic). A memory keeps its native content phase
Φ_identity; nothing here rewrites it. Φ_query is the phase of the cognitive operation (retrieval of a stored memory is
Φ7, codex "Naming: identity, aligned declaration"), not of the question's text. ΔΦ = Φ_query − Φ_identity is computed
per ask and never stored. A match answers by G = f(ΔΦ, S, C): S = the frame match (semantic), C = contextual coherence
(replayed proof, debate, no conflict, no quarantine, possessor scope). ΔΦ is one factor, A = (1 + cos ΔΦ)/2, that ranks
and weights; it never vetoes, and it can never create a match: G = 0 whenever S or C fails.
"""
from __future__ import annotations

import math
import re
from typing import Any

RULE_NAME_OF = "WM-NAME-OF"
RULE_OWNER_OF = "WM-OWNER-OF"
# 4.9.236: the phase of each cognitive operation Derive performs. Only one operation runs here: retrieval of stored
# memory (direct facts, the premises a chain is built from, a relational rule over a stored fact). Nic: Φ7 for retrieval.
OPERATION_PHASE = {"retrieve": 7}
PHASE_STEP_DEG = 40.0  # nine phases on the circle
# a first-person memory is the asker's only when it came from the asker's device (personal facts stay on the device)
PERSONAL_SOURCES = frozenset({"phone_kb", "world_facts"})
# 4.9.241 (plan 229 step 10): the kernel's facts about itself, stored as clauses (src/selfmodel.js FACTS, sent as memory.self)
SELF_SOURCES = frozenset({"self_model"})
RULE_PRO_VERB = "WM-PRO-VERB"
RULE_CONVERSE = "polar_converse"
NOT_NECESSARILY = "not necessarily"
_FIRST_PERSON = re.compile(r"(?i)\b(i|me|my|mine|myself|our|ours|we|us)\b")
_POSSESSIVE = re.compile(r"(?i)^\s*(my|our|([A-Z][A-Za-z'\-]*)'s)\s+(.+)$")
_DETS = {"the", "a", "an", "some", "this", "that", "these", "those"}
_STOP = {"of", "is", "are", "was", "were", "be", "and", "or", "to", "in", "on", "at", "for", "with", "by", "my", "your",
         "his", "her", "its", "their", "our", "'s", "s"}


def _sing(word: str) -> str:
    w = str(word or "").lower().strip("'")
    if w.endswith("'s"):
        w = w[:-2]
    if len(w) > 4 and w.endswith("ies"):
        return w[:-3] + "y"
    if len(w) > 3 and w.endswith("s") and not w.endswith("ss") and not w.endswith("us"):
        return w[:-1]
    return w


def _words(text: str) -> set[str]:
    return {_sing(w) for w in re.findall(r"[A-Za-z][A-Za-z'\-]*", str(text or "")) if w.lower() not in _DETS and w.lower() not in _STOP}


def _head(np: dict[str, Any]) -> str:
    head = np.get("head") or np.get("propn")
    if not head:
        ws = [w for w in re.findall(r"[A-Za-z][A-Za-z'\-]*", str(np.get("text") or "")) if w.lower() not in _DETS]
        head = ws[-1] if ws else ""
    return _sing(str(head))


def _owner_user(np: dict[str, Any]) -> bool:
    owner = np.get("owner")
    return owner == "user" or bool(np.get("user")) or bool(re.match(r"(?i)\s*(my|i)\b", str(np.get("text") or "")))


def negated(np: Any) -> bool:
    """4.9.241: a noun phrase under the negative quantifier ("no body", "no emotions") negates its clause: "I have no
    body" answers "Do you have a body?" with no, not yes (English: the quantifier carries the clause's polarity)."""
    if not isinstance(np, dict):
        return False
    q = str(np.get("quant") or np.get("det") or "").lower()
    return q == "no" or bool(re.match(r"(?i)\s*no\s+\w", str(np.get("text") or "")))


def polarity_of(frame: dict[str, Any]) -> str:
    """The clause's polarity with a negative quantifier on its object counted (4.9.241)."""
    pol = str(frame.get("polarity") or "pos")
    if negated(frame.get("karma")) or negated(frame.get("pred")):
        pol = "neg" if pol == "pos" else "pos"
    return pol


def kind_inclusion(fs: Any, fp: Any) -> bool:
    """4.9.241: a copula whose subject is a generic (an indefinite or a bare plural, not a particular) and whose predicate is
    an indefinite kind ("a whale is a living thing") states that the first kind is included in the second. Its converse
    ("a living thing is a whale") is neither stated nor denied by it: the honest answer is "not necessarily"."""
    def generic(np: Any) -> bool:
        return isinstance(np, dict) and not referring(np) and not np.get("propn") and bool(str(np.get("text") or "").strip()) \
            and (str(np.get("det") or "").lower() in ("a", "an") or bool(np.get("plural")))
    return generic(fs) and generic(fp)


def is_gap(np: Any) -> bool:
    return isinstance(np, dict) and bool(np.get("indef"))


def np_unify(q: Any, f: Any) -> bool:
    """A known question role and a fact role name the same thing."""
    if not isinstance(q, dict) or not isinstance(f, dict) or not str(f.get("text") or "").strip():
        return False
    if _owner_user(q) != _owner_user(f):
        return False
    # A numeral has no alphabetic token, so an empty word set would match every other empty phrase.
    if q.get("num") or f.get("num") or not _words(str(q.get("text") or "")) or not _words(str(f.get("text") or "")):
        if " ".join(str(q.get("text") or "").lower().split()) != " ".join(str(f.get("text") or "").lower().split()):
            return False
    # 4.9.240: the genitive of-phrase is the possessive ("the name of my dog" = "my dog's name"): one possessor slot
    qo, fo = genitive(q), genitive(f)
    if isinstance(qo, dict) and not (isinstance(fo, dict) and np_unify(qo, fo)):
        return False
    if _head(q) != _head(f):
        return False
    qw, fw = _words(q.get("text")), _words(f.get("text"))
    for sub in ("of", "owner"):
        if isinstance(f.get(sub), dict):
            fw |= _words(f[sub].get("text"))
    return qw <= fw


def genitive(np: Any) -> dict[str, Any] | None:
    """4.9.240: the possessor of a noun phrase, whether written as a possessive ("my dog's name": owner) or as a genitive
    of-phrase ("the name of my dog": of). English grammar, not a list: both name the same possessor slot."""
    if not isinstance(np, dict):
        return None
    if isinstance(np.get("owner"), dict):
        return np["owner"]
    if isinstance(np.get("of"), dict):
        return np["of"]
    return None


_DEFINITE = frozenset({"the", "this", "that", "these", "those", "my", "your", "his", "her", "its", "our", "their"})


def referring(np: Any) -> bool:
    """4.9.240: a noun phrase that names one particular thing: a proper name, a possessive, a definite determiner, the
    speaker or the kernel. An indefinite ("a whale"), a bare plural ("whales") or a bare mass noun names a kind or a
    member of one, not a particular."""
    if not isinstance(np, dict) or not str(np.get("text") or "").strip():
        return False
    if np.get("propn") or np.get("user") or np.get("kernel") or np.get("owner"):
        return True
    return str(np.get("det") or "").lower() in _DEFINITE


def identity(a: Any, b: Any) -> bool:
    """4.9.240: a copula between two referring phrases ("Rex is my dog") states identity, which runs both ways. A copula
    whose predicate (or subject) names a kind or a member of one ("a whale is a living thing") states membership or
    inclusion, which does not: "a living thing is a whale" does not follow."""
    return referring(a) and referring(b)


def _specific(np: dict[str, Any]) -> bool:
    return str(np.get("det") or "").lower() == "the" or isinstance(np.get("of"), dict) or isinstance(np.get("owner"), dict)


def _atom_np(text: str) -> dict[str, Any]:
    """A noun phrase read off an atom string. A sentence-initial capital is not a name when the phrase
    starts with a possessive determiner: "My pet" is the asker's pet, the same noun the question frame
    parses as head pet, owner user. A bare capitalised name ("Rex", "New York") stays a proper noun."""
    t = str(text or "").strip()
    first = t.split()[0].lower() if t.split() else ""
    poss = _POSSESSIVE.match(t)
    out: dict[str, Any] = {"text": t, "det": first if first in _DETS or poss else None}
    m = re.match(r"(?i)(.+?)\s+of\s+(.+)$", t)
    if m:
        ws = [w for w in m.group(1).split() if w.lower() not in _DETS]
        out["head"] = ws[-1] if ws else None
        out["of"] = {"text": m.group(2)}
    if poss and not out.get("head"):
        rest = [w for w in str(poss.group(3) or "").split() if w.lower() not in _DETS]
        if rest:
            out["head"] = rest[-1]
        if str(poss.group(1) or "").lower() == "my":
            out["owner"] = "user"
    elif t[:1].isupper() and first not in _DETS and len(t.split()) <= 3:
        out["propn"] = t
    return out


# 4.9.238 (Nic): "look" is a linking verb when an attribute is asked ("the sky looks blue" states the sky's colour as it
# appears). It links its subject to a bare complement (no determiner, no owner, not a name), which the phone grammar reads
# as its karma. Only an attribute question may read it as the copula; "What is the sky?" is not answered by how it looks.
LINKING_VERBS = frozenset({"look"})


def _value_rule(kind: Any) -> dict[str, Any] | None:
    """The lexicon's value rule for an attribute noun (concept_lexicon.json values: "a colour word is a value of colour")."""
    from rmc_engine_v1.echo_question import _lex
    lex = _lex()
    cid = (lex.get("surfaces") or {}).get(_sing(str(kind or "")))
    rule = (lex.get("values") or {}).get(cid or "")
    return rule if isinstance(rule, dict) else None


def is_value_of(kind: Any, np: Any) -> bool:
    """The filler is a value of the asked attribute by the lexicon (blue is a colour); never by the question's words."""
    rule = _value_rule(kind)
    if not rule or not isinstance(np, dict) or not str(np.get("text") or "").strip():
        return False
    from rmc_engine_v1.echo_question import _fills_slot
    return bool(_fills_slot(rule, str(np.get("text"))))


# 4.9.242 (plan 229 step 11): a filler is shown to be an N when its head is N, or when its WordNet gloss classifies
# it as an N (e.g. beagle: "a small … breed of hound"). No closed value list; the genus noun in the gloss is the kind.
_GLOSS_CACHE: dict[str, list[str]] | None = None


def _noun_glosses(lemma: str) -> list[str]:
    """Noun glosses of a lemma. Prefers the engine-packaged kind_member_glosses.json (ships in the Pyodide
    bundle); falls back to the phone WordNet packs under data/ when present. No network, no model."""
    global _GLOSS_CACHE
    import json
    from pathlib import Path
    if _GLOSS_CACHE is None:
        _GLOSS_CACHE = {}
        here = Path(__file__).resolve().parent
        packaged = here / "kind_member_glosses.json"
        if packaged.is_file():
            try:
                doc = json.loads(packaged.read_text(encoding="utf-8"))
                if isinstance(doc, dict):
                    for lem, glosses in doc.items():
                        if isinstance(glosses, list) and glosses:
                            _GLOSS_CACHE[str(lem).lower()] = [str(g) for g in glosses if g]
            except Exception:
                pass
        root = here.parents[1] / "data"  # source/data when running from source/engine
        for name in ("lexicon.json", "lexicon-ext.json"):
            path = root / name
            if not path.is_file():
                continue
            try:
                doc = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                continue
            L = doc.get("L") if isinstance(doc, dict) else None
            if not isinstance(L, dict):
                continue
            for lem, entry in L.items():
                glosses: list[str] = []
                for row in entry or []:
                    if not isinstance(row, (list, tuple)) or not row or row[0] != "n":
                        continue
                    for sense in (row[1] or []):
                        if isinstance(sense, (list, tuple)) and len(sense) >= 3 and sense[2]:
                            glosses.append(str(sense[2]))
                if glosses:
                    _GLOSS_CACHE.setdefault(str(lem).lower(), [])
                    for g in glosses:
                        if g not in _GLOSS_CACHE[str(lem).lower()]:
                            _GLOSS_CACHE[str(lem).lower()].append(g)
    return list((_GLOSS_CACHE or {}).get(_sing(lemma), []) or [])


def is_kind_member(kind: Any, np: Any) -> bool:
    """True when the NP is shown to be an instance/member of kind N: its head is N, or a noun gloss classifies it as N."""
    if not isinstance(np, dict) or not str(np.get("text") or "").strip():
        return False
    k = _sing(str(kind or ""))
    head = _head(np)
    if not k or not head:
        return False
    if head == k:
        return True
    # gloss classifies the referent as a K: "a … breed of hound", "any of several breeds …"
    pat = re.compile(r"\b" + re.escape(k) + r"\b")
    for g in _noun_glosses(head):
        if pat.search(g.lower()):
            return True
    return False


def _bare(np: Any) -> bool:
    if not isinstance(np, dict) or not str(np.get("text") or "").strip():
        return False
    first = str(np["text"]).split()[0].lower()
    return first not in _DETS and not np.get("owner") and not np.get("propn") and not np.get("det")


def _complement(fframe: dict[str, Any]) -> dict[str, Any] | None:
    """The subject complement of a copula or linking-verb fact: its predicate, or a linking verb's bare karma."""
    fk = str(fframe.get("kriya") or "").lower()
    if isinstance(fframe.get("pred"), dict) and str(fframe["pred"].get("text") or "").strip():
        return fframe["pred"]
    if fk in LINKING_VERBS and _bare(fframe.get("karma")):
        return fframe["karma"]
    return None


def attribute_of(qframe: dict[str, Any], fframe: dict[str, Any]) -> dict[str, Any] | None:
    """An attribute question over a copula or linking-verb fact. "What color is X?" (gap pred of kind K) and "What is the K
    of X?" (kartṛ "the K of X", gap pred) are answered by a fact "X is/looks V" whose complement V is a value of K by the
    lexicon. X must unify with the fact's kartṛ. A kind with no value rule (breed) is not an attribute here."""
    if (fframe.get("polarity") or "pos") != "pos":
        return None
    qs, qp = qframe.get("kartr"), qframe.get("pred")
    fs = fframe.get("kartr")
    comp = _complement(fframe)
    if not (is_gap(qp) and isinstance(qs, dict) and not is_gap(qs) and comp is not None):
        return None
    linking = str(fframe.get("kriya") or "").lower() in LINKING_VERBS
    if qp.get("kind") and np_unify(qs, fs) and is_value_of(qp["kind"], comp):
        return {"roles": 1, "gap": "pred", "filler": comp.get("text"), "orientation": "kartr=kartr", "rule": "attribute_kind",
                "kind": str(qp["kind"]), "linking": linking}
    of = genitive(qs)  # 4.9.240: "the colour of the sky" and "the sky's colour" name the same possessor
    if of and _specific(qs) and np_unify(of, fs) and is_value_of(_head(qs), comp):
        return {"roles": 1, "gap": "pred", "filler": comp.get("text"), "orientation": "of=kartr", "rule": "attribute_of",
                "kind": _head(qs), "linking": linking}
    return None


def fact_frame(fact: dict[str, Any]) -> tuple[dict[str, Any] | None, str]:
    """The frame a fact is matched on, and where it came from."""
    if isinstance(fact.get("frame"), dict) and fact["frame"].get("kartr"):
        return fact["frame"], "clause"
    if isinstance(fact.get("role_frame"), dict) and fact["role_frame"].get("kartr"):
        return fact["role_frame"], "clause_roles"
    atom = fact.get("atom") or {}
    args = atom.get("args") or []
    if atom.get("predicate") == "in" and len(args) >= 2:
        return contain_frame(atom), "atom"
    if atom.get("predicate") == "is" and len(args) >= 2:
        return {"kriya": "be", "polarity": atom.get("polarity") or "pos", "kartr": _atom_np(args[0]), "pred": _atom_np(args[1])}, "atom"
    if atom.get("predicate") and len(args) >= 2:
        return {"kriya": str(atom["predicate"]), "polarity": atom.get("polarity") or "pos", "kartr": _atom_np(args[0]), "karma": _atom_np(args[1])}, "atom"
    return None, "none"


CONTAIN_PREPS = frozenset({"inside", "within"})


def _contain_inner(pred: Any) -> dict[str, Any] | None:
    if not isinstance(pred, dict) or str(pred.get("type") or "") != "pp":
        return None
    if str(pred.get("prep") or "").lower() not in CONTAIN_PREPS:
        return None
    inner = pred.get("np") if isinstance(pred.get("np"), dict) and str(pred["np"].get("text") or "").strip() else None
    if inner:
        return inner
    text = str(pred.get("text") or "").strip()
    return {"text": text, "head": pred.get("head") or text} if text else None


def _adjunct_np(frame: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(frame, dict):
        return None
    for adj in frame.get("adj") or []:
        if isinstance(adj, dict) and isinstance(adj.get("np"), dict) and str(adj["np"].get("text") or "").strip():
            return adj["np"]
    return None


def contain_roles(frame: dict[str, Any] | None) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """(content, container) when the frame is the containment relation, from either reading."""
    if not isinstance(frame, dict):
        return None, None
    kriya = str(frame.get("kriya") or "").lower()
    if kriya == "contain":
        return frame.get("karma") if isinstance(frame.get("karma"), dict) else None, frame.get("kartr") if isinstance(frame.get("kartr"), dict) else None
    if kriya == "be":
        return frame.get("kartr") if isinstance(frame.get("kartr"), dict) else None, _contain_inner(frame.get("pred"))
    return None, None


def live_place(frame: dict[str, Any] | None) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """(resident, place) when the frame is the verb live with an adhikarana in-phrase. inside/on/at are not residence."""
    if not isinstance(frame, dict) or str(frame.get("kriya") or "").lower() != "live":
        return None, None
    for adj in frame.get("adj") or []:
        if isinstance(adj, dict) and str(adj.get("prep") or "").lower() == "in" and str(adj.get("role") or "") == "adhikarana" and isinstance(adj.get("np"), dict):
            return frame.get("kartr") if isinstance(frame.get("kartr"), dict) else None, adj["np"]
    return None, None


def geo_places(frame: dict[str, Any] | None) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """(place, region) for copular in only when the grammar filed both names as lexicon locations."""
    if not isinstance(frame, dict) or str(frame.get("kriya") or "").lower() != "be":
        return None, None
    pred = frame.get("pred")
    if not isinstance(pred, dict) or str(pred.get("type") or "") != "pp" or str(pred.get("prep") or "").lower() != "in":
        return None, None
    left = frame.get("kartr") if isinstance(frame.get("kartr"), dict) else None
    right = pred.get("np") if isinstance(pred.get("np"), dict) else None
    if left and left.get("loc") and right and right.get("loc"):
        return left, right
    return None, None


def contain_frame(conclusion: dict[str, Any]) -> dict[str, Any]:
    """The inner reading of a derived in(content, container) atom: kartṛ content, PP predicate inside container."""
    args = [str(a) for a in (conclusion.get("args") or ["", ""])]
    inner = _atom_np(args[1] if len(args) > 1 else "")
    return {"kriya": "be", "polarity": conclusion.get("polarity") or "pos", "kartr": _atom_np(args[0] if args else ""),
            "pred": {"type": "pp", "prep": "inside", "text": inner.get("text"), "np": inner}, "derived": True}


def chain_frame(first: dict[str, Any], second: dict[str, Any], conclusion: dict[str, Any]) -> dict[str, Any]:
    """A copula-chain conclusion's frame: the first premise's kartṛ and the second premise's predicate."""
    f1, _ = fact_frame(first)
    f2, _ = fact_frame(second)
    args = conclusion.get("args") or ["", ""]
    kartr = (f1 or {}).get("kartr") or _atom_np(args[0])
    pred = (f2 or {}).get("pred") or _atom_np(args[1])
    return {"kriya": "be", "polarity": "pos", "kartr": kartr, "pred": pred, "derived": True}


def match(qframe: dict[str, Any] | None, fframe: dict[str, Any] | None) -> dict[str, Any] | None:
    """Unify the question frame with a fact frame. None when they do not unify."""
    if not isinstance(qframe, dict) or not isinstance(fframe, dict):
        return None
    qk = str(qframe.get("kriya") or "").lower()
    fk = str(fframe.get("kriya") or "").lower()
    if qk in ("own", "have") and fk == "be":
        return owner_of(qframe, fframe)
    if qk == "be" and str(qframe.get("wh_role") or "") == "pred" and (fk == "be" or fk in LINKING_VERBS):
        # 4.9.238: an attribute question is answered by a value of the attribute (lexicon), through "be" or a linking verb
        attr = attribute_of(qframe, fframe)
        if attr:
            return attr
    if qk == "do" and str(qframe.get("wh_role") or "") == "karma" and fk not in ("be", "have", "do", "") and is_gap(qframe.get("karma")):
        return pro_verb(qframe, fframe)
    role = str(qframe.get("wh_role") or "")
    qc, qn = contain_roles(qframe)
    fc, fn = contain_roles(fframe)
    fpol = fframe.get("polarity") or "pos"
    # Containment is one relation read two ways (be+inside, or contain). The kriyā strings differ; the roles do not.
    qmeas = qframe.get("pred") if isinstance(qframe.get("pred"), dict) and qframe["pred"].get("type") == "measure" else None
    fmeas = fframe.get("pred") if isinstance(fframe.get("pred"), dict) and fframe["pred"].get("type") == "measure" else None
    if role in ("polarity", "") and qmeas and fmeas and np_unify(qframe.get("kartr"), fframe.get("kartr")):
        same = str(qmeas.get("num") or "") == str(fmeas.get("num") or "") and str(qmeas.get("unit") or "").lower() == str(fmeas.get("unit") or "").lower() and str(qmeas.get("property") or "").lower() == str(fmeas.get("property") or "").lower()
        if same:
            yes = fpol == (qframe.get("polarity") or "pos")
