WEIGHTS = {"core_state": 0.5, "auxiliary": 0.3, "metadata": 0.2}
HASHES = 32
EMA_ALPHA = 0.2
PREDICT_STEPS = 5
CRITICAL_PHASES = {1, 5, 7, 9}
LAWFUL_STEPS = {0, 1, 8}
MASK_SIM = 0.70
