        "entropy": ent,
        "predicted": predicted,
        "warn_threshold": 1.0,
        "critical_threshold": 2.5,
        "entropy_threshold": 0.8,
        "warn": any(d >= 1.0 for d in vector),
        "critical": any(d >= 2.5 for d in vector),
        "chi": bool(triggers),
        "chi_triggers": triggers,
        "coherence_internal_only": True,
        "admit_gate": False,
        "flag_5_to_8": flag_5,
        "flag_4_to_8": flag_4,
        "categorical_hard_fire": False,
