"""RMC Measurement Kernel v1 — Patch 262J1R-Preflight-C2R.

Shared deterministic measurement functions for the Recursive Manifest Compiler.

This module is intentionally dependency-light and side-effect free. It performs
real readings over the live objects passed into the RMC pipeline: input text,
phase paths, memory nodes, drift reports, resonance vectors, candidates, and
structured trace objects.

It does not call an LLM, query Chroma, read DBs, execute shell, write files,
write memory, mutate canonical references, or touch Identity Vault.

Implemented readings:
    * token and phrase extraction with whole-word boundaries
    * normalized Shannon entropy
    * recursive structure signatures and structural deltas
    * weighted lexical/phase/operator semantic similarity
    * memory fit, ancestry/source confidence, and conflict hints
    * circular Φ1–Φ9 phase deviation
    * resonance variance σ_res from phase vectors
    * drift severity D_score from measured components and taxonomy
    * symbolic ε_s = (σ_res + D_score + |ΔΦ|) / n
    * novelty delta against active memory
    * bounded evolutionary drift check
    * coherence component scoring
"""
from __future__ import annotations

import hashlib
import json
import math
import re
import statistics
from collections import Counter
from typing import Any, Iterable

ENGINE_VERSION = "rmc_measurement_kernel_v1_patch262J1R_preflight_C2R"
ENGINE_MODE = "side_effect_free_real_measurement_kernel"
PHASES = [f"Φ{i}" for i in range(1, 10)]
PHASE_INDEX = {f"Φ{i}": i for i in range(1, 10)}

STOPWORDS = {
    "a", "an", "and", "are", "as", "at", "be", "before", "by", "do", "for",
    "from", "how", "i", "in", "into", "is", "it", "of", "on", "or", "our",
    "that", "the", "their", "this", "to", "we", "what", "when", "where", "with",
    "without", "you", "your",
}

DRIFT_TAXONOMY_PENALTY = {
    "none": 0.0,
    "syntactic": 0.28,
    "evolutionary": 0.35,
    "resonant": 0.50,
    "structural": 0.55,
    "semantic": 0.65,
    "recursive": 0.80,
    "catastrophic": 1.00,
}

TASK_NOVELTY_BUDGETS = {
    "formal_definition": 0.35,
    "coding_patch": 0.30,
    "architecture_design": 0.55,
    "correction_workflow": 0.72,
    "creative_brainstorm": 0.75,
    "public_scientific_claim": 0.25,
    "default": 0.55,
}


def measurement_boundary() -> dict[str, Any]:
    """Return side-effect/security contract for the shared measurement kernel."""
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/measurement_kernel.py",
        "computes_real_readings": True,
        "implemented_readings": [
            "token_boundaries",
            "normalized_shannon_entropy",
            "structure_signature",
            "structure_delta",
            "semantic_distance",
            "memory_fit",
            "source_confidence",
            "conflict_penalty",
            "phase_delta",
            "resonance_variance_sigma_res",
            "drift_severity_D_score",
            "symbolic_epsilon_s",
            "novelty_delta",
            "bounded_evolutionary_drift",
            "coherence_components",
        ],
        "calls_llm": False,
        "queries_chroma": False,
        "reads_db_files": False,
        "executes_shell": False,
        "writes_files": False,
        "writes_rmc_memory": False,
        "writes_identity_vault": False,
        "mutates_canonical_reference": False,
    }


def clamp(value: Any, low: float = 0.0, high: float = 1.0) -> float:
    try:
        v = float(value)
    except Exception:
        v = 0.0
    return max(float(low), min(float(high), v))


def stable_hash(obj: Any) -> str:
    try:
        payload = json.dumps(obj, sort_keys=True, ensure_ascii=False, default=str)
    except Exception:
        payload = str(obj)
    return hashlib.sha256(payload.encode("utf-8", errors="replace")).hexdigest()


def stable_id(prefix: str, obj: Any, n: int = 18) -> str:
    return f"{prefix}_{stable_hash(obj)[:n]}"


def as_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if value in (None, "", {}):
        return []
    return [value]


def stringify(value: Any, *, limit: int = 8000) -> str:
    if isinstance(value, str):
        text = value
    else:
        try:
            text = json.dumps(value, sort_keys=True, ensure_ascii=False, default=str)
        except Exception:
            text = str(value)
    if limit and len(text) > limit:
        return text[:limit]
    return text


def tokens(text: Any) -> list[str]:
    """Return normalized whole-word tokens.

    The regex is boundary-based, so 'or' is not extracted from 'before'.
    """
    return re.findall(r"(?u)\b[\w\u03a6\u03c7]+(?:[-'][\w\u03a6\u03c7]+)?\b", str(text or "").lower())


def content_terms(text: Any, *, include_stopwords: bool = False) -> set[str]:
    out = set()
    for tok in tokens(text):
        if include_stopwords or (tok not in STOPWORDS and len(tok) > 1):
            out.add(tok)
    return out


def ngrams(tok: list[str], n: int) -> set[str]:
    if n <= 0 or len(tok) < n:
        return set()
    return {" ".join(tok[i:i+n]) for i in range(0, len(tok) - n + 1)}


def phrase_terms(text: Any) -> set[str]:
    tok = [t for t in tokens(text) if t not in STOPWORDS]
    return ngrams(tok, 2) | ngrams(tok, 3)


def normalized_shannon_entropy(value: Any) -> float:
    """Compute normalized Shannon entropy over whole-word tokens.

    Returns 0 for empty/single-class input and approaches 1 as token distribution
    becomes more diverse/even.
    """
    tok = tokens(stringify(value, limit=16000))
    if not tok:
        return 0.0
    counts = Counter(tok)
    total = float(sum(counts.values()))
    if total <= 0 or len(counts) <= 1:
        return 0.0
    entropy = -sum((count / total) * math.log2(count / total) for count in counts.values())
    max_entropy = math.log2(len(counts))
    if max_entropy <= 0:
        return 0.0
    return round(clamp(entropy / max_entropy), 6)


def _walk_structure(obj: Any, *, depth: int = 0, max_depth: int = 8) -> dict[str, Any]:
    type_counts: Counter[str] = Counter()
    key_paths: set[str] = set()
    list_lengths: list[int] = []
    scalar_count = 0
    max_seen_depth = depth

    def walk(value: Any, path: str, d: int) -> None:
        nonlocal scalar_count, max_seen_depth
        max_seen_depth = max(max_seen_depth, d)
        if d > max_depth:
            type_counts["truncated"] += 1
            return
        if isinstance(value, dict):
            type_counts["dict"] += 1
            for key, child in value.items():
                key_s = str(key)
                child_path = f"{path}.{key_s}" if path else key_s
                key_paths.add(child_path)
                walk(child, child_path, d + 1)
        elif isinstance(value, list):
            type_counts["list"] += 1
            list_lengths.append(len(value))
            for idx, child in enumerate(value[:50]):
                walk(child, f"{path}[]" if path else "[]", d + 1)
        elif isinstance(value, bool):
            type_counts["bool"] += 1
            scalar_count += 1
        elif isinstance(value, (int, float)) and not isinstance(value, bool):
            type_counts["number"] += 1
            scalar_count += 1
        elif value is None:
            type_counts["null"] += 1
            scalar_count += 1
        else:
            type_counts["string"] += 1
            scalar_count += 1

    walk(obj, "", depth)
    return {
        "type_counts": dict(sorted(type_counts.items())),
        "key_paths": sorted(key_paths),
        "key_count": len(key_paths),
        "max_depth": max_seen_depth,
        "list_count": len(list_lengths),
        "list_lengths_sample": list_lengths[:20],
        "scalar_count": scalar_count,
        "structure_hash": stable_hash({
            "type_counts": dict(sorted(type_counts.items())),
            "key_paths": sorted(key_paths),
            "max_depth": max_seen_depth,
            "list_lengths": list_lengths[:20],
        })[:16],
    }


def structure_signature(obj: Any) -> dict[str, Any]:
    return _walk_structure(obj)


def jaccard_distance(a: Iterable[Any], b: Iterable[Any]) -> float:
    set_a = {str(x) for x in a}
    set_b = {str(x) for x in b}
    if not set_a and not set_b:
        return 0.0
    union = set_a | set_b
    if not union:
        return 0.0
    return round(1.0 - (len(set_a & set_b) / len(union)), 6)


def structure_delta(a: Any, b: Any) -> float:
    sig_a = a if isinstance(a, dict) and "key_paths" in a else structure_signature(a)
    sig_b = b if isinstance(b, dict) and "key_paths" in b else structure_signature(b)
    key_delta = jaccard_distance(sig_a.get("key_paths", []), sig_b.get("key_paths", []))
    types_a = sig_a.get("type_counts", {}) if isinstance(sig_a.get("type_counts"), dict) else {}
    types_b = sig_b.get("type_counts", {}) if isinstance(sig_b.get("type_counts"), dict) else {}
    type_delta = jaccard_distance(types_a.keys(), types_b.keys())
    depth_a = float(sig_a.get("max_depth") or 0.0)
    depth_b = float(sig_b.get("max_depth") or 0.0)
    depth_delta = clamp(abs(depth_a - depth_b) / max(1.0, depth_a, depth_b, 8.0))
    return round(clamp(0.72 * key_delta + 0.18 * type_delta + 0.10 * depth_delta), 6)


def phase_index(phase: Any) -> int | None:
    text = str(phase or "").strip()
    if text in PHASE_INDEX:
        return PHASE_INDEX[text]
    m = re.search(r"(?:Φ|phi)?\s*([1-9])\b", text, flags=re.IGNORECASE)
    if m:
        return int(m.group(1))
    return None


def normalize_phase(phase: Any) -> str | None:
    idx = phase_index(phase)
    return f"Φ{idx}" if idx else None


def phase_path(value: Any) -> list[str]:
    out = []
    for p in as_list(value):
        norm = normalize_phase(p)
        if norm and norm not in out:
            out.append(norm)
    return out


def circular_phase_delta(a: Any, b: Any) -> float:
    ia = phase_index(a)
    ib = phase_index(b)
    if ia is None or ib is None:
        return 0.0
    raw = abs(ib - ia)
    circular = min(raw, 9 - raw)
    return round(clamp(circular / 8.0), 6)


def phase_path_metrics(path: Any) -> dict[str, Any]:
    phases = phase_path(path)
    indexes = [phase_index(p) for p in phases if phase_index(p) is not None]
    deltas = [circular_phase_delta(phases[i], phases[i + 1]) for i in range(len(phases) - 1)]
    avg_delta = round(sum(deltas) / len(deltas), 6) if deltas else 0.0
    max_delta = round(max(deltas), 6) if deltas else 0.0
    warnings: list[dict[str, Any]] = []
    # Illegal export: Φ5 drift to Φ8 projection without Φ6 correction and Φ7 naming before projection.
    if 5 in indexes and 8 in indexes:
        i8 = indexes.index(8)
        before_8 = indexes[:i8]
        if 6 not in before_8 or 7 not in before_8:
            warnings.append({
                "type": "phase_5_to_8_projection_skip",
                "severity": "critical",
                "rule": "Φ5 drift may not project to Φ8 before Φ6 correction and Φ7 naming.",
            })
    if 8 in indexes:
        i8 = indexes.index(8)
        before_8 = indexes[:i8]
        if 6 not in before_8 or 7 not in before_8:
            warnings.append({
                "type": "projection_without_correction_or_naming",
                "severity": "high",
                "rule": "Projection requires Φ6 correction and Φ7 naming first.",
            })
    if 7 in indexes:
        i7 = indexes.index(7)
        if 6 not in indexes[:i7]:
            warnings.append({
                "type": "naming_without_prior_correction",
                "severity": "medium",
                "rule": "Naming should preserve prior Φ6 correction when drift/projection pressure is active.",
            })
    illegal = any(w.get("severity") in {"critical", "high"} for w in warnings)
    return {
        "phase_path": phases,
        "phase_indexes": indexes,
        "transition_deltas": deltas,
        "average_delta_phi": avg_delta,
        "max_delta_phi": max_delta,
        "phase_path_legal": not illegal,
        "phase_warnings": warnings,
        "phase_validity_score": 0.0 if any(w.get("severity") == "critical" for w in warnings) else (0.32 if any(w.get("severity") == "high" for w in warnings) else (0.68 if warnings else 0.92 if phases else 0.45)),
    }


def memory_node_text(node: dict[str, Any]) -> str:
    parts = [
        node.get("content"),
        node.get("content_summary"),
        node.get("summary"),
        node.get("memory_role"),
        node.get("symbolic_signature"),
        node.get("source"),
        node.get("source_path"),
        node.get("chunk_id"),
    ]
    return " | ".join(str(p) for p in parts if p not in (None, ""))


def memory_phase_tags(node: dict[str, Any]) -> list[str]:
    tags = []
    for key in ("phase_tags", "rpmc_phase_tags", "phases"):
        for p in as_list(node.get(key)):
            norm = normalize_phase(p)
            if norm and norm not in tags:
                tags.append(norm)
    # Some content summaries embed Φ tags.
    for m in re.finditer(r"Φ([1-9])", memory_node_text(node)):
        norm = f"Φ{m.group(1)}"
        if norm not in tags:
            tags.append(norm)
    return tags


def _confidence_to_float(value: Any) -> float:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return clamp(value)
    s = str(value or "").lower().strip()
    mapping = {
        "high": 0.92,
        "medium_high": 0.78,
        "medium": 0.62,
        "medium_low": 0.42,
        "low": 0.25,
        "unknown": 0.35,
        "": 0.35,
    }
    return mapping.get(s, 0.50)


def weighted_semantic_similarity(a: Any, b: Any, *, phase_a: Iterable[Any] | None = None, phase_b: Iterable[Any] | None = None, operator_a: Iterable[Any] | None = None, operator_b: Iterable[Any] | None = None) -> float:
    text_a = stringify(a, limit=12000)
    text_b = stringify(b, limit=12000)
    terms_a = content_terms(text_a)
    terms_b = content_terms(text_b)
    phrase_a = phrase_terms(text_a)
    phrase_b = phrase_terms(text_b)
    phase_set_a = set(phase_path(list(phase_a or [])))
    phase_set_b = set(phase_path(list(phase_b or [])))
    op_a = {str(o).lower() for o in (operator_a or []) if str(o).strip()}
    op_b = {str(o).lower() for o in (operator_b or []) if str(o).strip()}

    def jac(sa: set[str], sb: set[str]) -> float:
        if not sa and not sb:
            return 0.0
        if not sa or not sb:
            return 0.0
        return len(sa & sb) / len(sa | sb)

    exact = jac(terms_a, terms_b)
    phrase = jac(phrase_a, phrase_b)
    phase = jac(phase_set_a, phase_set_b)
    ops = jac(op_a, op_b)
    # Weighted lexical/semantic overlap. Deterministic and inspectable.
    return round(clamp(0.50 * exact + 0.20 * phrase + 0.20 * phase + 0.10 * ops), 6)


def semantic_distance(a: Any, b: Any, **kwargs: Any) -> float:
    return round(1.0 - weighted_semantic_similarity(a, b, **kwargs), 6)


def extract_memory_nodes_from_trace(trace_or_report: dict[str, Any]) -> list[dict[str, Any]]:
    if not isinstance(trace_or_report, dict):
        return []
    # Candidate report wraps trace under source_trace_spine.
    if isinstance(trace_or_report.get("source_trace_spine"), dict):
        nested = extract_memory_nodes_from_trace(trace_or_report["source_trace_spine"])
        if nested:
            return nested
    if isinstance(trace_or_report.get("source_candidate_conclusion"), dict):
        nested = extract_memory_nodes_from_trace(trace_or_report["source_candidate_conclusion"])
        if nested:
            return nested
    if isinstance(trace_or_report.get("source_evolutionary_drift"), dict):
        nested = extract_memory_nodes_from_trace(trace_or_report["source_evolutionary_drift"])
        if nested:
            return nested
    symbolic = trace_or_report.get("symbolic_trace") or {}
    if isinstance(symbolic, dict):
        m_t = symbolic.get("M_t") or {}
        if isinstance(m_t, dict) and isinstance(m_t.get("active_memory_nodes"), list):
            return [n for n in m_t.get("active_memory_nodes") if isinstance(n, dict)]
    recall = trace_or_report.get("memory_recall") or {}
    if isinstance(recall, dict):
        state = recall.get("memory_state") or {}
        if isinstance(state, dict) and isinstance(state.get("active_memory_nodes"), list):
            return [n for n in state.get("active_memory_nodes") if isinstance(n, dict)]
    mem_support = trace_or_report.get("source_memory_support") or {}
    if isinstance(mem_support, dict) and isinstance(mem_support.get("linked_memory_nodes"), list):
        return [n for n in mem_support.get("linked_memory_nodes") if isinstance(n, dict)]
    return []


def extract_phase_state_from_trace(trace_or_report: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(trace_or_report, dict):
        return {}
    if isinstance(trace_or_report.get("source_phase_state"), dict):
        return dict(trace_or_report.get("source_phase_state") or {})
    if isinstance(trace_or_report.get("source_trace_spine"), dict):
        return extract_phase_state_from_trace(trace_or_report["source_trace_spine"])
    symbolic = trace_or_report.get("symbolic_trace") or {}
    if isinstance(symbolic, dict) and isinstance(symbolic.get("Φ_t"), dict):
        return dict(symbolic.get("Φ_t") or {})
    phase_report = trace_or_report.get("phase_report") or {}
    if isinstance(phase_report, dict):
        if isinstance(phase_report.get("phase_state"), dict):
            return dict(phase_report.get("phase_state") or {})
        return dict(phase_report)
    return {}


def extract_drift_state_from_trace(trace_or_report: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(trace_or_report, dict):
        return {}
    if isinstance(trace_or_report.get("source_drift_report"), dict) and trace_or_report.get("source_drift_report"):
        return dict(trace_or_report.get("source_drift_report") or {})
    if isinstance(trace_or_report.get("source_trace_spine"), dict):
        drift = extract_drift_state_from_trace(trace_or_report["source_trace_spine"])
        if drift:
            return drift
    drift = trace_or_report.get("drift_report") or {}
    if isinstance(drift, dict) and drift:
        return dict(drift)
    symbolic = trace_or_report.get("symbolic_trace") or {}
    if isinstance(symbolic, dict) and isinstance(symbolic.get("D_t"), dict):
        return dict(symbolic.get("D_t") or {})
    return {}


def extract_phase_vector(trace_or_report: dict[str, Any]) -> dict[str, float]:
    if not isinstance(trace_or_report, dict):
        return {}
    if isinstance(trace_or_report.get("source_trace_spine"), dict):
        nested = extract_phase_vector(trace_or_report["source_trace_spine"])
        if nested:
            return nested
    if isinstance(trace_or_report.get("source_candidate_conclusion"), dict):
        nested = extract_phase_vector(trace_or_report["source_candidate_conclusion"])
        if nested:
            return nested
    resonance = trace_or_report.get("resonance_summary") or {}
    if isinstance(resonance, dict) and isinstance(resonance.get("phase_vector"), dict):
        return {str(k): clamp(v) for k, v in resonance.get("phase_vector", {}).items()}
    return {}


def resonance_variance(phase_vector: dict[str, Any] | None) -> float:
    if not isinstance(phase_vector, dict) or not phase_vector:
        return 0.0
    vals = [clamp(v) for k, v in phase_vector.items() if normalize_phase(k)]
    if len(vals) <= 1:
        return 0.0
    return round(clamp(statistics.pstdev(vals)), 6)


def _drift_taxonomy_from_state(drift_state: dict[str, Any], candidate: dict[str, Any] | None = None, phase_metrics: dict[str, Any] | None = None) -> list[str]:
    names: list[str] = []
    for key in ("drift_taxonomy", "drift_categories", "drift_types", "top_drift_classes", "drift_classes"):
        value = drift_state.get(key) if isinstance(drift_state, dict) else None
        for item in as_list(value):
            if isinstance(item, dict):
                name = str(item.get("type") or item.get("name") or item.get("class") or "").lower()
            else:
                name = str(item or "").lower()
            for known in DRIFT_TAXONOMY_PENALTY:
                if known != "none" and known in name and known not in names:
                    names.append(known)
    if phase_metrics and not phase_metrics.get("phase_path_legal", True):
        if "recursive" not in names:
            names.append("recursive")
    if candidate and str(candidate.get("candidate_kind") or "") == "bounded_evolutionary_candidate":
        if "evolutionary" not in names:
            names.append("evolutionary")
    if not names:
        names = ["none"]
    return names


def taxonomy_penalty(names: Iterable[str]) -> float:
    penalties = []
    for name in names:
        low = str(name or "").lower()
        penalties.append(DRIFT_TAXONOMY_PENALTY.get(low, 0.0))
    return round(clamp(max(penalties) if penalties else 0.0), 6)


def source_confidence(nodes: list[dict[str, Any]]) -> float:
    if not nodes:
        return 0.0
    vals = []
    for node in nodes[:24]:
        conf = _confidence_to_float(node.get("confidence"))
        weight = clamp(node.get("retrieval_weight"), 0.0, 1.0)
        ancestry = 1.0 if node.get("ancestry") or node.get("source_path") or node.get("source") else 0.55
        vals.append(clamp(0.55 * conf + 0.30 * weight + 0.15 * ancestry))
    return round(sum(vals) / max(1, len(vals)), 6)


def memory_relation(candidate: dict[str, Any], nodes: list[dict[str, Any]], candidate_phase_path: list[str] | None = None) -> dict[str, Any]:
    # The compared text is the candidate meaning. Title, rationale, and
    # candidate_kind are labels. Joining them into a short fact ("Tokyo is
    # the capital of Japan") added the token "memory" and held C under 0.87.
    # The coherence weights below are unchanged.
    meaning = str(candidate.get("candidate") or "").strip()
    if meaning:
        text = meaning
    else:
        text = " | ".join(str(candidate.get(k) or "") for k in ("title", "rationale", "candidate_kind"))
    c_path = phase_path(candidate_phase_path or candidate.get("phase_path") or [candidate.get("phase_target")])
    sims = []
    node_summaries = []
    phase_hits: dict[str, int] = {}
    conflict_count = 0
    for node in nodes[:24]:
        n_tags = memory_phase_tags(node)
        n_text = memory_node_text(node)
        sim = weighted_semantic_similarity(text, n_text, phase_a=c_path, phase_b=n_tags)
        sims.append(sim)
        for p in set(c_path) & set(n_tags):
            phase_hits[p] = phase_hits.get(p, 0) + 1
        node_conf = _confidence_to_float(node.get("confidence"))
        prior_drift = clamp(node.get("prior_drift_score"), 0.0, 1.0)
        # Lightweight conflict hint: semantically close, but low confidence/high prior drift.
        if sim >= 0.16 and (node_conf < 0.38 or prior_drift >= 0.70):
            conflict_count += 1
        node_summaries.append({
            "memory_id": node.get("memory_id"),
            "source_kind": node.get("source_kind"),
            "memory_role": node.get("memory_role"),
            "phase_tags": n_tags,
            "retrieval_weight": clamp(node.get("retrieval_weight"), 0.0, 1.0),
            "confidence_numeric": node_conf,
            "similarity": round(sim, 6),
            "prior_drift_score": prior_drift,
        })
    max_sim = max(sims) if sims else 0.0
    avg_top = sum(sorted(sims, reverse=True)[:5]) / max(1, min(5, len(sims))) if sims else 0.0
    # 4.9.235: the texts the claim is compared against, nearest first (the same top-5 avg_top reads).
    ranked = sorted(range(len(sims)), key=lambda i: sims[i], reverse=True)[:5]
    support_texts = [memory_node_text(nodes[i]) for i in ranked]
    # Memory fit uses semantic relation, phase-hit density, retrieval weights, and source confidence.
    retrieval_weights = [clamp(n.get("retrieval_weight"), 0.0, 1.0) for n in nodes[:24]]
    avg_retrieval = sum(retrieval_weights) / max(1, len(retrieval_weights)) if retrieval_weights else 0.0
    phase_density = clamp(sum(phase_hits.values()) / max(1, len(nodes[:24]), len(c_path)))
    src_conf = source_confidence(nodes[:24])
    mem_fit = clamp(0.35 * max_sim + 0.22 * avg_top + 0.18 * phase_density + 0.15 * avg_retrieval + 0.10 * src_conf)
    novelty = clamp(1.0 - max_sim)
    sem_dist = clamp(1.0 - avg_top)
    return {
        "active_memory_count": len(nodes),
        "evaluated_memory_count": min(len(nodes), 24),
        "memory_fit": round(mem_fit, 6),
        "semantic_distance": round(sem_dist, 6),
        "novelty_delta": round(novelty, 6),
        "max_memory_similarity": round(max_sim, 6),
        "avg_top_memory_similarity": round(avg_top, 6),
        "phase_hit_counts": phase_hits,
        "phase_relevance": round(phase_density, 6),
        "average_retrieval_weight": round(avg_retrieval, 6),
        "source_confidence": src_conf,
        "conflict_count": conflict_count,
        "conflict_penalty": round(clamp(conflict_count / max(1, min(len(nodes), 12))) * 0.20, 6),
        "memory_similarity_sample": sorted(node_summaries, key=lambda n: n.get("similarity", 0.0), reverse=True)[:8],
        "support_texts": support_texts,
        "nearest_memory_text": support_texts[0] if support_texts else "",
    }


def infer_task_type(candidate: dict[str, Any], trace_or_report: dict[str, Any] | None = None) -> str:
    """Classify from the candidate's own words.

    A trace dump contains engine filenames and the word "patch". Scanning it
    labeled every ordinary question as a coding patch and shrank the novelty
    budget. An empty candidate still falls back to the trace text.
    """
    own = " ".join([
        str(candidate.get("candidate_kind") or ""),
        str(candidate.get("title") or ""),
        str(candidate.get("candidate") or ""),
    ]).strip()
    text = own.lower() if own else stringify(trace_or_report or {}, limit=1000).lower()
    words = set(re.findall(r"[a-z0-9]+", text))

    def hit(*terms: str) -> bool:
        return any(term in words for term in terms)

    if hit("patch", "code", "module", "compile", "compiler", "verifier"):
        return "coding_patch"
    if hit("correction", "correct", "drift", "repair"):
        return "correction_workflow"
    if hit("definition", "define", "naming", "name"):
        return "formal_definition"
    if hit("public", "scientific", "proof", "claim"):
        return "public_scientific_claim"
    if hit("brainstorm", "creative", "dream"):
        return "creative_brainstorm"
    if hit("architecture", "system", "compiler", "engine"):
        return "architecture_design"
    return "default"


def symbolic_epsilon(sigma_res: float, d_score: float, delta_phi: float, n: int = 3) -> float:
    n_safe = max(1, int(n or 3))
    return round(clamp((clamp(sigma_res) + clamp(d_score) + clamp(delta_phi)) / n_safe), 6)


def relative_entropy(text: Any, support_texts: Iterable[Any]) -> dict[str, Any]:
    """The claim's information that its memory nodes do not carry.

    4.9.235 (plan 229 step 7): normalized_shannon_entropy of a short sentence is ~1.0 for every
    sentence (each word appears once), so it measured length, not drift. Each token carries
    -log2 p(token) bits of the claim's own distribution; the bits whose token appears in a
    support node are carried by memory. The drift term is the claim's normalized entropy times
    the uncarried share of its bits: 0 when the nodes say the same words, the plain entropy when
    they share none.
    """
    tok = tokens(text)
    h_norm = normalized_shannon_entropy(" ".join(tok))
    if not tok:
        return {"entropy_relative": 0.0, "entropy_norm": h_norm, "uncarried_share": 0.0}
    carried_vocab: set[str] = set()
    for support in support_texts or []:
        carried_vocab.update(tokens(support))
    counts = Counter(tok)
    total = float(len(tok))
    bits = {t: -math.log2(c / total) if c < total else 0.0 for t, c in counts.items()}
    all_bits = sum(counts[t] * bits[t] for t in counts)
    if all_bits <= 0:
        share = 0.0 if all(t in carried_vocab for t in counts) else 1.0
    else:
        share = sum(counts[t] * bits[t] for t in counts if t not in carried_vocab) / all_bits
    return {
        "entropy_relative": round(clamp(h_norm * share), 6),
        "entropy_norm": h_norm,
        "uncarried_share": round(clamp(share), 6),
    }


_ARTICLE = {"an": "a"}


def sentence_form(text: Any) -> list[str]:
    """The sentence's function-word skeleton: stopwords kept, each run of content words is one slot."""
    out: list[str] = []
    for tok in tokens(text):
        tok = _ARTICLE.get(tok, tok)
        if tok in STOPWORDS:
            out.append(tok)
        elif not out or out[-1] != "_":
            out.append("_")
    return out


def form_delta(text: Any, other: Any) -> float:
    """Jaccard distance between two sentences' forms (their 1- to 3-grams of the skeleton)."""
    a, b = sentence_form(text), sentence_form(other)
    grams_a = {" ".join(a[i:i + n]) for n in (1, 2, 3) for i in range(0, max(0, len(a) - n + 1))}
    grams_b = {" ".join(b[i:i + n]) for n in (1, 2, 3) for i in range(0, max(0, len(b) - n + 1))}
    return jaccard_distance(grams_a, grams_b)


def drift_severity_score(*, entropy_score: float, structure_delta_score: float, semantic_distance_score: float, phase_deviation: float, taxonomy_score: float) -> float:
    return round(clamp(
        0.25 * clamp(entropy_score)
        + 0.20 * clamp(structure_delta_score)
        + 0.20 * clamp(semantic_distance_score)
        + 0.20 * clamp(phase_deviation)
        + 0.15 * clamp(taxonomy_score)
    ), 6)


def measure_candidate(candidate: dict[str, Any], trace_or_report: dict[str, Any] | None = None, *, memory_nodes: list[dict[str, Any]] | None = None, phase_state: dict[str, Any] | None = None, drift_state: dict[str, Any] | None = None, phase_vector: dict[str, Any] | None = None) -> dict[str, Any]:
    """Compute real measurement readings for one candidate meaning state."""
    trace = trace_or_report or {}
    nodes = memory_nodes if memory_nodes is not None else extract_memory_nodes_from_trace(trace)
    if not nodes and isinstance(candidate.get("memory_links"), list):
        nodes = [n for n in candidate.get("memory_links", []) if isinstance(n, dict)]
    phase_s = phase_state if phase_state is not None else extract_phase_state_from_trace(trace)
    drift_s = drift_state if drift_state is not None else extract_drift_state_from_trace(trace)
    vector = phase_vector if phase_vector is not None else extract_phase_vector(trace)
    c_path = phase_path(candidate.get("phase_path") or [candidate.get("phase_target")])
    if not c_path:
        c_path = phase_path(phase_s.get("phase_path_hypothesis") or [phase_s.get("phase_primary")])
    p_metrics = phase_path_metrics(c_path)
    mem = memory_relation(candidate, nodes, c_path)
    input_text = " | ".join(str(candidate.get(k) or "") for k in ("title", "candidate", "rationale", "candidate_kind"))
    entropy = normalized_shannon_entropy(input_text)
    sig_candidate = structure_signature(candidate)
    sig_template = structure_signature({
        "candidate_id": "",
        "title": "",
        "candidate": "",
        "candidate_kind": "",
        "phase_target": "Φ1",
        "phase_path": [],
        "memory_links": [],
        "confidence": 0.0,
        "novelty": 0.0,
        "drift": 0.0,
        "allowed_to_continue_to_scoring": False,
    })
    s_delta = structure_delta(sig_candidate, sig_template)
    # 4.9.235 (plan 229 step 7): with memory nodes, drift is read against them. Entropy is the
    # claim's information its nodes do not carry, and structure is the claim's sentence form
    # against the nearest node's form. Without nodes both keep the plain readings above (the
    # candidate's entropy and its shape against the empty candidate template).
    meaning_text = str(candidate.get("candidate") or "").strip() or input_text
    rel = relative_entropy(meaning_text, mem.get("support_texts") or []) if nodes else None
    entropy_term = rel["entropy_relative"] if rel is not None else entropy
    form = form_delta(meaning_text, mem.get("nearest_memory_text") or "") if nodes else None
    structure_term = form if form is not None else s_delta
    sigma = resonance_variance(vector)
    taxonomy = _drift_taxonomy_from_state(drift_s, candidate, p_metrics)
    tax = taxonomy_penalty(taxonomy)
    d_score = drift_severity_score(
        entropy_score=entropy_term,
        structure_delta_score=structure_term,
        semantic_distance_score=mem.get("semantic_distance", 0.0),
        phase_deviation=p_metrics.get("max_delta_phi", 0.0),
        taxonomy_score=tax,
    )
    eps = symbolic_epsilon(sigma, d_score, p_metrics.get("max_delta_phi", 0.0), 3)
    task_type = infer_task_type(candidate, trace)
    novelty_budget = TASK_NOVELTY_BUDGETS.get(task_type, TASK_NOVELTY_BUDGETS["default"])
    novelty_delta = mem.get("novelty_delta", 1.0)
    phase_legal = bool(p_metrics.get("phase_path_legal"))
    bounded = bool(
        novelty_delta > 0.0
        and novelty_delta <= novelty_budget
        and eps <= 0.60
        and phase_legal
        and (bool(nodes) or "hypothesis" in str(candidate.get("candidate_kind") or "").lower())
    )
    circuit = bool(
        eps >= 0.80
        or any(w.get("severity") == "critical" for w in p_metrics.get("phase_warnings", []))
        or "catastrophic" in taxonomy
    )
    chi_required = bool(eps > 0.60 or "recursive" in taxonomy or not phase_legal)
    if circuit:
        chi_action = "circuit_breaker_block_projection_route_to_correction_or_archive"
    elif chi_required:
        chi_action = "route_to_correction_engine"
    elif bounded:
        chi_action = "allow_bounded_exploration"
    else:
        chi_action = "hold_for_review_or_add_memory_support"
    return {
        "measurement_kernel_version": ENGINE_VERSION,
        "candidate_id": candidate.get("candidate_id"),
        "token_count": len(tokens(input_text)),
        "phrase_count": len(phrase_terms(input_text)),
        "entropy_norm": entropy,
        "structure_signature": sig_candidate,
        "structure_delta": s_delta,
        "D_terms": {
            "entropy": entropy_term,
            "entropy_basis": "relative_to_memory_nodes" if rel is not None else "candidate_entropy_no_nodes",
            "uncarried_share": rel["uncarried_share"] if rel is not None else None,
            "structure": structure_term,
            "structure_basis": "sentence_form_vs_nearest_node" if form is not None else "candidate_shape_vs_template_no_nodes",
            "semantic_distance": mem.get("semantic_distance", 0.0),
            "phase_deviation": p_metrics.get("max_delta_phi", 0.0),
            "taxonomy": tax,
            "formula": "0.25*entropy + 0.20*structure + 0.20*semantic_distance + 0.20*phase_deviation + 0.15*taxonomy",
        },
        "semantic_distance": mem.get("semantic_distance", 0.0),
        "memory_fit": mem.get("memory_fit", 0.0),
        "source_confidence": mem.get("source_confidence", 0.0),
        "conflict_count": mem.get("conflict_count", 0),
        "conflict_penalty": mem.get("conflict_penalty", 0.0),
        "memory_relation": mem,
        "phase_metrics": p_metrics,
        "sigma_res": sigma,
        "drift_taxonomy": taxonomy,
        "taxonomy_penalty": tax,
        "D_score": d_score,
        "epsilon_s": eps,
        "novelty_delta": novelty_delta,
        "task_type": task_type,
        "novelty_budget": novelty_budget,
        "bounded_evolutionary_drift": bounded,
        "circuit_breaker": circuit,
        "chi_t_required": chi_required,
        "chi_t_action": chi_action,
        "reads_actual_candidate": True,
        "reads_actual_memory_nodes": bool(nodes),
        "reads_actual_phase_path": bool(c_path),
        "reads_actual_resonance_vector": bool(vector),
    }


def coherence_components(candidate: dict[str, Any], measurement: dict[str, Any], *, target_novelty: float | None = None) -> dict[str, Any]:
    mem_fit = clamp(measurement.get("memory_fit"))
    phase_validity = clamp((measurement.get("phase_metrics") or {}).get("phase_validity_score"))
    epsilon = clamp(measurement.get("epsilon_s"))
    drift_containment = clamp(1.0 - epsilon)
    source_conf = clamp(measurement.get("source_confidence"))
    novelty_delta = clamp(measurement.get("novelty_delta"))
    budget = clamp(measurement.get("novelty_budget"), 0.05, 1.0)
    target = clamp(target_novelty if target_novelty is not None else min(0.42, budget * 0.72), 0.0, 1.0)
    bounded_novelty_score = clamp(1.0 - abs(novelty_delta - target))
    utility = clamp(_utility_fit_from_candidate(candidate))
    operator_legality = 1.0 if not measurement.get("circuit_breaker") and (measurement.get("phase_metrics") or {}).get("phase_path_legal", False) else 0.0
    conflict_penalty = clamp(measurement.get("conflict_penalty"))
    projection_gate_penalty = 0.0
    phase_path_value = (measurement.get("phase_metrics") or {}).get("phase_path", [])
    if "Φ8" in phase_path_value and not ("Φ6" in phase_path_value and "Φ7" in phase_path_value):
        projection_gate_penalty = 0.25
    if measurement.get("circuit_breaker"):
        projection_gate_penalty = max(projection_gate_penalty, 0.35)
    score = clamp(
        0.24 * mem_fit
        + 0.20 * phase_validity
        + 0.18 * drift_containment
        + 0.14 * source_conf
        + 0.10 * utility
        + 0.08 * bounded_novelty_score
        + 0.06 * operator_legality
        - conflict_penalty
        - projection_gate_penalty
    )
    return {
        "memory_fit": round(mem_fit, 6),
        "phase_validity": round(phase_validity, 6),
        "drift_containment": round(drift_containment, 6),
        "source_confidence": round(source_conf, 6),
        "utility_fit": round(utility, 6),
        "bounded_novelty_score": round(bounded_novelty_score, 6),
        "operator_legality": round(operator_legality, 6),
        "conflict_penalty": round(conflict_penalty, 6),
        "projection_gate_penalty": round(projection_gate_penalty, 6),
        "coherence_score": round(score, 6),
        "formula": "0.24*memory_fit + 0.20*phase_validity + 0.18*drift_containment + 0.14*source_confidence + 0.10*utility_fit + 0.08*bounded_novelty_score + 0.06*operator_legality - conflict_penalty - projection_gate_penalty",
    }


def _utility_fit_from_candidate(candidate: dict[str, Any]) -> float:
    kind = str(candidate.get("candidate_kind") or "").lower()
    title = str(candidate.get("title") or "").lower()
    if "correction" in kind or "correction" in title:
        return 0.88
    if "memory" in kind:
        return 0.84
    if "projection" in kind:
        return 0.58
    if "evolutionary" in kind:
        return 0.70
    if "archive" in kind or "containment" in kind:
        return 0.44
    return 0.62


def measure_trace_summary(trace_or_report: dict[str, Any]) -> dict[str, Any]:
    nodes = extract_memory_nodes_from_trace(trace_or_report)
    phase_state = extract_phase_state_from_trace(trace_or_report)
    drift_state = extract_drift_state_from_trace(trace_or_report)
    vector = extract_phase_vector(trace_or_report)
    path = phase_path(phase_state.get("phase_path_hypothesis") or [phase_state.get("phase_primary")])
    phase_metrics = phase_path_metrics(path)
    entropy = normalized_shannon_entropy(trace_or_report)
    sigma = resonance_variance(vector)
    taxonomy = _drift_taxonomy_from_state(drift_state, None, phase_metrics)
    d_score = drift_severity_score(
        entropy_score=entropy,
        structure_delta_score=0.0,
        semantic_distance_score=0.0,
        phase_deviation=phase_metrics.get("max_delta_phi", 0.0),
        taxonomy_score=taxonomy_penalty(taxonomy),
    )
    return {
        "measurement_kernel_version": ENGINE_VERSION,
        "active_memory_count": len(nodes),
        "phase_metrics": phase_metrics,
        "entropy_norm": entropy,
        "sigma_res": sigma,
        "drift_taxonomy": taxonomy,
        "D_score": d_score,
        "epsilon_s": symbolic_epsilon(sigma, d_score, phase_metrics.get("max_delta_phi", 0.0), 3),
        "source_confidence": source_confidence(nodes),
        "reads_actual_memory_nodes": bool(nodes),
        "reads_actual_phase_path": bool(path),
        "reads_actual_resonance_vector": bool(vector),
    }

files.rmc_engine_v1/memory_clauses.py:
"""Memory as clauses (plan 229 step 3, v4.9.231).

The phone parses each remembered or recalled sentence with its own grammar (src/qframe.js
KQFrame.clause, schema forge.clause/v1) and sends the clause beside the row's text. One Ask turn
holds the clauses in a context variable, keyed by row id and by the normalized sentence, so a layer
that meets a recalled node (the world model's Observe) finds the same clause the phone parsed.
A clause counts only when its schema is right and it was parsed from that row's own text.
No model; nothing here answers; nothing is written.
"""
from __future__ import annotations

import contextvars
import re
from typing import Any

SCHEMA = "forge.clause/v1"
KEYS = ("receipts", "phone", "hosted", "anchors", "research")

_REG: contextvars.ContextVar[dict[str, Any] | None] = contextvars.ContextVar("forge_memory_clauses", default=None)


def norm(text: Any) -> str:
    return re.sub(r"\s+", " ", str(text or "")).strip().rstrip(".!?").strip().lower()


def valid(clause: Any, text: Any) -> bool:
    """The phone's schema, parsed from this row's own text (not a clause carried over from another row)."""
    if not isinstance(clause, dict) or clause.get("schema") != SCHEMA:
        return False
    return norm(clause.get("text")) == norm(text)


def sentences(clause: dict[str, Any]) -> list[dict[str, Any]]:
    """The clause records of a row: one per sentence (a one-sentence row is its own record)."""
    if isinstance(clause.get("sentences"), list):
        return [c for c in clause["sentences"] if isinstance(c, dict) and c.get("schema") == SCHEMA]
    return [clause]


def _rows(memory: dict[str, Any]) -> list[tuple[str, dict[str, Any]]]:
    out: list[tuple[str, dict[str, Any]]] = []
    for key in KEYS:
        for row in memory.get(key) or []:
            if isinstance(row, dict):
                out.append((key, row))
    for pool in memory.get("pools") or []:
        if isinstance(pool, dict):
            for row in pool.get("rows") or []:
                if isinstance(row, dict):
                    out.append(("pool:" + str(pool.get("name") or ""), row))
    return out


def begin(payload: dict[str, Any]) -> Any:
    memory = payload.get("memory") if isinstance(payload.get("memory"), dict) else {}
    by_id: dict[str, dict[str, Any]] = {}
    by_text: dict[str, dict[str, Any]] = {}
    stats = {"rows": 0, "with_clause": 0, "valid": 0, "rejected": 0, "parsed_sentences": 0, "unparsed_sentences": 0, "by_store": {}}
    for store, row in _rows(memory):
        text = row.get("text") or row.get("content")
        if not str(text or "").strip():
            continue
        stats["rows"] += 1
        cl = row.get("clause")
        if cl is None:
            continue
        stats["with_clause"] += 1
        if not valid(cl, text):
            stats["rejected"] += 1
            continue
        stats["valid"] += 1
        st = stats["by_store"].setdefault(store, 0)
        stats["by_store"][store] = st + 1
        for s in sentences(cl):
            # 4.9.238: a concessive/causal sentence is counted and indexed by its clauses
            for c in ([x for x in s.get("clauses") if isinstance(x, dict)] if isinstance(s.get("clauses"), list) else [s]):
                stats["parsed_sentences" if c.get("parsed") else "unparsed_sentences"] += 1
                if c.get("parsed"):
                    by_text.setdefault(norm(c.get("text")), c)
        if row.get("id"):
            by_id[str(row["id"])] = cl
        by_text.setdefault(norm(text), cl)
    return _REG.set({"by_id": by_id, "by_text": by_text, "stats": stats, "lookups": []})


def end(token: Any) -> None:
    _REG.reset(token)


def lookup(row_id: Any = None, text: Any = None) -> dict[str, Any] | None:
    """The clause the phone parsed for this row (by id, else by its normalized sentence)."""
    reg = _REG.get()
    if not reg:
        return None
    cl = reg["by_id"].get(str(row_id or "")) if row_id else None
    if cl is not None and text is not None and not valid(cl, text):
        # the id's row text and this text differ (a sentence of a longer row): look the sentence up instead
        cl = None
    if cl is None and text is not None:
        cl = reg["by_text"].get(norm(text))
    return cl


def with_place(clause: dict[str, Any], place: dict[str, Any]) -> dict[str, Any]:
    """A copy of the clause (and of each of its sentences) carrying the row's meaning id, phase, band and Hz."""
    out = dict(clause)
    out["place"] = dict(place)
    if isinstance(clause.get("sentences"), list):
        out["sentences"] = [dict(c, place=dict(place)) if isinstance(c, dict) else c for c in clause["sentences"]]
    return out


def note(consumer: str, **info: Any) -> None:
    reg = _REG.get()
    if reg is not None:
        reg["lookups"].append(dict({"consumer": consumer}, **info))


def summary() -> dict[str, Any]:
    reg = _REG.get()
    if not reg:
        return {"schema": SCHEMA, "active": False}
    return {"schema": SCHEMA, "active": True, **reg["stats"], "uses": reg["lookups"][:12], "calls_llm": False}

files.rmc_engine_v1/memory_recaller.py:
"""RMC Memory Recaller + Trace Spine v1.

Patch 262J1R-Preflight-B6 begins the real RMC application spine by adding
read-only memory recall and trace assembly on top of the already-installed
Phase Parser, Resonance Lexicon, Drift Analyzer, and dataset/reference surfaces.

This module is intentionally not an LLM hook. It does not render final
language, approve output, write memory, mutate datasets, query Chroma or any
vector store, execute shell, or touch Identity Vault. The withdrawn legacy
retrieval parameters remain refusal inputs only. Its job is to assemble the
trace inputs the RMC needs before Candidate Generation can become trustworthy.

Core doctrine:
    Input Event -> Phase Parser -> Memory Recaller -> Drift Analyzer ->
    Candidate Generator -> Coherence -> Correction/Naming -> Manifest ->
    Renderer -> Echo Validator -> Memory Writer

This module implements the read-only Memory Recaller and an early Trace Spine
object through the Drift Analyzer stage. Downstream C_t/R_t remain explicitly
not implemented here.
"""
from __future__ import annotations

import datetime as _dt
import hashlib
import json
import os
import re
from pathlib import Path
from typing import Any

from rmc_engine_v1.phase_parser import parse_phase
from rmc_engine_v1.resonance_lexicon import analyze_resonance
from rmc_engine_v1.drift_engine import analyze_drift
from rmc_engine_v1.frozen_legacy_boundary import classify_retrieval_request

ENGINE_VERSION = "rmc_memory_recaller_v1_frozen_legacy_containment_v1"
ENGINE_MODE = "read_only_rmc_memory_recaller_trace_spine_filesystem_only"
DEFAULT_FORGE_ROOT = Path("/home/nic/forge")
MAX_TEXT_BYTES = 900_000

PHASES = [f"Φ{i}" for i in range(1, 10)]


def _utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat()


def _forge_root(root: str | Path | None = None) -> Path:
    if root is not None:
        return Path(root).expanduser().resolve()
    env_root = os.environ.get("FORGE_ROOT")
    if env_root:
        return Path(env_root).expanduser().resolve()
    return DEFAULT_FORGE_ROOT


def _sha256_text(text: str) -> str:
    return hashlib.sha256((text or "").encode("utf-8")).hexdigest()


def _stable_id(prefix: str, text: str) -> str:
    return f"{prefix}_{_sha256_text(text)[:18]}"


def _read_text(path: Path, max_bytes: int = MAX_TEXT_BYTES) -> str:
    try:
        with path.open("rb") as f:
            data = f.read(max_bytes)
        return data.decode("utf-8", errors="replace")
    except Exception:
        return ""


def _read_json(path: Path) -> Any:
    text = _read_text(path)
    if not text.strip():
        return None
    try:
        return json.loads(text)
    except Exception:
        return None


def _iter_json_files(path: Path, pattern: str = "*.json", recursive: bool = False, limit: int = 400) -> list[Path]:
    if not path.exists():
        return []
    try:
        files = list(path.rglob(pattern) if recursive else path.glob(pattern))
        files = [p for p in files if p.is_file()]
        # Name order is the write order (m0000, m0001, …). mtime ties on a
        # fast writer, and a reverse mtime walk reads research before the
        # trusted rows. The absolute path is not part of the key.
        def _file_key(p: Path) -> tuple[str, str]:
            try:
                rel = str(p.resolve().relative_to(path.resolve()))
            except Exception:
                rel = p.name
            return (p.name, rel)
        files.sort(key=_file_key)
        return files[:limit]
    except Exception:
        return []


def _coerce_phase_list(value: Any) -> list[str]:
    phases: list[str] = []
    if isinstance(value, str):
        raw = re.split(r"[,;|\s]+", value)
        phases = [p.strip() for p in raw if p.strip()]
    elif isinstance(value, list):
        phases = [str(p).strip() for p in value if str(p).strip()]
    elif isinstance(value, dict):
        phases = [str(k).strip() for k in value.keys() if str(k).strip().startswith("Φ")]
    cleaned = []
    for ph in phases:
        ph = ph.replace("Phi", "Φ").replace("phi", "Φ")
        m = re.search(r"(?:Φ|phase[_\s-]?)([1-9])", ph, re.I)
        if m:
            ph = f"Φ{m.group(1)}"
        if ph in PHASES and ph not in cleaned:
            cleaned.append(ph)
    return cleaned


def _phase_state(phase_report: dict[str, Any]) -> dict[str, Any]:
    if isinstance(phase_report.get("phase_state"), dict):
        return phase_report.get("phase_state") or {}
    return phase_report


def _relative(path: Path, root: Path) -> str:
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except Exception:
        return str(path)


def _extract_node_text(data: Any, fallback: str = "") -> str:
    if isinstance(data, dict):
        parts: list[str] = []
        for key in (
            "content", "text", "chunk_text", "chunk_preview", "input", "claim", "summary",
            "filename", "source_filename", "corpus_id", "receipt_id", "memory_role",
            "symbolic_signature", "rpmc_phase_tags", "symbolic_operators", "expected_route",
            "candidate_family", "review_status",
        ):
            if data.get(key) not in (None, "", []):
                parts.append(f"{key}: {data.get(key)}")
        if not parts:
            for k, v in list(data.items())[:18]:
                if isinstance(v, (str, int, float, bool)):
                    parts.append(f"{k}: {v}")
        return " | ".join(parts)[:3000] or fallback
    if isinstance(data, list):
        return " | ".join(_extract_node_text(item) for item in data[:5])[:3000] or fallback
    return str(data or fallback)[:3000]


def _node_from_receipt(path: Path, root: Path, data: dict[str, Any]) -> dict[str, Any]:
    text = _extract_node_text(data, fallback=path.name)
    receipt_id = str(data.get("receipt_id") or path.stem)
    corpus_id = str(data.get("corpus_id") or "")
    phase_tags = _coerce_phase_list(data.get("rpmc_phase_tags") or data.get("phase_tags") or data.get("phase"))
    return {
        "memory_id": _stable_id("mem_receipt", receipt_id + "\n" + str(data.get("text") or data.get("content") or "")),
        "source_kind": "ingestion_receipt",
        "source_path": _relative(path, root),
        "content_summary": text[:700],
        "source": data.get("filename") or data.get("source_filename") or path.name,
        "phase_tags": phase_tags,
        "confidence": "medium_high" if data.get("verification_ok") is not False else "low",
        "ancestry": {
            "receipt_id": receipt_id,
            "corpus_id": corpus_id,
            "collection": data.get("collection") or data.get("collection_name") or "",
            "symbolic_map_path": data.get("symbolic_map_path") or "",
        },
        "prior_drift_score": 0.0 if data.get("verification_ok") is not False else 0.45,
        "memory_role": "source_provenance_receipt",
        "content": str(data.get("text") or data.get("content") or "")[:1200],
        "sfe": data.get("sfe") if isinstance(data.get("sfe"), dict) else None,
        "quarantined": data.get("quarantined") is True or data.get("verification_ok") is False or str(data.get("trust") or "").lower() == "low",
        "sensitive": data.get("sensitive") is True,
        "anchor_placed": data.get("anchor_placed") is True,
        "anchor_ancestor_text": str(data.get("anchor_ancestor_text") or ""),
        "trust": data.get("trust"),
        "tier": data.get("tier"),
        "concepts": data.get("concepts") if isinstance(data.get("concepts"), list) else None,
        "license": data.get("license"),
        "source_url": data.get("source_url"),
        "revision": data.get("revision"),
        "provenance": data.get("provenance") if isinstance(data.get("provenance"), dict) else None,
        "contributor": data.get("contributor"),
        "clause": data.get("clause") if isinstance(data.get("clause"), dict) else None,
        "meaning_id": data.get("meaning_id") if isinstance(data.get("meaning_id"), str) else None,
        "sim": data.get("sim") if isinstance(data.get("sim"), dict) else None,
    }


def _node_from_manifest(path: Path, root: Path, data: dict[str, Any]) -> dict[str, Any]:
    text = _extract_node_text(data, fallback=path.name)
    return {
        "memory_id": _stable_id("mem_manifest", path.name + "\n" + str(data.get("collection") or "") + "\n" + text[:200]),
        "source_kind": "collection_manifest",
        "source_path": _relative(path, root),
        "content_summary": text[:700],
        "source": data.get("collection") or path.name,
        "phase_tags": _coerce_phase_list(data.get("phase_tags") or data.get("phase_path")),
        "confidence": "medium_high",
        "ancestry": {
            "collection": data.get("collection") or "",
            "total_chunks": data.get("total_chunks", data.get("collection_total_chunks", 0)),
            "receipts": data.get("receipts", [])[:8] if isinstance(data.get("receipts"), list) else data.get("receipts", ""),
        },
        "prior_drift_score": 0.0,
        "memory_role": "context_collection_manifest",
    }


def _symbolic_entries(data: Any) -> list[dict[str, Any]]:
    """Extract symbolic-map-like entries from several possible schemas."""
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    if not isinstance(data, dict):
        return []
    for key in ("entries", "symbolic_entries", "chunks", "symbolic_map", "map", "records"):
        value = data.get(key)
        if isinstance(value, list):
            return [item for item in value if isinstance(item, dict)]
        if isinstance(value, dict):
            out: list[dict[str, Any]] = []
            for k, v in value.items():
                if isinstance(v, dict):
                    row = dict(v)
                    row.setdefault("chunk_id", k)
                    out.append(row)
            return out
    # Some older maps are dicts keyed by chunk id.
    out = []
    for k, v in data.items():
        if isinstance(v, dict) and any(x in v for x in ("chunk_id", "rpmc_phase_tags", "memory_role", "chunk_preview")):
            row = dict(v)
            row.setdefault("chunk_id", k)
            out.append(row)
    return out


def _nodes_from_symbolic_map(path: Path, root: Path, data: Any, limit: int = 40) -> list[dict[str, Any]]:
    nodes: list[dict[str, Any]] = []
    for entry in _symbolic_entries(data)[:limit]:
        text = _extract_node_text(entry, fallback=path.name)
        phase_tags = _coerce_phase_list(entry.get("rpmc_phase_tags") or entry.get("phase_tags") or entry.get("phase"))
        role = str(entry.get("memory_role") or "symbolic_map_chunk")
        drift_score = 0.0
        if entry.get("drift_terms") or entry.get("collapse_terms"):
            drift_score = 0.25
        nodes.append({
            "memory_id": _stable_id("mem_symbolic", path.name + "\n" + str(entry.get("chunk_id") or "") + "\n" + text[:200]),
            "source_kind": "symbolic_map_entry",
            "source_path": _relative(path, root),
            "chunk_id": entry.get("chunk_id") or entry.get("id") or "",
            "content_summary": text[:850],
            "source": entry.get("source_file") or entry.get("filename") or path.name,
            "phase_tags": phase_tags,
            "confidence": "medium_high",
            "ancestry": {
                "corpus_id": entry.get("corpus_id") or "",
                "sha256_16": entry.get("sha256_16") or "",
                "symbolic_signature": entry.get("symbolic_signature") or "",
            },
            "prior_drift_score": drift_score,
            "memory_role": role,
        })
    return nodes


def _node_from_growth(path: Path, root: Path, data: dict[str, Any]) -> dict[str, Any]:
    text = _extract_node_text(data, fallback=path.name)
    phase_tags = _coerce_phase_list(
        data.get("expected_phase_path") or
        data.get("phase_path") or
        (data.get("phase_summary") or {}).get("phase_path_hypothesis") if isinstance(data.get("phase_summary"), dict) else None
    )
    drift_score = 0.0
    if isinstance(data.get("drift_summary"), dict):
        try:
            drift_score = float(data["drift_summary"].get("epsilon_s") or 0.0)
        except Exception:
            drift_score = 0.0
    kind = "dataset_growth_record"
    parts = set(path.parts)
    if "review_queue" in parts:
        kind = "dataset_review_queue_item"
    elif "candidate_examples" in parts:
        kind = "dataset_candidate_example"
    elif "raw_events" in parts:
        kind = "dataset_raw_event"
    elif "dataset_receipts" in parts:
        kind = "dataset_capture_receipt"
    return {
        "memory_id": _stable_id("mem_growth", path.name + "\n" + str(data.get("candidate_id") or data.get("observation_id") or "") + "\n" + text[:200]),
        "source_kind": kind,
        "source_path": _relative(path, root),
        "content_summary": text[:850],
        "source": data.get("source_kind") or path.name,
        "phase_tags": phase_tags,
        "confidence": "review_required" if kind in ("dataset_candidate_example", "dataset_review_queue_item") else "observation_only",
        "ancestry": {
            "observation_id": data.get("observation_id") or "",
            "candidate_id": data.get("candidate_id") or "",
            "approval": data.get("approval") or (data.get("receipt") or {}).get("approval") if isinstance(data.get("receipt"), dict) else "",
        },
        "prior_drift_score": drift_score,
        "memory_role": kind,
    }


def _collect_candidate_nodes(root: Path, limit_per_source: int = 160) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    memory_root = root / "memory"
    context_root = memory_root / "context_library_v1"
    dataset_root = memory_root / "rmc_dataset_v1"

    nodes: list[dict[str, Any]] = []
    source_counts: dict[str, int] = {}

    for path in _iter_json_files(context_root / "receipts", "*.json", False, limit_per_source):
        data = _read_json(path)
        if isinstance(data, dict):
            nodes.append(_node_from_receipt(path, root, data))
            source_counts["ingestion_receipts"] = source_counts.get("ingestion_receipts", 0) + 1

    for path in _iter_json_files(context_root / "manifests", "*.json", False, limit_per_source):
        data = _read_json(path)
        if isinstance(data, dict):
            nodes.append(_node_from_manifest(path, root, data))
            source_counts["collection_manifests"] = source_counts.get("collection_manifests", 0) + 1

    for path in _iter_json_files(context_root / "symbolic_maps", "*.json", False, min(limit_per_source, 80)):
        data = _read_json(path)
        before = len(nodes)
        nodes.extend(_nodes_from_symbolic_map(path, root, data, limit=40))
        source_counts["symbolic_map_entries"] = source_counts.get("symbolic_map_entries", 0) + (len(nodes) - before)

    for sub in ("review_queue", "candidate_examples", "raw_events", "dataset_receipts"):
        for path in _iter_json_files(dataset_root / sub, "*.json", True, limit_per_source):
            data = _read_json(path)
            if isinstance(data, dict):
                nodes.append(_node_from_growth(path, root, data))
                source_counts[sub] = source_counts.get(sub, 0) + 1

    # Keep deterministic order and cap; final ranking happens later.
    return nodes[:1200], {
        "context_root": str(context_root),
        "dataset_root": str(dataset_root),
        "context_root_exists": context_root.exists(),
        "dataset_root_exists": dataset_root.exists(),
        "candidate_nodes_collected": len(nodes),
        "source_counts": source_counts,
    }


def _context_library_status(root: Path) -> dict[str, Any]:
    context_root = root / "memory" / "context_library_v1"
    dataset_root = root / "memory" / "rmc_dataset_v1"
    subdirs = {
        "context_library_root": context_root,
        "receipts": context_root / "receipts",
        "manifests": context_root / "manifests",
        "symbolic_maps": context_root / "symbolic_maps",
        "indexes": context_root / "indexes",
        "dataset_growth_root": dataset_root,
        "dataset_review_queue": dataset_root / "review_queue",
        "dataset_receipts": dataset_root / "dataset_receipts",
    }
    return {
        name: {
            "path": str(path),
            "exists": path.exists(),
            "file_count": len([p for p in path.rglob("*") if p.is_file()]) if path.exists() and path.is_dir() else 0,
        }
        for name, path in subdirs.items()
    }


def memory_recaller_boundary() -> dict[str, Any]:
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/memory_recaller.py",
        "implements_rmc_stage": "Memory Recaller + Trace Spine through Drift Analyzer",
        "reads_context_library_json": True,
        "reads_dataset_growth_json": True,
        "queries_chroma": False,
        "queries_vector_store": False,
        "semantic_similarity_authority": False,
        "reads_db_files": False,
        "calls_llm": False,
        "executes_shell": False,
        "writes_files": False,
        "writes_rmc_memory": False,
        "writes_identity_vault": False,
        "renders_final_language": False,
        "approved_output": False,
        "normal_runtime_gold_mutation_allowed": False,
        "retrieval_backend_default": "filesystem",
        "supported_retrieval_backends": ["filesystem"],
        "legacy_vector_parameters_are_refusal_inputs": True,
        "fallback_from_blocked_backend_allowed": False,
        "note": "This module builds read-only I_t/M_t/Φ_t/D_t trace inputs from deterministic filesystem sources only.",
    }

def build_input_event(source_text: str, source_metadata: dict[str, Any] | None = None) -> dict[str, Any]:
    source_metadata = source_metadata or {}
    text = str(source_text or "")
    return {
        "event_id": _stable_id("rmc_input_event", text + json.dumps(source_metadata, sort_keys=True, default=str)),
        "raw_input_preview": text[:800],
        "raw_input_sha256": _sha256_text(text),
        "raw_input_length": len(text),
        "conversation_context": source_metadata.get("conversation_context", "adapter_supplied_or_empty"),
        "identity_context": source_metadata.get("identity_context", "forge_operator_context_unprivileged"),
        "session_metadata": {
            "created_at_utc": _utc_now(),
            "source_kind": source_metadata.get("source_kind", "operator_query_input"),
            "selector": source_metadata.get("selector", ""),
            "active_scope": source_metadata.get("active_scope", "unknown"),
        },
    }


def recall_memory(source_text: str, source_metadata: dict[str, Any] | None = None, root: str | Path | None = None, limit: int = 12) -> dict[str, Any]:
    """Build a deterministic filesystem-only active memory set M_t."""
    source_metadata = dict(source_metadata or {})
    root_path = _forge_root(root)
    input_event = build_input_event(source_text, source_metadata)
    phase_report = parse_phase(source_text, source_metadata)
    retrieval_decision = classify_retrieval_request(source_metadata)

    requested_backend = (
        retrieval_decision.get("requested", {}).get("backend")
        if isinstance(retrieval_decision.get("requested"), dict)
        else source_metadata.get("retrieval_backend")
    )
    if retrieval_decision.get("status") != "OK":
        inventory = {
            "context_root": str(root_path / "memory" / "context_library_v1"),
            "dataset_root": str(root_path / "memory" / "rmc_dataset_v1"),
            "context_root_exists": (root_path / "memory" / "context_library_v1").exists(),
            "dataset_root_exists": (root_path / "memory" / "rmc_dataset_v1").exists(),
            "candidate_nodes_collected": 0,
            "source_counts": {},
            "retrieval_backend_requested": requested_backend,
            "retrieval_backend_effective": "none",
            "fallback_performed": False,
        }
        return {
            "status": "BLOCKED",
            "reason_code": retrieval_decision.get("reason_code"),
            "engine_version": ENGINE_VERSION,
            "engine_mode": ENGINE_MODE,
            "stage": "Memory Recaller",
            "input_event": input_event,
            "phase_report_summary": {
                "phase_primary": _phase_state(phase_report).get("phase_primary"),
                "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
                "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
                "confidence": _phase_state(phase_report).get("confidence"),
                "transition_warnings": _phase_state(phase_report).get("transition_warnings", []),
            },
            "memory_state": {
                "M_t_present": False,
                "candidate_nodes_collected": 0,
                "active_memory_count": 0,
                "retrieval_dimensions": ["phase_align", "frame_role", "concept", "copula_hop"],
                "retrieval_backend_requested": requested_backend,
                "retrieval_backend_effective": "none",
                "active_memory_nodes": [],
                "source_counts_collected": {},
                "active_source_kind_counts": {},
                "active_memory_role_counts": {},
                "active_phase_counts": {},
            },
            "legacy_retrieval_request": retrieval_decision,
            "context_library_status": _context_library_status(root_path),
            "inventory": inventory,
            "fallback_performed": False,
            "boundary": memory_recaller_boundary(),
        }

    nodes, inventory = _collect_candidate_nodes(root_path)
    inventory["retrieval_backend_requested"] = requested_backend or "filesystem"
    inventory["retrieval_backend_effective"] = "filesystem"
    inventory["candidate_nodes_collected"] = len(nodes)
    inventory["fallback_performed"] = False

    # 4.9.209 (Nic: everything looks up through phase resonance): the token-overlap ranking
    # branch is removed. Every caller gets resonance recall.
    from rmc_engine_v1.lexicon_resonance import apply_lexicon_phase
    from rmc_engine_v1.resonance_recall import rank_memory
    phase_report = apply_lexicon_phase(phase_report, source_text)
    resonance_report = rank_memory(source_text, nodes, phase_report)
    active = list(resonance_report.get("active") or [])[: max(1, min(int(limit or 12), 50))]
    role_counts: dict[str, int] = {}
    source_counts: dict[str, int] = {}
    phase_counts: dict[str, int] = {}
    for node in active:
        role = str(node.get("memory_role") or "unknown")
        kind = str(node.get("source_kind") or "unknown")
        role_counts[role] = role_counts.get(role, 0) + 1
        source_counts[kind] = source_counts.get(kind, 0) + 1
        for ph in node.get("phase_tags") or []:
            phase_counts[ph] = phase_counts.get(ph, 0) + 1

    return {
        "status": "OK",
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "stage": "Memory Recaller",
        "input_event": input_event,
        "phase_report_summary": {
            "phase_primary": _phase_state(phase_report).get("phase_primary"),
            "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
            "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
            "confidence": _phase_state(phase_report).get("confidence"),
            "transition_warnings": _phase_state(phase_report).get("transition_warnings", []),
        },
        "memory_state": {
            "M_t_present": True,
            "candidate_nodes_collected": inventory.get("candidate_nodes_collected", 0),
            "active_memory_count": len(active),
            "retrieval_dimensions": ["phase_align", "frame_role", "concept", "copula_hop"],
            "retrieval_backend_requested": inventory.get("retrieval_backend_requested"),
            "retrieval_backend_effective": "filesystem",
            "active_memory_nodes": active,
            "source_counts_collected": inventory.get("source_counts", {}),
            "active_source_kind_counts": source_counts,
            "active_memory_role_counts": role_counts,
            "active_phase_counts": phase_counts,
            "recall_method": "resonance",
            "resonance": dict({k: resonance_report.get(k) for k in ("method", "uses_token_overlap", "calls_llm", "question_phi", "question_band", "question_band_name", "question_tuning", "asked", "how", "rsoc", "quarantine", "cite",
                                                       # 4.9.239: phase compatibility recorded apart, on every candidate and every active row
                                                       "question_text_phi", "phase_rule", "candidate_signals")},
                               active_signals=[{"memory_id": a.get("memory_id"), "retrieval_weight": a.get("retrieval_weight"), "signals": a.get("signals")} for a in (resonance_report.get("active") or []) if isinstance(a, dict)][:12]) if resonance_report else None,
            "admitted_for_observe": (resonance_report or {}).get("admitted_for_observe") if resonance_report else None,
        },
        "legacy_retrieval_request": retrieval_decision,
        "context_library_status": _context_library_status(root_path),
        "inventory": inventory,
        "fallback_performed": False,
        "boundary": memory_recaller_boundary(),
    }

def build_trace_spine(source_text: str, source_metadata: dict[str, Any] | None = None, root: str | Path | None = None, limit: int = 12) -> dict[str, Any]:
    """Assemble the read-only RMC trace spine through deterministic memory recall."""
    source_metadata = dict(source_metadata or {})
    input_event = build_input_event(source_text, source_metadata)
    phase_report = parse_phase(source_text, source_metadata)
    resonance_report = analyze_resonance(source_text, source_metadata)
    # Drift stays on the parser report. Placement for recall and candidates is the concept packet.
    drift_report = analyze_drift(phase_report)
    from rmc_engine_v1.lexicon_resonance import apply_lexicon_phase
    phase_report = apply_lexicon_phase(phase_report, source_text)
    memory_report = recall_memory(source_text, source_metadata, root=root, limit=limit)
    from rmc_engine_v1.resonance_recall import settle_subject_phase
    phase_report = settle_subject_phase(phase_report, (memory_report.get("memory_state") or {}).get("active_memory_nodes"))

    if memory_report.get("status") != "OK":
        return {
            "status": "BLOCKED",
            "reason_code": memory_report.get("reason_code"),
            "engine_version": ENGINE_VERSION,
            "engine_mode": "read_only_rmc_trace_spine_filesystem_only",
            "stage": "Trace Spine",
            "input_event": input_event,
            "phase_report": phase_report,
            "memory_recall": memory_report,
            "drift_report": drift_report,
            "symbolic_trace": {
                "I_t": input_event,
                "M_t": {"status": "BLOCKED", "active_memory_count": 0, "active_memory_nodes": []},
                "Φ_t": {
                    "phase_primary": _phase_state(phase_report).get("phase_primary"),
                    "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
                    "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
                    "confidence": _phase_state(phase_report).get("confidence"),
                },
                "D_t": {
                    "drift_report_id": drift_report.get("drift_report_id"),
                    "epsilon_s": drift_report.get("epsilon_s"),
                    "projection_status": drift_report.get("projection_status"),
                },
                "C_t": {"status": "NOT_IMPLEMENTED_IN_B6"},
                "R_t": {"status": "NOT_RENDERED"},
            },
            "trace_spine_readiness": {
                "input_event_present": bool(input_event.get("event_id")),
                "phase_state_present": bool(_phase_state(phase_report).get("phase_primary")),
                "memory_state_present": False,
                "drift_state_present": bool(drift_report.get("drift_report_id")),
                "candidate_generator_present": False,
                "manifest_ready": False,
                "rendering_allowed": False,
                "memory_write_allowed": False,
            },
            "fallback_performed": False,
            "boundary": memory_recaller_boundary(),
        }

    operator_chain = [
        {"stage": "Input Event", "status": "implemented_read_only", "object": "I_t"},
        {"stage": "Phase Parser", "status": "implemented_read_only", "object": "Φ_t"},
        {"stage": "Memory Recaller", "status": "implemented_read_only_filesystem_only", "object": "M_t"},
        {"stage": "Drift Analyzer", "status": "implemented_read_only", "object": "D_t"},
        {"stage": "Candidate Conclusion Generator", "status": "not_implemented_in_B6", "object": "C_t"},
        {"stage": "Renderer", "status": "not_implemented_in_B6", "object": "R_t"},
    ]

    trace = {
        "trace_id": _stable_id("rmctrace", input_event["event_id"] + str(memory_report.get("memory_state", {}).get("active_memory_count", 0))),
        "trace_created_at_utc": _utc_now(),
        "I_t": input_event,
        "M_t": {
            "active_memory_count": memory_report.get("memory_state", {}).get("active_memory_count", 0),
            "active_memory_node_ids": [n.get("memory_id") for n in memory_report.get("memory_state", {}).get("active_memory_nodes", [])],
            "active_memory_nodes": memory_report.get("memory_state", {}).get("active_memory_nodes", []),
        },
        "Φ_t": {
            "phase_primary": _phase_state(phase_report).get("phase_primary"),
            "phase_secondary": _phase_state(phase_report).get("phase_secondary", []),
            "phase_path_hypothesis": _phase_state(phase_report).get("phase_path_hypothesis", []),
            "confidence": _phase_state(phase_report).get("confidence"),
        },
        "O_t": operator_chain,
        "D_t": {
            "drift_report_id": drift_report.get("drift_report_id"),
            "epsilon_s": drift_report.get("epsilon_s"),
            "projection_status": drift_report.get("projection_status"),
            "recommended_action": drift_report.get("recommended_action"),
            "circuit_breaker": drift_report.get("circuit_breaker"),
            "top_drift_classes": drift_report.get("top_drift_classes", [])[:5],
        },
        "C_t": {
            "status": "NOT_IMPLEMENTED_IN_B6",
            "next_required_patch": "B7 or C — Candidate Conclusion Generator Extraction",
        },
        "R_t": {
            "status": "NOT_RENDERED",
            "law": "No output rendering in B6; language remains downstream of manifest/renderer.",
        },
    }

    return {
        "status": "OK",
        "engine_version": ENGINE_VERSION,
        "engine_mode": "read_only_rmc_trace_spine_filesystem_only",
        "stage": "Trace Spine",
        "input_event": input_event,
        "phase_report": phase_report,
        "resonance_summary": {
            "resonance_event_count": len(resonance_report.get("resonance_events", [])),
            "operator_phrase_count": len(resonance_report.get("operator_phrases", [])),
            "circuit_breaker_candidate": resonance_report.get("circuit_breaker_candidate", False),
            "projection_allowed": resonance_report.get("projection_allowed", False),
            "phase_vector": resonance_report.get("phase_vector", {}),
            "violations": resonance_report.get("violations", []),
        },
        "memory_recall": memory_report,
        "drift_report": drift_report,
        "symbolic_trace": trace,
        "trace_spine_readiness": {
            "input_event_present": bool(input_event.get("event_id")),
            "phase_state_present": bool(_phase_state(phase_report).get("phase_primary")),
            "memory_state_present": True,
            "drift_state_present": bool(drift_report.get("drift_report_id")),
            "candidate_generator_present": False,
            "manifest_ready": False,
            "rendering_allowed": False,
            "memory_write_allowed": False,
        },
        "fallback_performed": False,
        "boundary": memory_recaller_boundary(),
    }

files.rmc_engine_v1/memory_writer.py:
"""Memory Writer Dry-Run / W_t engine.

Patch 262J1R-Preflight-C7 creates the write-intent layer that follows Echo
Validation. This module does not write files, mutate RMC memory, update Chroma,
change canonical references, call an LLM, execute shell, or touch Identity
Vault. It computes whether the validated RMC output is eligible for a future
approved memory write and returns a deterministic write plan.

The actual write stage is intentionally deferred to a later gated patch. C7
answers one question only: if this echo-validated render were allowed to become
memory, what exactly would be written, where, under which phase/drift tags, and
why?
"""
from __future__ import annotations

import datetime as _dt
import re
from typing import Any

try:
    from rmc_engine_v1.measurement_kernel import clamp, stable_hash, stable_id
except Exception:  # pragma: no cover - keeps unit tests usable if imported standalone
    import hashlib

    def clamp(value: Any, low: float = 0.0, high: float = 1.0) -> float:
        try:
            number = float(value)
        except Exception:
            number = low
        return max(low, min(high, number))

    def stable_hash(value: Any) -> str:
        return hashlib.sha256(str(value).encode("utf-8", errors="replace")).hexdigest()

    def stable_id(prefix: str, value: Any) -> str:
        return f"{prefix}_{stable_hash(value)[:18]}"

ENGINE_VERSION = "rmc_memory_writer_dry_run_v2_patch262J1R_preflight_C11R_feedback_t"
ENGINE_MODE = "read_only_memory_writer_dry_run_W_t"

REQUIRED_ECHO_FIELDS = [
    "echo_validation_id",
    "source_rendered_output_id",
    "source_manifest_id",
    "echo_score",
    "echo_components",
    "echo_validation_passed",
    "recommended_route",
]

REQUIRED_MEMORY_NODE_FIELDS = [
    "content",
    "source",
    "phase",
    "confidence",
    "ancestry",
    "prior_drift_score",
    "retrieval_weight",
    "tags",
]

REQUIRED_FEEDBACK_FIELDS = [
    "feedback_id",
    "feedback_object_type",
    "feedback_kind",
    "source_trace",
    "source_manifest_id",
    "source_rendered_output_id",
    "source_echo_validation_id",
    "source_memory_node_id",
    "feedback_signal",
    "feedback_status",
    "retrieval_tags",
]


def _utc_now() -> str:
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat()


def _as_dict(value: Any) -> dict[str, Any]:
    return dict(value or {}) if isinstance(value, dict) else {}


def _as_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    if value in (None, "", {}):
        return []
    return [value]


def _text(value: Any, limit: int = 4000) -> str:
    text = str(value or "").strip()
    text = re.sub(r"\s+", " ", text)
    return text[:limit]


def _tokens(value: Any) -> set[str]:
    return {tok for tok in re.findall(r"[a-z0-9_]+", str(value or "").lower()) if len(tok) > 2}


def _round(value: Any, places: int = 6) -> float:
    return round(clamp(value), places)


def memory_writer_boundary() -> dict[str, Any]:
    return {
        "engine_version": ENGINE_VERSION,
        "engine_mode": ENGINE_MODE,
        "engine_module_location": "forge/rmc_engine_v1/memory_writer.py",
        "implements_rmc_stage": "Memory Writer Dry-Run / W_t",
        "input_contract": "C6_echo_validation_report_with_optional_V_t",
        "output_contract": "dry_run_memory_write_plan_or_blocked_write_candidate",
        "actual_writer_stage_present": False,
        "approval_required_for_real_write": True,
        "read_only": True,
        "uses_llm": False,
        "queries_chroma": False,
        "reads_db_files": False,
        "executes_shell": False,
        "writes_files": False,
        "writes_rmc_memory": False,
        "writes_identity_vault": False,
        "mutates_canonical_reference": False,
        "approved_output": False,
        "projection_allowed": False,
        "memory_write_allowed": False,
        "read_only_means": "computes write eligibility and exact write plan in response only; performs no mutation",
    }


def memory_writer_schema_contract() -> dict[str, Any]:
    return {
        "memory_writer_symbol": "W_t",
        "formula": "W_t = plan_memory_write(V_t, R_t, μ_t, T_t) if echo_passed and write_eligibility >= threshold",
        "required_source": "C6 V_t echo validation plus C5 R_t render packet and C4 μ_t manifest packet",
        "required_memory_node_fields": list(REQUIRED_MEMORY_NODE_FIELDS),
        "required_feedback_fields": list(REQUIRED_FEEDBACK_FIELDS),
        "feedback_object_contract": "feedback_t is a first-class retrievable object with its own ID, tags, source links, and commit path; user feedback is not fabricated when absent",
        "memory_update_formula": "M_{t+1} = M_t ∪ {T_t, μ_t, R_t, feedback_t}",
        "write_eligibility_formula": (
            "0.30*echo_score + 0.18*manifest_confidence + 0.14*drift_stability "
            "+ 0.12*memory_support + 0.10*schema_integrity + 0.08*phase_closure "
            "+ 0.08*source_confidence - novelty_risk_penalty - distortion_penalty"
        ),
        "dry_run_threshold": 0.72,
        "actual_write_stage": "deferred_to_gated_C8_or_later",
        "axioms_enforced": {
            "no_output_without_trace": True,
            "meaning_precedes_rendering": True,
            "memory_must_be_phase_tagged": True,
            "phase6_closure_before_projection": True,
            "language_is_output_modality_not_core_state": True,
            "echo_validation_before_memory_write": True,
            "feedback_t_is_first_class_object": True,
        },
    }


def _V_t(echo_report: dict[str, Any]) -> dict[str, Any]:
    return _as_dict(echo_report.get("V_t"))


def _render_report(echo_report: dict[str, Any]) -> dict[str, Any]:
    return _as_dict(echo_report.get("source_output_renderer"))


def _render_packet_from_echo(echo_report: dict[str, Any]) -> dict[str, Any]:
    render_report = _render_report(echo_report)
    return _as_dict(render_report.get("render_packet"))


def _manifest_packet_from_echo(echo_report: dict[str, Any]) -> dict[str, Any]:
    render_report = _render_report(echo_report)
    packet = render_report.get("source_manifest_packet")
    if isinstance(packet, dict) and packet:
        return dict(packet)
    source_manifest = _as_dict(render_report.get("source_manifest_compiler"))
    packet = source_manifest.get("manifest_packet")
    return dict(packet or {}) if isinstance(packet, dict) else {}


def _mu_from_echo(echo_report: dict[str, Any]) -> dict[str, Any]:
    return _as_dict(_manifest_packet_from_echo(echo_report).get("μ_t"))


def _drift_status(mu: dict[str, Any]) -> dict[str, Any]:
    return _as_dict(mu.get("drift_status"))


def _memory_links(mu: dict[str, Any]) -> list[dict[str, Any]]:
    return [m for m in _as_list(mu.get("memory_links")) if isinstance(m, dict)]


def _source_confidence(memory_links: list[dict[str, Any]]) -> float:
    if not memory_links:
        return 0.0
    values = []
    for item in memory_links:
        raw = item.get("confidence", item.get("source_confidence", item.get("weight", 0.5)))
        if isinstance(raw, str):
            lowered = raw.lower()
            if lowered in ("high", "canonical", "trusted"):
                raw = 0.9
            elif lowered in ("medium", "moderate"):
                raw = 0.65
            elif lowered in ("low", "weak"):
                raw = 0.35
            else:
                raw = 0.5
        values.append(clamp(raw))
    return round(sum(values) / max(1, len(values)), 6)


def _phase_closure_score(mu: dict[str, Any]) -> float:
    phases = [str(p) for p in _as_list(mu.get("phase_path"))]
    if not phases:
        return 0.0
    has6 = "Φ6" in phases
    has7 = "Φ7" in phases
    has8 = "Φ8" in phases
    if has8 and (not has6 or not has7):
        return 0.0
    if has6 and has7:
        return 1.0
    if has6:
        return 0.72
    return 0.42


def _schema_integrity(render_packet: dict[str, Any], mu: dict[str, Any], V: dict[str, Any]) -> float:
    required_mu = ["claim", "phase_path", "operator_path", "memory_links", "confidence", "novelty", "drift_status", "output_targets"]
    required_render = ["rendered_output_id", "source_manifest_id", "render_mode", "R_t"]
    required_echo = list(REQUIRED_ECHO_FIELDS)
    total = len(required_mu) + len(required_render) + len(required_echo)
    missing = sum(1 for key in required_mu if key not in mu)
    missing += sum(1 for key in required_render if key not in render_packet)
    missing += sum(1 for key in required_echo if key not in V)
    return round(clamp(1.0 - (missing / max(1, total))), 6)


def _drift_stability(mu: dict[str, Any]) -> float:
    drift = _drift_status(mu)
    eps = drift.get("post_epsilon_s", drift.get("epsilon_s", drift.get("measured_epsilon_s", 0.5)))
    if isinstance(eps, dict):
        eps = eps.get("epsilon_s", 0.5)
    return round(clamp(1.0 - clamp(eps)), 6)


def _novelty_risk_penalty(mu: dict[str, Any]) -> float:
    novelty = clamp(mu.get("novelty", 0.0))
    # Novelty beyond 0.70 is not forbidden, but it requires review support.
    return round(max(0.0, novelty - 0.70) * 0.35, 6)


def _distortion_penalty(V: dict[str, Any]) -> float:
    flags = _as_list(V.get("distortion_flags"))
    components = _as_dict(V.get("echo_components"))
    direct = clamp(V.get("distortion_penalty", 0.0))
    component_penalty = 0.0
    if flags:
        component_penalty += min(0.35, 0.07 * len(flags))
    for value in components.values():
        try:
            if float(value) < 0.5:
                component_penalty += 0.025
        except Exception:
            continue
    return round(clamp(max(direct, component_penalty)), 6)


def _memory_support(memory_links: list[dict[str, Any]]) -> float:
    if not memory_links:
        return 0.0
    count_score = clamp(len(memory_links) / 5.0)
    confidence_score = _source_confidence(memory_links)
    return round((0.55 * count_score) + (0.45 * confidence_score), 6)


def _render_content(render_packet: dict[str, Any]) -> str:
    R_t = render_packet.get("R_t")
    if isinstance(R_t, dict):
        # Prefer human-readable fields, then stable compact representation.
        for key in ("text", "summary", "claim", "display", "content"):
            if key in R_t:
                return _text(R_t.get(key), 8000)
    return _text(R_t, 8000)


def _phase_tags(mu: dict[str, Any]) -> list[str]:
    tags = []
    for phase in _as_list(mu.get("phase_path")):
        value = str(phase).strip()
        if value and value not in tags:
            tags.append(value)
    return tags


def _operator_tags(mu: dict[str, Any]) -> list[str]:
    tags = []
    for operator in _as_list(mu.get("operator_path")):
        value = str(operator).strip()
        if value and value not in tags:
            tags.append(value)
    return tags


def _write_class(mu: dict[str, Any], V: dict[str, Any], eligibility: float) -> str:
    drift = _drift_status(mu)
    status = str(drift.get("status") or "").lower()
    if not bool(V.get("echo_validation_passed")):
        return "blocked_echo_failed"
    if eligibility >= 0.86 and "unresolved" not in status:
        return "candidate_trace_memory_high_confidence"
    if eligibility >= 0.72:
        return "candidate_trace_memory_requires_review"
    return "blocked_low_write_eligibility"


