            continue
        seen.add(id(node))
        text = clean_text(node)
        if node.get("anchor_placed"):
            ancestor = str(node.get("anchor_ancestor_text") or "").strip()
            if ancestor and ancestor not in text:
                text = (text + " " + ancestor).strip()
        elif role_locks:
