    chosen = cluster[0]
    if chosen["echo"] < ECHO_MIN:
        failure = _remember_failure(question, now, "SEED-ECHO")
        return dict(base, rule="SEED-ECHO", gap=True, quarantined=True, trace=trace, backoff=failure)
