def plan(question: str, frame: dict[str, Any] | None = None, facts: list[dict[str, Any]] | None = None,
         memory: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    from rmc_engine_v1.sim_karaka import memory_facts, read
